        // Function: Create Dict for JSON Translation Numeric To Literal
        private void CreateDictForJsonTranslationNumericToLiteral()
        {
            // Clear
            dctStrStrItemNumericToLiteral = new Dictionary<string, string>();

            // Add items to dictionary
            dctStrStrItemNumericToLiteral.Add("\"0\"", "\"Zero\"");
            dctStrStrItemNumericToLiteral.Add("\"1\"", "\"One\"");
            dctStrStrItemNumericToLiteral.Add("\"2\"", "\"Two\"");
            dctStrStrItemNumericToLiteral.Add("\"3\"", "\"Three\"");
            dctStrStrItemNumericToLiteral.Add("\"4\"", "\"Four\"");
            dctStrStrItemNumericToLiteral.Add("\"5\"", "\"Five\"");
            dctStrStrItemNumericToLiteral.Add("\"6\"", "\"Six\"");
            dctStrStrItemNumericToLiteral.Add("\"7\"", "\"Seven\"");
            dctStrStrItemNumericToLiteral.Add("\"8\"", "\"Eight\"");
            dctStrStrItemNumericToLiteral.Add("\"9\"", "\"Nine\"");

        }

        private void CreateDictForJsonTranslationFromLiteralToNumeric()
        {
            // Clear
            dctStrStrItemLiteralToNumeric = new Dictionary<string, string>();

            // Add items to dictionary
            dctStrStrItemLiteralToNumeric.Add("Zero", "0");
            dctStrStrItemLiteralToNumeric.Add("One", "1");
            dctStrStrItemLiteralToNumeric.Add("Two", "2");
            dctStrStrItemLiteralToNumeric.Add("Three", "3");
            dctStrStrItemLiteralToNumeric.Add("Four", "4");
            dctStrStrItemLiteralToNumeric.Add("Five", "5");
            dctStrStrItemLiteralToNumeric.Add("Six", "6");
            dctStrStrItemLiteralToNumeric.Add("Seven", "7");
            dctStrStrItemLiteralToNumeric.Add("Eight", "8");
            dctStrStrItemLiteralToNumeric.Add("Nine", "9");
        }

