        // Function: Write To File using 2 arguments
        private void WriteToFile(string sFilePath, string sString)
        {
            // Write to file Encoding different                
            if (CompareStrings(powerShellVersionLoaded, minPS7ver) >= 0)
            {
                // UTF8
                File.WriteAllText(sFilePath, sString);
            }
            else if (CompareStrings(powerShellVersionLoaded, minPS5ver) >= 0)
            {
                // UTF with BOM
                using (var sw = new StreamWriter(sFilePath, false, new UTF8Encoding(true)))
                {
                    sw.WriteLine(sString);
                }
            }
        }

