        // Function: Scale UI
        public void ScaleUI()
        {
            //ModernWpf.MessageBox.Show(currentSSWWindowScale.HeightAdjustInPixels.ToString());

            this.Height = ((double.Parse(currentSSWLanguage.HeightOfWrapperInPixels) + (double.Parse(currentSSWWindowScale.HeightAdjustInPixels))) * (double.Parse(currentSSWWindowScale.Header) / 100));
            this.Width = (double.Parse(currentSSWLanguage.WidthOfWrapperInPixels)) * (double.Parse(currentSSWWindowScale.Header) / 100);

            sScaleSelected = currentSSWWindowScale.Header;


            foreach (ToolTip tt in listAllToolTips)
            {
                tt.FontSize = 14 * ((double.Parse(sScaleSelected)) / 100);
            }

            ColorWindowScalesMenu();

        }

        // Function: Scale UI
        public void FontScaleUI()
        {
            //ModernWpf.MessageBox.Show(currentSSWWindowScale.HeightAdjustInPixels.ToString());

            //this.Height = ((double.Parse(currentSSWLanguage.HeightOfWrapperInPixels) + (double.Parse(currentSSWWindowScale.HeightAdjustInPixels))) * (double.Parse(currentSSWWindowScale.Header) / 100));
            // this.Width = (double.Parse(currentSSWLanguage.WidthOfWrapperInPixels)) * (double.Parse(currentSSWWindowScale.Header) / 100);

            int iFontScaleSelected = Int32.Parse(currentSSWFontScale.Header.ToString());
            int iFontScaleLabelWidthSelected = Int32.Parse(currentSSWFontScale.LabelWidth.ToString());


            foreach (ToolTip tt in listAllToolTips)
            {
                //tt.FontSize = 14 * ((double.Parse(currentSSWFontScale.Header.ToString())) / 100);
            }

            foreach (Image i in listAllImages)
            {
                i.Height = iFontScaleSelected;
            }

            foreach (TextBlock tblck in listAllTextBlocks)
            {
                tblck.FontSize = iFontScaleSelected;
            }
            foreach (Label lbl in listAllLabels)
            {
                lbl.FontSize = iFontScaleSelected;
                lbl.Width = iFontScaleLabelWidthSelected;
            }
            foreach (ComboBox cbo in listAllComboBoxs)
            {
                cbo.FontSize = iFontScaleSelected;
            }
            foreach (CheckBox chk in listAllCheckBoxs)
            {
                float a = float.Parse(iFontScaleSelected.ToString()) / 14f;
                chk.LayoutTransform = new ScaleTransform(1 * a, 1 * a);
            }


            foreach (Cmbchk cc in listAllCmbchks)
            {
                foreach (CheckBox chk in cc.LstChk)
                {
                    //ModernWpf.MessageBox.Show("c:" + iFontScaleSelected.ToString());

                    float a = float.Parse(iFontScaleSelected.ToString()) / 14f;
                    //ModernWpf.MessageBox.Show(a.ToString());
                    chk.LayoutTransform = new ScaleTransform(1 * a, 1 * a);
                }
                cc.MainCmb.FontSize = iFontScaleSelected;
            }

            foreach (TextBox tbox in listAllTextBoxs)
            {
                tbox.FontSize = iFontScaleSelected;
            }

            foreach (Button btn in listAllButtons)
            {

                btn.FontSize = iFontScaleSelected;

                if (btn.Tag == "btnSave")
                {
                    btn.Margin = new Thickness(Int32.Parse(iFontScaleLabelWidthSelected.ToString()), 0, 0, 0);
                }
            }

            ColorFontScalesMenu();

        }

