        // Function: Color Font Scales
        private void ColorFontScalesMenu()
        {
            foreach (MenuItem mi in listMenuItemFS)
            {
                mi.ClearValue(Control.BackgroundProperty);
                mi.ClearValue(Control.ForegroundProperty);
            }

            Brush br = (Brush)new BrushConverter().ConvertFrom("#FFa34054");

            sFontScaleSelected = currentSSWFontScale.Header;

            foreach (MenuItem mi in listMenuItemFS)
            {
                SSWFontScale ca = (SSWFontScale)mi.DataContext;
                if (ca.Header.ToString().Contains(sFontScaleSelected))
                {
                    mi.Foreground = System.Windows.Media.Brushes.White;

                    mi.Background = br;
                }
            }
        }

