        // Function: Setup Wrapper Window Scale
        public void OnGoingWrapperWindowScale()
        {
            menuWindowScale.Items.Clear();
            listMenuItemWS = new List<MenuItem>();

            // For loop to get items
            foreach (var item in arrayJSONWWS)
            {
                try
                {
                    foreach (var item2 in item)
                    {
                        // Try ... Catch
                        try
                        {
                            if (item2.Name.ToString().Trim() == OSLanguage.Trim())
                            {
                                foreach (var item3 in item2)
                                {
                                    foreach (var item4 in item3)
                                    {
                                        MenuItem newMenuItem = new MenuItem();

                                        string h = "";

                                        if (Int32.Parse(item4.Name) < 100)
                                        {
                                            h += sScaleDown + " " + item4.Name + "%";
                                        }
                                        else if (Int32.Parse(item4.Name) == 100)
                                        {
                                            h += sScale + " " + item4.Name + "%";
                                        }
                                        else
                                        {
                                            h += sScaleUp + " " + item4.Name + "%";
                                        }

                                        newMenuItem.Header = h;
                                        SSWWindowScale a = new SSWWindowScale();

                                        foreach (var item5 in item4)
                                        {
                                            try
                                            {
                                                string Code = "";

                                                string Header = "";
                                                string HeightAdjustInPixels = "";

                                                Code = item2.Name.ToString().Trim();
                                                if (item4.Name != null)
                                                {
                                                    Header = item4.Name;
                                                }
                                                if (item5.HeightAdjustInPixels != null)
                                                {
                                                    HeightAdjustInPixels = item5.HeightAdjustInPixels;
                                                }

                                                a = new SSWWindowScale(Code, Header, HeightAdjustInPixels);

                                            }
                                            catch (Exception ex)

                                            {
                                                ModernWpf.MessageBox.Show("Error: " + item3.ToString() + " : " + ex.Message.ToString());
                                            }

                                            newMenuItem.DataContext = a;

                                            newMenuItem.Click += a.WindowScaleFunction;

                                            menuWindowScale.Items.Add(newMenuItem);


                                            listMenuItemWS.Add(newMenuItem);
                                        }
                                    }
                                }
                            }
                        }
                        catch (Exception ex)

                        {
                            //ModernWpf.MessageBox.Show("Error: " + item2.ToString() + " : " + ex.Message.ToString());
                        }
                    }
                }
                catch (Exception ex)
                {
                    //ModernWpf.MessageBox.Show("Error: " + item.ToString() + " : " + ex.Message.ToString());
                }
            }
        }

        // Function: Set Current SSW ToolTip Scale to Default 100

        // Function: Get Language and Set Current SSW Language
        public void GetLanguageAndSetCurrentSSWWindowScaleToWrapperConfigPresetChangeWindowScale(bool getLanguageTF = true)
        {
            if (getLanguageTF == true)
            {
                // Get language
                GetLanguageTwoCharacterOfCurrentOperatingSystem();
            }                       

            // Get currentSSWWindowScale
            foreach (SSWWindowScale sswws in listSSWWindowScale)
            {
                if ((sswws.Code == OSLanguage) & (sswws.Header.Contains(windowScalePreset.ToString())))
                {
                    currentSSWWindowScale = sswws;
                }
            }

            // English default
            if (!listCodeLanguages.Contains(OSLanguage))
            {
                // Set OSLanguage to English
                OSLanguage = "en";

                foreach (SSWWindowScale sswas in listSSWWindowScale)
                {
                    if ((sswas.Code == OSLanguage) & (sswas.Header.Contains(windowScalePreset.ToString())))
                    {
                        currentSSWWindowScale = sswas;
                    }
                }
            }
        }

