        // Function: Load Wrapper Window Scales JSON
        private void LoadWrapperWindowScalesJson()
        {
            // Check if JSON file exists
            if (CheckFileExists(wrapperWindowScalesJSONFilename))
            {
                using (StreamReader r = new StreamReader(wrapperWindowScalesJSONFilename))
                {
                    // String of Json file
                    string stringJson = r.ReadToEnd();

                    // Try to Deserialize to global variable arrayJSON
                    try
                    {
                        arrayJSONWWS = Newtonsoft.Json.JsonConvert.DeserializeObject(stringJson);
                    }
                    // Catch and show error in JSON in MessageBox
                    catch (JsonReaderException ex)
                    {
                        ModernWpf.MessageBox.Show("ERROR! in JSON file: " + wrapperWindowScalesJSONFilename + ": " + ex.Message);
                    }
                }
            }
            // File does not exist
            else
            {
                ModernWpf.MessageBox.Show(wrapperWindowScalesJSONFilename + " " + messageBoxDoesNotExist);
            }
        }

        // Function: Load Wrapper Window Scales JSON
        private void LoadWrapperToolTipScalesJson()
        {
            // Check if JSON file exists
            if (CheckFileExists(wrapperToolTipScalesJSONFilename))
            {
                using (StreamReader r = new StreamReader(wrapperToolTipScalesJSONFilename))
                {
                    // String of Json file
                    string stringJson = r.ReadToEnd();

                    // Try to Deserialize to global variable arrayJSON
                    try
                    {
                        arrayJSONWTS = Newtonsoft.Json.JsonConvert.DeserializeObject(stringJson);
                    }
                    // Catch and show error in JSON in MessageBox
                    catch (JsonReaderException ex)
