        // Function: Setup Wrapper Window Scale Make Menu
        public void SetupWrapperWindowScaleMakeMenu(bool getLanguageTF = true)
        {
            if (getLanguageTF == true)
            {
                // Get Language Two Character of Current OS
                GetLanguageTwoCharacterOfCurrentOperatingSystem();
            }
            
            // Clear
            menuWindowScale.Items.Clear();
            listMenuItemWS = new List<MenuItem>();

            

            // For loop
            foreach (SSWWindowScale sswas in listSSWWindowScale)
            {
                if (OSLanguage.Trim() == sswas.Code.ToString().Trim())
                {
                    MenuItem newMenuItem = new MenuItem();

                    string h = "";

                    if (Int32.Parse(sswas.Header.ToString()) < 100)
                    {
                        h += sScaleDown + " " + sswas.Header.ToString() + "%";

                    }
                    else if (Int32.Parse(sswas.Header.ToString()) == 100)
                    {
                        h += sScale + " " + sswas.Header.ToString() + "%";
                    }
                    else
                    {
                        h += sScaleUp + " " + sswas.Header.ToString() + "%";
                    }

                    newMenuItem.Header = h;

                    newMenuItem.DataContext = sswas;

                    newMenuItem.Click += sswas.WindowScaleFunction;

                    menuWindowScale.Items.Add(newMenuItem);

                    listMenuItemWS.Add(newMenuItem);
                }
                // Default to English
                else if ("en" == sswas.Code.ToString().Trim())
                {

                    MenuItem newMenuItem = new MenuItem();

                    string h = "";

                    if (Int32.Parse(sswas.Header.ToString()) < 100)
                    {
                        h += sScaleDown + " " + sswas.Header.ToString() + "%";

                    }
                    else if (Int32.Parse(sswas.Header.ToString()) == 100)
                    {
                        h += sScale + " " + sswas.Header.ToString() + "%";
                    }
                    else
                    {
                        h += sScaleUp + " " + sswas.Header.ToString() + "%";
                    }

                    newMenuItem.Header = h;

                    newMenuItem.DataContext = sswas;

                    newMenuItem.Click += sswas.WindowScaleFunction;

                    menuWindowScale.Items.Add(newMenuItem);

                    listMenuItemWS.Add(newMenuItem);
                }
            }
        }

        // Function: Setup Wrapper Window Scale Make Menu
        public void SetupWrapperFontScaleMakeMenu()
        {
            // Clear
            menuFontScale.Items.Clear();

            listMenuItemFS = new List<MenuItem>();
            
            // For loop
            foreach (SSWFontScale sswfs in listSSWFontScale)
