        #region Autosave

        // Function: Set Up Auto Save Timer
        private void SetUpAutoSaveTimer()
        {
            // Setup auto save timer 1 second countdown calling 'DoAutoSave'
            autoSaveTimer = new DispatcherTimer(new TimeSpan(0, 0, 1), DispatcherPriority.Background, new EventHandler(DoAutoSave), System.Windows.Application.Current.Dispatcher);
            // Disable timer at beginning
            autoSaveTimer.IsEnabled = false;
        }

        // Function: Do Auto Save
        private void DoAutoSave(object sender, EventArgs e)
        {
            // Countdown
            if (autosaveIntervalInSeconds > 0)
            {
                // Minus the seconds
                autosaveIntervalInSeconds--;

                // Format the seconds to double digits
                int ints1 = autosaveIntervalInSeconds / 60; // minutes
                int ints2 = autosaveIntervalInSeconds % 60; // seconds

                string strs1 = ""; // string for minutes
                string strs2 = ""; // string for seconds

                if (ints1.ToString().Length == 1) // format minutes to 2 digits
                {
                    strs1 = "0" + ints1.ToString();
                }
                else // format to 1 digit
                {
                    strs1 = ints1.ToString();
                }

                if (ints2.ToString().Length == 1) // format seconds to 2 digits
                {
                    strs2 = "0" + ints2.ToString();
                }
                else // format to 1 digit
                {
                    strs2 = ints2.ToString();
                }

                // Display the Autosave header the timer
                menuAutosave.Header = stringTimerMenuAutosaveHeader + " - " + string.Format("{0}:{1}", strs1, strs2);

            }
            // timer = 0 save and add seconds again
            else
            {
                //autosaveTimer.Stop(); // Stop the timer if needed but we continue to loop by adding more seconds at the end of this else clause              

                // If there is a successful import ps1 file - boolOpenPS1Successful is a bool that says you imported so controls are enabled
                if (boolOpenPS1Successful == true)
                {
                    // False all variables for the output
                    FalseAllVariablesBooleanForOutput();

                    // Get the current date.
                    DateTime thisDay = DateTime.Now;
                    string sThisDay = thisDay.ToString();

                    // Network user name
                    string sUserName = System.Security.Principal.WindowsIdentity.GetCurrent().Name;

                    // Machine name
                    string sMachineName = System.Environment.MachineName;

                    // Remove computer name if there is no domain
                    if (sUserName.ToLower().Contains(sMachineName.ToLower()))
                    {
                        sUserName = sUserName.Substring(sUserName.IndexOf("\\") + 1); // start at '\\' to save
                    }

                    // string script output
                    string so = "";

                    string s0 = "##################################################\n";
                    string s1 = "# File: " + autosaveFilename + "\n";
                    string s2 = "# Network\\User Name: " + sUserName + "\n";
                    string s3 = "# Computer Name: " + sMachineName + "\n";
                    string s4 = "# Date & Time: " + sThisDay + "\n";
                    string s5 = "##################################################\n\n";

                    so += s0 + s1 + s2 + s3 + s4 + s5;

                    // scriptTop added
                    so += scriptTop;

                    // Add begin (BEFORE) functions from list
                    if (listStringBefore.Count > 0)
                    {
                        so += Environment.NewLine;
                        foreach (string s in listStringBefore)
                        {
                            if (s.Length > 0)
                            {
                                so += s; // Add function from listStringBefore

                                // Add a new line as long as it is not the last item                            
                                if (s != listStringBefore[listStringBefore.Count() - 1])
                                {
                                    so += Environment.NewLine;
                                }
                            }
                        }
                    }

                    //// Inside
                    //so += Environment.NewLine;

                    // Selected Function Called
                    OutputUncommentedSelectedAllSections();

                    // Unselected Function Called
                    OutputCommentedUnselectedAllSections();

                    // Create Output using above functions
                    string co = CreateOutput();

                    

                    string sectionIA = co.Substring(co.IndexOf(startLineRegionInitialActions) + startLineRegionInitialActions.Length, co.IndexOf(endLineRegionInitialActions) - co.IndexOf(startLineRegionInitialActions) - startLineRegionInitialActions.Length);

                    

                    string editST = scriptTop;

                    //TestOutputWindow testOutputWindow = new TestOutputWindow("hi", 600, 600, editST);
                    //testOutputWindow.Show();

                    string sFindTopLine = "Get-ChildItem -Path $PSScriptRoot\\Module\\Private | ForEach-Object -Process {. $_.FullName}";
                    string sFindBottomLine = "# Global variable if checks failed";

                    sFindTopLine = lineToFindInPS1ToGetTopOfScriptTopLine;
                    sFindBottomLine = lineToFindInPS1ToGetTopOfScriptBottomLine;

                    

                    string topPart = editST.Substring(0, editST.IndexOf(sFindTopLine) + sFindTopLine.Length);

                   

                    string bottomPart = editST.Substring(editST.IndexOf(sFindBottomLine));

                    // Stitch 
                    string scriptTopFinal = topPart + sectionIA + bottomPart;

                    so += scriptTopFinal;

                    // Add Bottom Part
                    string scriptBottomFinal = co.Substring(co.IndexOf(startLineRegionSystemProtection));

                    so += scriptBottomFinal;

                    // Add end (AFTER) functions
                    if (listStringAfter.Count > 0)
                    {
                        foreach (string s in listStringAfter)
                        {
                            if (s.Length > 0)
                            {
                                so += s;
                                // Add new line unless last item in after list
                                if (s != listStringAfter[listStringAfter.Count() - 1])
                                {
                                    so += Environment.NewLine;
                                }
                            }
                        }
                    }

                    // Saving

                    string fileText = so;

                    string fullPathAsPs1Filename = parentFolder + "\\" + autosaveFilename;

                    // Write to File Function
                    WriteToFile(fullPathAsPs1Filename, fileText);
                }

                // Add back the seconds to restart timer
                autosaveIntervalInSeconds += autosaveIntervalInSecondsCopyToAdd;
            }
        }

        #endregion Autosave

