        // Function: Tab select/focus change which fixes 'double refresh' console logic problem
        private void TabControl_SelectionChanged(object sender, SelectionChangedEventArgs e)
        {
            // Console Output Tab is focused
            if (tabConsoleOutput.IsSelected)
            {
                // Refresh console if false
                if (boolAlreadyRefreshed == false)
                {
                    // Output PowerShell
                    OutputPowerShell_Click(null, new RoutedEventArgs());

                    //btnRefreshConsole.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));

                    // Change already refreshed to false
                    boolAlreadyRefreshed = false;
                }
            }
            // Select false every other tab
            else
            {
                boolAlreadyRefreshed = false;
            }
        }

