        // Function: Startup Load Strings For MessageBox Based On Language HARD CODED
        private void GetLanguageStartupLoadStringsForMessageBoxBasedOnLanguage(bool getLanguageTF = true)
        {
            if (getLanguageTF == true)
            { 
                // Get Language
                GetLanguageTwoCharacterOfCurrentOperatingSystem();
            }

            // Russian
            if (OSLanguage == "ru")
            {
                messageBoxDoesNotExist = messageBoxDoesNotExistRU;
                messageBoxFilesMissingClose = messageBoxFilesMissingCloseRU;
                messageBoxMaybeFilesNotUnzippedProperly = messageBoxMaybeFilesNotUnzippedProperlyRU;
            }

            // German
            else if (OSLanguage == "de")
            {
                messageBoxDoesNotExist = messageBoxDoesNotExistDE;
                messageBoxFilesMissingClose = messageBoxFilesMissingCloseDE;
                messageBoxMaybeFilesNotUnzippedProperly = messageBoxMaybeFilesNotUnzippedProperlyDE;
            }

            // Else
            else
            {
                messageBoxDoesNotExist = messageBoxDoesNotExist;
                messageBoxFilesMissingClose = messageBoxFilesMissingClose;
                messageBoxMaybeFilesNotUnzippedProperly = messageBoxMaybeFilesNotUnzippedProperly;
            }
        }

