        // Function: Load Wrapper Config Variables
        private void GetWrapperLocalizationsVariables()
        {
            // For loop to get items
            foreach (var item in arrayJSONWL)
            {
                try
                {
                    foreach (var item2 in item)
                    {
                        // Try ... Catch
                        try
                        {
                            MenuItem newMenuItem = new MenuItem();
                            newMenuItem.Header = item2.Name;
                            SSWLanguage l = new SSWLanguage();

                            foreach (var item3 in item2)
                            {
                                try
                                {
                                    string sCode = "";
                                    string sFolder = "";
                                    string sWidthOfWrapperInPixels = "";
                                    string sHeightOfWrapperInPixels = "";
                                    string sWidthLabelInPixels = "";
                                    string sWidthLabelContextTabInPixels = "";
                                    string sWidthComboBoxInPixels = "";
                                    string sWidthComboBoxSystemTabInPixels = "";
                                    string sWidthComboBoxStartMenuTabInPixels = "";

                                    if (item3.Code != null)
                                    {
                                        sCode = item3.Code;
                                    }
                                    if (item3.Folder != null)
                                    {
                                        sFolder = item3.Folder;
                                    }
                                    if (item3.Code != null)
                                    {
                                        sWidthOfWrapperInPixels = item3.WidthOfWrapperInPixels;
                                    }
                                    if (item3.Code != null)
                                    {
                                        sHeightOfWrapperInPixels = item3.HeightOfWrapperInPixels;
                                    }
                                    if (item3.Code != null)
                                    {
                                        sWidthLabelInPixels = item3.WidthLabelInPixels;
                                    }
                                    if (item3.Code != null)
                                    {
                                        sWidthLabelContextTabInPixels = item3.WidthLabelContextTabInPixels;
                                    }
                                    if (item3.Code != null)
                                    {
                                        sWidthComboBoxInPixels = item3.WidthComboBoxInPixels;
                                    }
                                    if (item3.Code != null)
                                    {
                                        sWidthComboBoxSystemTabInPixels = item3.WidthComboBoxSystemTabInPixels;
                                    }
                                    if (item3.Code != null)
                                    {
                                        sWidthComboBoxStartMenuTabInPixels = item3.WidthComboBoxStartMenuTabInPixels;
                                    }

                                    l = new SSWLanguage(sCode, sFolder, sWidthOfWrapperInPixels, sHeightOfWrapperInPixels, sWidthLabelInPixels, sWidthLabelContextTabInPixels,
                                       sWidthComboBoxInPixels, sWidthComboBoxSystemTabInPixels, sWidthComboBoxStartMenuTabInPixels);
                                }
                                catch (Exception ex)

                                {
                                    ModernWpf.MessageBox.Show("Error: " + item3.ToString() + " : " + ex.Message.ToString());
                                }

                                newMenuItem.Click += l.LanguageFunction;

                                listSSWLanguage.Add(l);

                                menuLanguage.Items.Add(newMenuItem);
                            }
                        }
                        catch (Exception ex)
                        {
                            ModernWpf.MessageBox.Show("Error: " + item2.ToString() + " : " + ex.Message.ToString());
                        }
                    }
                }
                catch (Exception ex)
                {
                    ModernWpf.MessageBox.Show("Error: " + item.ToString() + " : " + ex.Message.ToString());
                }
            }
        }

