        // Function: Change UI tag to other language
        private void ChangeTagToInputLang(string tagLang)
        {
            // Not English and EN based on file - Special condition for EN
            if (CheckFileExists(tagLang) || tagLang == "EN")
            {
                // Not English
                if (tagLang != "EN")
                {
                    using (StreamReader r = new StreamReader(tagLang))
                    {
                        // string to hold tagFilename
                        string stringJSON = r.ReadToEnd();
                        try
                        {
                            // Create dictionary Tag from string stringJson
                            dictTag = JsonConvert.DeserializeObject<Dictionary<string, string>>(stringJSON);
                        }
                        catch (JsonReaderException ex)
                        {
                            ModernWpf.MessageBox.Show("ERROR! in JSON file: " + tagLang + ": " + ex.Message);
                        }
                        catch (JsonSerializationException ex)
                        {
                            ModernWpf.MessageBox.Show("ERROR! in JSON file: " + tagLang + ": " + ex.Message);
                        }
                    }
                }

                // English - use Russian tag file to copy key first value
                else
                {
                    // Build tag.json from ru
                    string fileName = "";
                    string fileNameP1of3 = "Localizations\\";
                    string fileNameP2of3 = "";
                    string fileNameP3of2 = "\\tag.json";

                    foreach (SSWLanguage sswl in listSSWLanguage)
                    {
                        if (sswl.Code == "ru")
                        {
                            fileNameP2of3 = sswl.Folder.ToString();
                            break;
                        }
                    }
                    // complete tag.json
                    fileName = fileNameP1of3 + fileNameP2of3 + fileNameP3of2;

                    // Check file exists
                    if (CheckFileExists(fileName))
                    {
                        using (StreamReader r = new StreamReader(fileName)) // Use Russian 
                        {
                            // string to hold tagFilename
                            string stringJson = r.ReadToEnd();
                            try
                            {
                                // Create dictionary Tag from string stringJson using only keys for both key and value
                                var dictTagHolderTemp = JsonConvert.DeserializeObject<Dictionary<string, string>>(stringJson);
                                // Create second dictionary to temp hold key, key
                                Dictionary<string, string> dictTagHolderTemp2 = new Dictionary<string, string>() { };

                                foreach (KeyValuePair<string, string> entry in dictTagHolderTemp)
                                {
                                    // Key Key
                                    dictTagHolderTemp2.Add(entry.Key, entry.Key);
                                }
                                // Assign dictionary Tag to dictionary Holder 2 that is temp for English
                                dictTag = dictTagHolderTemp2;
                            }
                            catch (JsonReaderException ex)
                            {
                                ModernWpf.MessageBox.Show("ERROR! in JSON file: " + fileName + ": " + ex.Message);
                            }
                        }
                    }
                }

                // Change comboboxs with language tag
                foreach (Section sec in listSections)
                {
                    ChangeTagCmbWidthWithInput(sec.ComboBoxes, tagLang);
                }
            }
        }


        // Function: ChangeTagCmb 
        private void ChangeTagCmbWidthWithInput(List<ComboBox> cmbList, string lang)
        {
            int cmbWidthTag = 155;

            int result = 0;

            if (cmbList == systemSec.ComboBoxes)
            {
                int.TryParse(currentSSWLanguage.WidthComboBoxSystemTabInPixels, out result);
                cmbWidthTag = result;
            }
            //else if (cmbList == startMenuSec.ComboBoxes)
            //{
            //    int.TryParse(currentSSWLanguage.WidthComboBoxSystemTabInPixels, out result);
            //    cmbWidthTag = result;
            //}
            else
            {
                // Normal
                int.TryParse(currentSSWLanguage.WidthComboBoxInPixels, out result);
                cmbWidthTag = result;
            }

            foreach (ComboBox cmb in cmbList)
            {
                cmb.Width = cmbWidthTag;

                foreach (ComboBoxItem cmbItem in cmb.Items)
                {
                    string sTag = "";
                    if (cmbItem.Tag != null)
                    {
                        sTag = cmbItem.Tag.ToString();

                        if (sTag.Contains(" "))
                        {
                            if (sTag.Substring(sTag.LastIndexOf(" ") + 1, 1) == "-")
                            {
                                sTag = sTag.Substring(sTag.LastIndexOf("-") + 1);
                            }
                            else
                            {
                                sTag = sTag.Substring(sTag.LastIndexOf(" ") + 1);
                            }
                        }
                    }

                    if (dictTag.ContainsKey(sTag))
                    {
                        cmbItem.Content = dictTag[sTag];
                    }
                }
            }
        }

