        // Function: Check Windows OS language and change ToolTip, UI and Tag
        public void ChangeToolTipsTagsUIForCurrentLanguage()
        {
            try
            {
                // Clear ToolTips list
                listAllToolTips = new List<ToolTip>();

                int result = 0;
                int.TryParse(currentSSWLanguage.WidthOfWrapperInPixels, out result);

                System.Windows.Application.Current.MainWindow.Width = result;
                gMainWindow.Width = result + 20;

                int.TryParse(currentSSWLanguage.HeightOfWrapperInPixels, out result);
                System.Windows.Application.Current.MainWindow.Height = result;


                string sLocalizationsAndFolder = "Localizations\\" + currentSSWLanguage.Folder + "\\";

                string tooltipFilenameWindows10 = sLocalizationsAndFolder + "tooltip_Windows_10.json";
                string tooltipFilenameWindows11ARM = sLocalizationsAndFolder + "tooltip_Windows_11_ARM.json";
                string tooltipFilenameWindows11 = sLocalizationsAndFolder + "tooltip_Windows_11.json";

                string uiFilename = sLocalizationsAndFolder + "ui.json";
                string tagFilename = sLocalizationsAndFolder + "tag.json";

                // ToolTip
                if (windowsOSVersion == "win10")
                {
                    ChangeToolTipBasedOnInputLang(tooltipFilenameWindows10);
                }
                else if ((windowsOSVersion == "win11") & (ARMLoaded == "yes"))
                {
                    ChangeToolTipBasedOnInputLang(tooltipFilenameWindows11ARM);
                }
                else if ((windowsOSVersion == "win11") & (cpuArch == "ARM64"))
                {
                    ChangeToolTipBasedOnInputLang(tooltipFilenameWindows11ARM);
                }
                else if (windowsOSVersion == "win11")
                {
                    ChangeToolTipBasedOnInputLang(tooltipFilenameWindows11);
                }

                // UI                
                ChangeUIBasedOnInputLang(uiFilename);
                // Menu Window
                foreach (MenuItem mi in listMenuItemWS)
                {
                    SSWWindowScale a = (SSWWindowScale)mi.DataContext;
                    string number = a.Header;

                    string h = "";

                    if (Int32.Parse(number) < 100)
                    {
                        h += sScaleDown + " " + number + "%";
                    }
                    else if (Int32.Parse(number) == 100)
                    {
                        h += sScale + " " + number + "%";
                    }
                    else
                    {
                        h += sScaleUp + " " + number + "%";
                    }

                    mi.Header = h;
                }


                // Tag
                if (OSLanguage == "en")
                {
                    ChangeTagToInputLang("EN");
                }
                else
                {
                    ChangeTagToInputLang(tagFilename);
                }

                tblckStatusBarMessage.Text = statusBarHover;

                ToolTip newToolTip = new ToolTip();
                newToolTip.Content = statusBarHover;

                tblckStatusBarMessage.ToolTip = newToolTip;

                listAllToolTips.Add(newToolTip);

                //tblckStatusBarMessage.ToolTip = statusBarHover;
            }
            catch (Exception ex)
            {
                ModernWpf.MessageBox.Show(ex.Message);
            }

            ScaleUI();
            //FontScaleUI();
            //ToolTipScaleUI();

        }

