        // Function: Get Language and Set Current SSW Language
        public void GetLanguageAndSetCurrentSSWLanguage(bool getLanguageTF = true)
        {
            if (getLanguageTF == true)
            {
                // Get language
                GetLanguageTwoCharacterOfCurrentOperatingSystem();
            }
            
            // Set
            foreach (SSWLanguage sswl in listSSWLanguage)
            {
                if (sswl.Code == OSLanguage)
                {
                    currentSSWLanguage = sswl;
                }
            }

            // If not found set to EN
            if (!listCodeLanguages.Contains(OSLanguage))
            {
                // Set to en
                OSLanguage = "en";

                foreach (SSWLanguage sswl in listSSWLanguage)
                {
                    if (sswl.Code == OSLanguage)
                    {
                        currentSSWLanguage = sswl;
                    }
                }
            }
        }



        // Function: Get Windows OS language and change ToolTip, UI and Tag
        private void GetLanguageAndChange(bool getLanguageTF = true)
        {
            if (getLanguageTF == true)
            {
                // Get language
                GetLanguageTwoCharacterOfCurrentOperatingSystem();
            }            

            foreach (SSWLanguage sswl in listSSWLanguage)
            {
                if (sswl.Code == OSLanguage)
                {
                    currentSSWLanguage = sswl;

                }
            }

            if (!listCodeLanguages.Contains(OSLanguage))
            {
                OSLanguage = "en";

                foreach (SSWLanguage sswl in listSSWLanguage)
                {
                    if (sswl.Code == OSLanguage)
                    {
                        currentSSWLanguage = sswl;
                    }
                }
            }

            ChangeToolTipsTagsUIForCurrentLanguage();
        }

        // Function: Change UI based on Input lang
        private void ChangeUIBasedOnInputLang(string uiLang) // HELP HELP HELP scale ui scale ui
        {
            if (CheckFileExists(uiLang))
            {
                using (StreamReader r = new StreamReader(uiLang))
                {
                    // string string JSON reading from file
                    string stringJSON = r.ReadToEnd();

                    try
                    {
                        // make JSON from stringJSON
                        arrayJSONUI = Newtonsoft.Json.JsonConvert.DeserializeObject(stringJSON);

                        // for loop to go through JSON UI
                        foreach (var item in arrayJSONUI)
                        {
                            if (item.Id == "Menu")
                            {
                                menuImportExportPreset.Header = item.Options.menuImportExportPreset;
                                menuImportPreset.Header = item.Options.menuImportPreset;
                                menuExportPreset.Header = item.Options.menuExportPreset;

                                menuAutosave.Header = item.Options.menuAutosave;
                                stringTimerMenuAutosaveHeader = item.Options.menuAutosave.ToString();

                                menuPresets.Header = item.Options.menuPresets;
                                menuOpposite.Header = item.Options.menuOpposite;
                                menuOppositeTab.Header = item.Options.menuOppositeTab;
                                menuOppositeEverything.Header = item.Options.menuOppositeEverything;
                                menuClear.Header = item.Options.menuClear;
                                menuClearTab.Header = item.Options.menuClearTab;
                                menuClearEverything.Header = item.Options.menuClearEverything;
                                menuTheme.Header = item.Options.menuTheme;
                                menuThemeDark.Header = item.Options.menuThemeDark;
                                menuThemeLight.Header = item.Options.menuThemeLight;
                                menuLanguage.Header = item.Options.menuLanguage;
                                //menuInfo.Header = item.Options.menuInfo;
                                menuAbout.Header = item.Options.menuAbout;
                                menuAccessibility.Header = item.Options.menuAccessibility;
                                menuWindowScale.Header = item.Options.menuWindowScale;
                                menuFontScale.Header = item.Options.menuFontScale;
                                sScale = item.Options.menuScale;
                                sScaleDown = item.Options.menuScaleDown;
                                sScaleUp = item.Options.menuScaleUp;
                                menuDonate.Header = item.Options.menuDonate;
                            }
                            if (item.Id == "Tab")
                            {
                                tabTBSearch.Text = item.Options.tabSearch;
                                tabTBInitialActions.Text = item.Options.tabInitialActions;
                                tabTBSystemProtection.Text = item.Options.tabSystemProtection;
                                tabTBPrivacyTelemetry.Text = item.Options.tabPrivacyTelemetry;
                                tabTBUIPersonalization.Text = item.Options.tabUIPersonalization;
