                                tabTBDefenderSecurity.Text = item.Options.tabDefenderSecurity;
                                tabTBContextMenu.Text = item.Options.tabContextMenu;
                                tabTBUpdatePolicies.Text = item.Options.tabUpdatePolicies;
                                tabTBConsoleOutput.Text = item.Options.tabConsoleOutput;
                            }
                            if (item.Id == "Button")
                            {
                                btnRefreshConsoleOutputPowerShell.Content = item.Options.btnRefreshConsoleOutputPowerShell;
                                btnRunPowerShell.Content = item.Options.btnRunPowerShell;

                                foreach (Section sec in listSections)
                                {
                                    foreach (Tboxtboxtbox ttt in sec.ListTboxtboxtboxSA)
                                    {
                                        List<Button> lbtn = ttt.ListBtns;

                                        foreach (Button btn in lbtn)
                                        {
                                            if (btn.Tag.ToString().Contains("Open"))
