                                }

                                btnSearchSearch.Content = item.Options.btnSearch;
                                btnClearSearch.Content = item.Options.btnClear;
                            }

                            if (item.Id == "StatusBar")
                            {
                                statusBarHover = item.Options.statusBarHover;
                                statusBarPresetLoaded = item.Options.statusBarPresetLoaded;
                                statusBarPresetNotComp = item.Options.statusBarPresetNotComp;
