        #region Theme

        // Function: Check Registry if Light or Dark Theme return int
        private string ReturnLightDarkTheme()
        {
            // Return string
            string sReturnTheme = "light";

            // Make key
            const string userRoot = "HKEY_CURRENT_USER";
            const string subKey = "Software\\Microsoft\\Windows\\CurrentVersion\\Themes\\Personalize";
            const string keyName = userRoot + "\\" + subKey;

            // Get value
            int themeNumber = (int)Registry.GetValue(keyName, "AppsUseLightTheme", 2);

            // Convert to string value
            if (themeNumber == 0)
            {
                sReturnTheme = "dark";
            }

            // Return
            return sReturnTheme;
        }

