        // Function: Add Controls to All Tabs
        private void AddControlsToAllTabs()
        {
            //ClearSectionControlToList();

            // Create Controls for all tabs                
            for (int i = 0; i < listSections.Count; i++)
            {
                AddControlsToTab(listSections[i], listStringSectionsNames[i], listStackPanels[i]);
            }

            AddSectionControlsToList();
        }

