        private void ClearSectionControlToList()
        {
            listAllLabels = new List<Label>();
            listAllComboBoxs = new List<ComboBox>();
            listAllCheckBoxs = new List<CheckBox>();
            listAllCmbchks = new List<Cmbchk>();
            listAllTextBlocks = new List<TextBlock>();
            listAllImages = new List<Image>();
