        // Function: Add Section Controls to list
        private void AddSectionControlsToList()
        {

            //listAllTextBoxs = new List<TextBox>();
            //listAllButtons = new List<Button>();
            // listAllImages = new List<Image>();

            listAllTextBlocks.Add(tabTBConsoleOutput);
            listAllTextBlocks.Add(tabTBSearch);
            listAllTextBlocks.Add(tabTBInitialActions);
            listAllTextBlocks.Add(tabTBSystemProtection);
            listAllTextBlocks.Add(tabTBPrivacyTelemetry);
            listAllTextBlocks.Add(tabTBUIPersonalization);
            listAllTextBlocks.Add(tabTBOneDrive);
            listAllTextBlocks.Add(tabTBSystem);
            listAllTextBlocks.Add(tabTBWSL);
            listAllTextBlocks.Add(tabTBUWP);
            listAllTextBlocks.Add(tabTBGaming);
            listAllTextBlocks.Add(tabTBScheduledTasks);
            listAllTextBlocks.Add(tabTBDefenderSecurity);
            listAllTextBlocks.Add(tabTBContextMenu);
            listAllTextBlocks.Add(tabTBUpdatePolicies);

            listAllImages.Add(iConsoleOutput);
            listAllImages.Add(iSearch);
            listAllImages.Add(iInitialActions);
            listAllImages.Add(iSystemProtection);
            listAllImages.Add(iPrivacyTelemetry);
            listAllImages.Add(iPersonalization);
            listAllImages.Add(iOneDrive);
            listAllImages.Add(iSystem);
            listAllImages.Add(iWSL);
            listAllImages.Add(iUWP);
            listAllImages.Add(iGaming);
            listAllImages.Add(iScheduledTasks);
            listAllImages.Add(iDefenderSecurity);
            listAllImages.Add(iContextMenu);
            listAllImages.Add(iUpdatePolicies);



            foreach (Section sec in listSections)
            {
                foreach (Label lbl in sec.Labels)
                {
                    listAllLabels.Add(lbl);
                }
                foreach (ComboBox cbo in sec.ComboBoxes)
                {
                    listAllComboBoxs.Add(cbo);
                }
                foreach (CheckBox chk in sec.CheckBoxes)
                {
                    listAllCheckBoxs.Add(chk);
                }
                foreach (List<CheckBox> lstchk in sec.DictStringListChk.Values)
                {
                    foreach (CheckBox chk in lstchk)
                    {
                        listAllCheckBoxs.Add(chk);
                    }
                }
                foreach (Cmbchk cc in sec.ListCmbchkPESC)
                {
                    listAllCmbchks.Add(cc);
                }


            }
        }

