        // Function: Add Controls To Tab       
        private void AddControlsToTab(Section sec, string region, StackPanel spSec)
        {
            // Lines           
            int numberLinesCount = 0;

            int result;

            // Change label width
            if (sec == contextMenuSec) // Context Menu
            {
                int.TryParse(currentSSWLanguage.WidthLabelContextTabInPixels, out result);

                lblWidth = result;

                //ModernWpf.MessageBox.Show(lblWidth.ToString());
            }
            else
            {
                int.TryParse(currentSSWLanguage.WidthLabelInPixels, out result);

                lblWidth = result;
            }


            //lblWidth = 500;

            // special combobox width
            int specialCmbWidth = cmbWidth;

            // Stackpanel creation
            StackPanel spColPanel1 = new StackPanel();
            spSec.Children.Add(spColPanel1);

            StackPanel spColPanel2 = new StackPanel();
            spSec.Children.Add(spColPanel2);

            StackPanel spColPanel3 = new StackPanel();
            spSec.Children.Add(spColPanel3);

            // for loop
            for (int w = 0; w < arrayJSON.Count; w++)
            {

                //if (w == arrayJSON.Count - 1)
                //{
                //    ModernWpf.MessageBox.Show(w.ToString());
                //}
                // item is for loop at w
                var item = arrayJSON[w];

                StackPanel sp = new StackPanel
                {
                    Name = "myStackPanel" + numberLinesCount,
                    Orientation = Orientation.Horizontal
                };
                if (numberLinesCount < functionControlsPerColumn)
                {
                    spColPanel1.Children.Add(sp);
                }
                else if (numberLinesCount < functionControlsPerColumn * 2)
                {
                    spColPanel2.Children.Add(sp);
                }
                else if (numberLinesCount < functionControlsPerColumn * 3)
                {
                    spColPanel3.Children.Add(sp);
                }

                // Try ... Catch
                try
                {
                    // Argument counter
                    int argCount = 0;

                    // Normal
                    if (item.Region == region)
                    {
                        // Count number of Arg
                        foreach (var i in item.Arg)
                        {
                            argCount += 1;
                        }

                        // Combobox with required and 2 items Initial Actions
                        if ((item.Control == "cmb") & (item.Required == "true") & (argCount == 2))
                        {
                            // o = item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Function + ";";                          

                            string sCtrlName = item.Function;

                           

                            // Label
                            System.Windows.Controls.Label lbl = new System.Windows.Controls.Label() { Width = lblWidth };
                            lbl.Content = sCtrlName;
                            lbl.Padding = new Thickness(5, 6, 0, 0);

                            // Stackpanel add
                            sp.Children.Add(lbl);

                            // Add to section label list
                            sec.Labels.Add(lbl);

                            // Combobox
                            ComboBox cmb = new ComboBox() { Width = specialCmbWidth };

                            cmb.Tag = item.Function;

                            // First item
                            string sCmbName = item.Function + " -" + item.Arg.Zero.Tag;

                            sCmbName = ReturnLastPartFromInput(sCmbName);

                            ComboBoxItem cmbItem = new ComboBoxItem();
                            cmbItem.Content = sCmbName;
                            // Tag to store entire function name
                            cmbItem.Tag = item.Function + " -" + item.Arg.Zero.Tag;
                            // Add to combobox
                            cmb.Items.Add(cmbItem);

                            // Second
                            // If empty
                            if (item.Arg.One.Tag == "")
                            {
                                sCmbName = item.Function;
                                cmbItem = new ComboBoxItem();
                                cmbItem.Content = sCmbName;

                                // Tag to store entire function name
                                cmbItem.Tag = item.Function;
                            }
                            // Normal with tag
                            else
                            {
                                sCmbName = item.Function + " -" + item.Arg.One.Tag;
                                cmbItem = new ComboBoxItem();
                                cmbItem.Content = ReturnLastPartFromInput(sCmbName);

                                // Tag to store entire function name
                                cmbItem.Tag = sCmbName;
                            }

                            // Add to combobox
                            cmb.Items.Add(cmbItem);

                            // No Third as 2 only combobox
                            CmbRequired cmbRequired = new CmbRequired();

                            List<string> lstStrMainArg = new List<string>() { item.Arg.Zero.Tag.ToString(), item.Arg.One.Tag.ToString() };
                            List<bool> lstBoolCmb1 = new List<bool>() { new bool(), new bool() };
                            cmbRequired = new CmbRequired(item.Function.ToString(), lstStrMainArg, item.RequiredIndex.ToString(), cmb, lstBoolCmb1);

                            // Add cmbRequired to section list
                            sec.ListCmbRequiredIA.Add(cmbRequired);

                            // Add to Stackpanel ComboBox
                            sp.Children.Add(cmb);

                            // Add ComboBox to Section ComboBox
                            sec.ComboBoxes.Add(cmb);

                            // Increment number of lines count
                            numberLinesCount += 1;

                            AddSep(item.Function.ToString(), sp);
                        }

                        // Combobox combobox with 2 items User folders
                        else if ((item.Control == "cmbs") & (item.Required == "false") & (argCount == 2))
                        {
                            // o = item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Function + " -" + item.Arg.One.Tag + ";";                            

                            if (item.Arg2 != null)
                            {
                                string sCtrlName = item.Function;

                                // Label
                                System.Windows.Controls.Label lbl = new System.Windows.Controls.Label() { Width = lblWidth };
                                lbl.Content = sCtrlName;

                                // Combobox
                                ComboBox cmb = new ComboBox() { Width = specialCmbWidth };

                                lbl.Padding = new Thickness(5, 6, 0, 0);
                                sp.Children.Add(lbl);
                                sec.Labels.Add(lbl);

                                // Stackpanel right
                                StackPanel spUFRight = new StackPanel();
                                spUFRight.Orientation = Orientation.Vertical;

                                // cmbs
                                Cmbs cmbs = new Cmbs();

                                List<ComboBox> lstCmb = new List<ComboBox>();

                                // Count number of Arg2
                                int argCount2 = 0;

                                // Count number of Arg2
                                dynamic values = item.Arg2;
                                foreach (dynamic itemArg2 in values)
                                {
                                    argCount2 += 1;
                                }

                                foreach (var itemArg2 in item.Arg2)
                                {
                                    // Go in twice for loop to get item
                                    foreach (dynamic itemitemArg2 in itemArg2)
                                    {
                                        StackPanel spUF = new StackPanel();
