                                        sec.Labels.Add(lblUF);

                                        ComboBox cmbUF = new ComboBox() { Width = item.Arg2ArgWidth };
                                        cmbUF.Tag = itemitemArg2.Function.ToString();

                                        ComboBoxItem cmbItemUF = new ComboBoxItem() { };

                                        foreach (dynamic itemitemitemArg2 in itemitemArg2.Arg)
                                        {
                                            foreach (dynamic itemitemitemitemArg2 in itemitemitemArg2)
                                            {
                                                //string sCmbItem = " -" + itemitemArg2.Function.ToString() + " " + itemitemitemitemArg2.Tag.ToString();
                                                string sCmbItem = item.Function + " -" + itemitemArg2.Function.ToString() + " " + itemitemitemitemArg2.Tag.ToString();

                                                cmbItemUF = new ComboBoxItem() { };
                                                cmbItemUF.Content = ReturnLastPartFromInput(sCmbItem);
                                                cmbItemUF.Tag = sCmbItem;

                                                cmbUF.Items.Add(cmbItemUF);
                                            }
                                        }

                                        // Third Skip
                                        cmbItemUF = new ComboBoxItem() { };
                                        cmbItemUF.Content = sSkip;
                                        cmbItemUF.Tag = sSkip;

                                        cmbUF.Items.Add(cmbItemUF);

                                        spUF.Children.Add(cmbUF);

                                        lstCmb.Add(cmbUF);

                                        sec.ComboBoxes.Add(cmbUF);

                                        spUFRight.Children.Add(spUF);
                                    }
                                }

                                List<string> lstStrMainArg = new List<string>();

                                dynamic values2 = item.Arg;
                                foreach (dynamic itemArg2 in values2)
                                {
                                    foreach (var itemitemArg2 in itemArg2)
                                    {
                                        lstStrMainArg.Add(itemitemArg2.Tag.ToString());
                                    }
                                }

                                cmbs = new Cmbs(item.Function.ToString().Trim(), lstStrMainArg, lstCmb.Count, -1, false, lstCmb, false);
                                // Add to section
                                sec.ListCmbsUF.Add(cmbs);
                                // Add to stackpanel
                                sp.Children.Add(spUFRight);

                                numberLinesCount += 1;

                                AddSep(item.Function.ToString(), sp);
                            }


                        }
                        // Cmb chk Alter for OneDrive
                        else if ((item.Control == "cmbchkalter") & (item.Required == "false") & (argCount == 2))
