                            CheckBox chk = new CheckBox();

                            List<string> lstStrMainArg = new List<string>() { item.Arg.Zero.Tag.ToString(), item.Arg.One.Tag.ToString() };
                            List<bool> lstBoolCmb1 = new List<bool>();

                            int indexOfInstall = 0;

                            for (int i = 0; i < lstStrMainArg.Count; i++)
