        // Function: Get Names of Sections
        private void GetNamesOfSections()
        {
            sInitialActions = initialActionsSec.FindString.Substring(initialActionsSec.FindString.IndexOf(" ")).Trim();
            sSystemProtection = systemProtectionSec.FindString.Substring(systemProtectionSec.FindString.IndexOf(" ")).Trim();
            sPrivacyTelemetry = privacyTelemetrySec.FindString.Substring(privacyTelemetrySec.FindString.IndexOf(" ")).Trim();
            sUIPersonalization = uiPersonalizationSec.FindString.Substring(uiPersonalizationSec.FindString.IndexOf(" ")).Trim();
            sOneDrive = oneDriveSec.FindString.Substring(oneDriveSec.FindString.IndexOf(" ")).Trim();
            sSystem = systemSec.FindString.Substring(systemSec.FindString.IndexOf(" ")).Trim();
            sWSL = wslSec.FindString.Substring(wslSec.FindString.IndexOf(" ")).Trim();
            sUWPApps = uwpAppsSec.FindString.Substring(uwpAppsSec.FindString.IndexOf(" ")).Trim();
            sGaming = gamingSec.FindString.Substring(gamingSec.FindString.IndexOf(" ")).Trim();
            sScheduledTasks = scheduledTasksSec.FindString.Substring(scheduledTasksSec.FindString.IndexOf(" ")).Trim();
            sMicrosoftDefenderSecurity = defenderSecuritySec.FindString.Substring(defenderSecuritySec.FindString.IndexOf(" ")).Trim();
            sContextMenu = contextMenuSec.FindString.Substring(contextMenuSec.FindString.IndexOf(" ")).Trim();
            sUpdatePolicies = updatePoliciesSec.FindString.Substring(updatePoliciesSec.FindString.IndexOf(" ")).Trim();
        }

        // Function: Check if Windows Terminal Installed
        private void CheckIfWindowsTerminalInstalled()
        {
            // Check exists folder path with exe, if found true
            if (CheckFileExists(wtFileExeLocation))
            {
                boolWTInstalled = true;
            }
            // Not found is falses
            else
            {
                boolWTInstalled = false;
            }
        }

