        // Function: Set ToolTip Duration
        private void SetToolTipDuration()
        {
            float ms = toolTipDurationInSeconds * 1000;
            int ms2 = Math.Abs(Convert.ToInt32(ms));

            //ModernWpf.MessageBox.Show(toolTipDurationInSeconds.ToString());
            // ModernWpf.MessageBox.Show(ms2.ToString());
            // Tooltip timeout to infinity


            //ToolTipService.ShowDurationProperty.OverrideMetadata(typeof(DependencyObject), new FrameworkPropertyMetadata(toolTipDurationInSeconds));
            ToolTipService.ShowDurationProperty.OverrideMetadata(
                typeof(DependencyObject), new FrameworkPropertyMetadata(ms2));
        }
        
        // Function: Get CPU Arch
        private void GetCpuArch()
        {
            // Empty string variable cpuArch
            cpuArch = "";

            // Get CPU Architecture
            cpuArch = System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture.ToString();

            // cpuArch = "arm64"; // Testing

            // Uppercase the string
            cpuArch = cpuArch.ToUpper();
        }


        // Function: Get PowerShellVersionsInstalled
        private void GetPowerShellVersionsInstalled()
        {
            string programFilesPath = Environment.ExpandEnvironmentVariables("%ProgramW6432%");

            string powerShellFileExeLocation = programFilesPath + "\\PowerShell\\7\\pwsh.exe";

            if (CheckFileExists(powerShellFileExeLocation))
            {
                powerShellVersion7Installed = "yes";
            }
            // Empty if not found
            else
            {
                powerShellVersion7Installed = "no";
            }

            string systemDirectoryPath = Environment.SystemDirectory;

            powerShellFileExeLocation = systemDirectoryPath + "\\WindowsPowerShell\\v1.0\\powershell.exe";

            if (CheckFileExists(powerShellFileExeLocation))
            {
                powerShellVersion5_1Installed = "yes";
            }
            // Empty if not found
            else
            {
                powerShellVersion5_1Installed = "no";
            }
        }               

        // Function: Load and Setup String Skip Variables
        private void LoadAndSetupStringSkipVariables()
        {
            // List
            List<string> lstStrCode = new List<string>();
            List<string> lstStrFolder = new List<string>();

            // Make lists
            foreach (SSWLanguage sswl in listSSWLanguage)
            {
                lstStrCode.Add(sswl.Code);
                lstStrFolder.Add(sswl.Folder);
            }

            // Make path
            string sLocalizationsPath = "Localizations\\";
            string sTag = "\\tag.json";

            // List
            List<string> lstStrTagFilename = new List<string>();

            // File Name
            string sTagFilename = "";

            // Make list of filenames
            foreach (string str in lstStrFolder)
            {
                sTagFilename = sLocalizationsPath + str + sTag;
                lstStrTagFilename.Add(sTagFilename);
            }

            // For loop going through list of filename
            foreach (string fileName in lstStrTagFilename)
            {
                // Check exist
                if (CheckFileExists(fileName))
                {
                    // RU
                    using (StreamReader r = new StreamReader(fileName))
                    {
                        // string to hold tagFilename
                        string stringJSON = r.ReadToEnd();
                        try
                        {
                            // Create dictionary Tag from string stringJson
                            Dictionary<string, string> dictStrStr = new Dictionary<string, string>();

                            dictStrStr = JsonConvert.DeserializeObject<Dictionary<string, string>>(stringJSON);

                            // Add to list of dictionaries
                            listDictStrStrSkipVariables.Add(dictStrStr);
                        }
                        catch (JsonReaderException ex)
                        {
                            ModernWpf.MessageBox.Show("ERROR! in JSON file: " + fileName + ": " + ex.Message);
                        }
                        catch (JsonSerializationException ex)
                        {
                            ModernWpf.MessageBox.Show("ERROR! in JSON file: " + fileName + ": " + ex.Message);
                        }
                    }
                }
            }

            try
            {
                // For loop to get code
                for (int i = 0; i < listDictStrStrSkipVariables.Count; i++)
                {
                    // Get code at i
                    string sKey = "";
                    sKey = lstStrCode[i];

                    // Get dictionary at i
                    Dictionary<string, string> d = listDictStrStrSkipVariables[i];

                    // Add code and value for the 'Skip'
                    dictStrStrSkipVariables.Add(sKey, d[sSkip]);

                    // Add to list of Skip string variables
                    listStringSkip.Add(d[sSkip]);
                }
            }
            catch (JsonReaderException ex)
            {
                ModernWpf.MessageBox.Show("ERROR! " + ex.Message);
            }
        }

