        // Function: Get EXE version and Display in Title Bar
        private void GetExeVersionAndDisplayInTitleBar()
        {
            // Get version of EXE
            System.Reflection.Assembly assembly = System.Reflection.Assembly.GetExecutingAssembly();
            System.Diagnostics.FileVersionInfo fvi = System.Diagnostics.FileVersionInfo.GetVersionInfo(assembly.Location);
            string version = fvi.FileVersion;
            // Put version in global variable            
            SSWVersion = version.Substring(0, version.LastIndexOf("."));
            // Main title
            this.Title = "Sophia Script Wrapper " + SSWVersion;
        }

        // Function: Compare LTSC Build Numbers
        private void CompareLTSCBuildNumbers()
        {
            int i = Int32.Parse(currentOSBuildNumber);
            if (i >= LTSC2024BN)
            {
                currentOSLTSCYear = "2024";
            }
            else if (i >= LTSC2021BN)
            {
                currentOSLTSCYear = "2021";
            }
            else if (i >= LTSC2019BN)
            {
                currentOSLTSCYear = "2019";
            }
            else
            {
                currentOSLTSCYear = "no";
            }
        }

        private void CompareWindowsBuildsAndDecide()
        {

            string cOSBN = currentOSBuildNumber;

            string cOSBNMajor = currentOSBuildNumberMajor;
            int iCOSBNMajor = (Int32.Parse(cOSBNMajor));
            string cOSBNMinor = currentOSBuildNumberMinor;
            int iCOSBNMinor = (Int32.Parse(cOSBNMinor));

