            int iSSWindows11LTSC2024MinorFromGitHub = (Int32.Parse(SSWindows11LTSC2024MinorFromGitHub));
            int iSSWindows10LTSC2021MinorFromGitHub = (Int32.Parse(SSWindows10LTSC2021MinorFromGitHub));
            int iSSWindows10LTSC2019MinorFromGitHub = (Int32.Parse(SSWindows10LTSC2019MinorFromGitHub));
            int iSSWindows10MinorFromGitHub = (Int32.Parse(SSWindows10MinorFromGitHub));


            if ((cVOS == "win11") && (iCOSBNMajor <= iSSWindows11MajorFromGitHub) && (iCOSBNMinor >= iSSWindows11MinorFromGitHub))
            {

            }
            else if ((cVOS == "win11") && (cLTSC == "2024") && (iCOSBNMinor >= iSSWindows11LTSC2024MinorFromGitHub))
            {

            }
            else if ((cVOS == "win10") && (cLTSC == "2021") && (iCOSBNMinor >= iSSWindows10LTSC2021MinorFromGitHub))
            {

            }
            else if ((cVOS == "win10") && (cLTSC == "2019") && (iCOSBNMinor >= iSSWindows10LTSC2019MinorFromGitHub))
            {

            }
            else if ((cVOS == "win10") && (iCOSBNMinor >= iSSWindows10MinorFromGitHub))
            {

            }
            else
            {
                if (cVOS == "win10")
                {
                    ModernWpf.MessageBox.Show("You Windows is out of date. Please run Windows Update. " + SSWindows10URLFromGitHub);
