        // Function: Get Windows Version by comparing UBR code (No Edition Id Used for now)
        private void GetWinVerAndEditionId()
        {
            // Registry Key
            RegistryKey registryKey = Registry.LocalMachine.OpenSubKey(@"SOFTWARE\Microsoft\Windows NT\CurrentVersion");

            // Get BuildNumber Value
            var buildNumber = registryKey.GetValue("CurrentBuildNumber").ToString(); // UBR to CurrentBuildNumber
                                                                                     //var ubuildNumber = registryKey.GetValue("UBR").ToString(); // UBR to CurrentBuildNumber

            //ModernWpf.MessageBox.Show("b: " + buildNumber + ", U: " + ubuildNumber);

            Version osVersion = Environment.OSVersion.Version;

            int buildNumberMajor = osVersion.Major;
            int buildNumberMinor = osVersion.Minor;

            // Get BuildNumber Value
            //var buildNumberMinor = registryKey.GetValue("MinorVersion").ToString(); // UBR to CurrentBuildNumber

            // Get BuildNumber Value
            //var buildNumberMajor = registryKey.GetValue("MajorVersion").ToString(); // UBR to CurrentBuildNumber

            currentOSBuildNumber = buildNumber;

            currentOSBuildNumberMinor = buildNumberMinor.ToString();

            currentOSBuildNumberMajor = buildNumberMajor.ToString();

            CompareLTSCBuildNumbers();

            // Windows 11
            if (Int32.Parse(buildNumber) >= minWindows11BN)
            {
                windowsOSVersion = "win11";
            }
            // Windows 10
            else if (Int32.Parse(buildNumber) >= minWindows10BN)
            {
                windowsOSVersion = "win10";
            }
            // Else Windows 10
            else
            {
                windowsOSVersion = "win10";
            }

            //// Get EditionID Value
            string editionId = registryKey.GetValue("EditionID").ToString();

            //windowsEditionId = editionId;


            if (editionId.Contains("Pro"))
            {
                currentEditionProEduEnterHome = "Pro";
            }
            else if (editionId.Contains("Education"))
            {
                currentEditionProEduEnterHome = "Education";
            }
            else if (editionId.Contains("Enterprise"))
            {
                currentEditionProEduEnterHome = "Enterprise";
            }
            else if (editionId.Contains("Home"))
            {
                currentEditionProEduEnterHome = "Home";
            }
            else if (editionId.Contains("2019"))
            {
                currentEditionProEduEnterHome = "2019";
            }
            else if (editionId.Contains("2021"))
            {
                currentEditionProEduEnterHome = "2021";
            }
            else if (editionId.Contains("2024"))
            {
                currentEditionProEduEnterHome = "2024";
            }
            //windowsOSVersion = "win11";
            //windowsOSVersion = "win10";
            //sCurrentEditionProEduEnterHome = "2024";
            //ModernWpf.MessageBox.Show(windowsOSVersion + " " + sCurrentEditionProEduEnterHome);
        }

        // Function: Get String Section Names into List
        private void GetStringSectionNamesIntoList()
        {
            // Get the names of regions from FindString variable of each Section
            for (int i = 0; i < listStringSectionsNames.Count; i++)
            {
                listStringSectionsNames[i] = listSections[i].FindString.Substring(listSections[i].FindString.IndexOf(" ") + 1);
            }
        }

        // Function: Load the JSON file
        private void LoadJson(string jsonFilename)
        {
            if (CheckFileExists(jsonFilename))
            {
                using (StreamReader r = new StreamReader(jsonFilename))
                {
                    // String of jsonfile
                    string stringJson = r.ReadToEnd();

                    stringJson = ReplaceStringWithDict(stringJson);

                    //TestOutputWindow tow = new TestOutputWindow("Hello", 450, 1000, stringJson) { };
                    //tow.ShowDialog();

                    // Try to Deserialize to global variable arrayJSON
                    try
                    {
                        arrayJSON = Newtonsoft.Json.JsonConvert.DeserializeObject(stringJson);
                    }
                    // Catch and show error in JSON in MessageBox
                    catch (JsonReaderException ex)
                    {
                        ModernWpf.MessageBox.Show("ERROR! in JSON file: " + jsonFilename + ": " + ex.Message);
                    }
                }
            }

            FindLastFunctionPerTab();
        }

        private void FindLastFunctionPerTab()
        {
            foreach (var item in arrayJSON)
            {
                //ModernWpf.MessageBox.Show(item.Region.ToString());
                //ModernWpf.MessageBox.Show(sInitialActions);

                if (item.Region.ToString() == sInitialActions)
                    sInitialActionsLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sSystemProtection)
                    sSystemProtectionLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sPrivacyTelemetry)
                    sPrivacyLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sUIPersonalization)
                    sPersonalizationLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sOneDrive)
                    sOneDriveLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sSystem)
                    sSystemLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sWSL)
                    sWSLLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sUWPApps)
                    sUWPAppsLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sGaming)
                    sGamingLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sScheduledTasks)
                    sScheduledTasksLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sMicrosoftDefenderSecurity)
                    sDefenderSecurityLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sContextMenu)
                    sContextMenuLastFunction = item.Function.ToString();
                if (item.Region.ToString() == sUpdatePolicies)
