        // Function: Load JSON file BeforeAfter
        private void LoadJsonBeforeAfter()
        {
            // Check if file exists
            if (CheckFileExists(beforeAfterJSONFilename))
            {
                using (StreamReader r = new StreamReader(beforeAfterJSONFilename))
                {
                    string stringJson = r.ReadToEnd();

                    try
                    {
                        arrayJSONBeforeAfter = Newtonsoft.Json.JsonConvert.DeserializeObject(stringJson);
                    }
                    catch (JsonReaderException ex)
                    {
                        ModernWpf.MessageBox.Show("ERROR! in JSON file: " + beforeAfterJSONFilename + ": " + ex.Message);
                    }
                }
            }
            else
            {
                ModernWpf.MessageBox.Show(beforeAfterJSONFilename + " " + messageBoxDoesNotExist);
            }
        }

        // Function: Convert JSON Before and After to list
        private void ConvertJsonBeforeAfterToList()
        {
            // For loop
            foreach (var item in arrayJSONBeforeAfter)
            {
                // Try ... Catch
                try
                {
                    // Before
                    if (item.Region == "before")
                    {
                        if (item.Function != "")
                        {
                            listStringBefore.Add(item.Function.ToString());
                        }
                    }
                    // After
                    else if (item.Region == "after")
                    {
                        if (item.Function != "")
                        {
                            listStringAfter.Add(item.Function.ToString());
                        }
                    }
                }
                catch (Exception ex)
                {
                    ModernWpf.MessageBox.Show(item.Function.ToString() + " error! " + ex.Message);
                }
            }
        }

