        // Function: Clear list strings special function, create Dict string boolean special functions and create list string special functions 
        public static void ClearListStringsSpecialFunctions_CreateDictStringBooleanSpecialFunctions_CreateListStringSpecialFunctions()
        {
            // for loop Sections clear for list string special functions
            foreach (Section sec in listSections)
            {
                sec.ListStringSpecialFunctions = new List<string>();
            }

            // string to find which is space dash
            string sFindSpaceDash = " -";

            // Go through each list of function names and find space dash to add to list
            foreach (Section sec in listSections)
            {
                foreach (string str in sec.ListStringFunctionNamesOnly) // Requires this list of just function names only
                {
                    string strTrimmed = str.Trim(); // Needs trim for "UninstallUWPApps -ForAllUsers" - most problems is because of extra white space so things need to be trimmed

                    // If there is a space dash
                    if (strTrimmed.Contains(sFindSpaceDash))
                    {
                        if (!sec.DictStringBooleanSpecialFunctions.ContainsKey(strTrimmed))
                        {
                            // Dictionary of String and Boolean for Special Functions
                            sec.DictStringBooleanSpecialFunctions.Add(strTrimmed, new bool());
                        }

                        if (!sec.ListStringSpecialFunctions.Contains(strTrimmed))
                        {
                            // List of String for Special Functions
                            sec.ListStringSpecialFunctions.Add(strTrimmed);
                        }
                    }
                }
            }
        }

        // Function: Return Last Part from Input or just function
        public static string ReturnLastPartFromInput(string sInput)
        {
            // string output
            string sOutput = "";

            // If there is a space
            if (sInput.IndexOf(" ") != -1)
            {
                string lastPart = sInput.Substring(sInput.LastIndexOf(" ") + 1, 1);

                // Has a dash
                if (lastPart == "-")
                {
                    sOutput = sInput.Substring(sInput.LastIndexOf("-") + 1);
                }
                // No dash just a space
                else
                {
                    sOutput = sInput.Substring(sInput.LastIndexOf(" ") + 1);
                }
            }
            // just function
            else
            {
                sOutput = sInput;
            }

            return sOutput;
        }

        // Function: Return Function Part from Input or just function
        private string ReturnFunctionPartFromInput(string sInput)
        {
            string sOutput = "";

            // If there is a space
            if (sInput.IndexOf(" ") != -1)
            {
                // Get first part which is the function
                sOutput = sInput.Substring(0, sInput.LastIndexOf(" "));
            }
            // Get the same as input as there is no space
            else
            {
                sOutput = sInput;
            }

            return sOutput;

        }



