        // Function: Replace String With String
        private static string ReplaceStringWithString(string str, string toBeReplaced, string replace)
        {
            return Regex.Replace(str, toBeReplaced, replace);
        }


        // Function: Compare Strings
        private int CompareStrings(string str1, string str2)
        {
            // int return first follows after set to
            int iReturn = 1;
            // Compare the values, using the CompareTo method on the first string.
            int cmpVal = str1.CompareTo(str2);

            if (cmpVal == 0) // The strings are the same.
                iReturn = 0;
            else if (cmpVal < 0) // first precedes/before
                iReturn = -1;
            //else // first follows/after
            //    return 1;

            return iReturn;
        }

        // Function: SubstractReturnBetween 
        private int SubstractReturnBetween(string stringHolder, string findString)
        {
            return stringHolder.IndexOf(findString);
        }

        // Function: FirstStringReturnBetween
        private string FirstStringReturnBetween(string stringHolder, string firstFindString, string secondFindString, int substractRet)
        {
            return stringHolder.Substring(stringHolder.IndexOf(firstFindString), stringHolder.IndexOf(secondFindString) + secondFindString.Length - substractRet);
        }

        // Function: SubstractReturn for datafile function
        private int SubstractReturn(string stringHolder, string findString)
        {
            return stringHolder.IndexOf(findString) + findString.Length;
        }

        // Function: FirstStringReturn for datafile function
        private string FirstStringReturn(string stringHolder, string firstFindString, string secondFindString, int substractRet)
        {
            return stringHolder.Substring(stringHolder.IndexOf(firstFindString) + firstFindString.Length, stringHolder.IndexOf(secondFindString) - substractRet);
        }

