        // Function: Convert to list remove lines with only 1 character or empty
        private List<string> ConvertToList(string inputString)
        {
            List<string> listStringCreatedByNewLines = new List<string>();
            List<string> listStringWithEachItemGreaterThan1Character = new List<string>();

            // Make list separted by new line
            listStringCreatedByNewLines = inputString.Split('\n').ToList();

            // If string item is greater than 1 character add to sc list
            foreach (string s in listStringCreatedByNewLines)
            {
                if (s.Length > 1)
                {
                    // Trime just in case
                    listStringWithEachItemGreaterThan1Character.Add(s.Trim());
                }
            }

            return listStringWithEachItemGreaterThan1Character;
        }

