        // Button: OutputPowerShell to Textbox to run or save
        private void OutputPowerShell_Click(object sender, RoutedEventArgs e)
        {
            // False all variables for the output
            FalseAllVariablesBooleanForOutput();

            // Add before and after
            List<string> beginStringOutputList = listStringBefore;
            List<string> endStringOutputList = listStringAfter;

            // string script output
            string so = "";

            // scriptTop added
            //so += scriptTop;

            // Add begin (BEFORE) functions
            if (beginStringOutputList.Count > 0)
            {
                so += Environment.NewLine;

                foreach (string s in beginStringOutputList)
                {
                    if (s.Length > 0)
                    {
                        so += s;
                        // Add a new line as long as it is not the last item
                        if (s != beginStringOutputList[beginStringOutputList.Count() - 1])
                        {
                            so += Environment.NewLine;
                        }
                    }
                }
            }

            //// Inside
            //so += Environment.NewLine;

            // Selected Function Called
            OutputUncommentedSelectedAllSections();

            // Unselected Function Called
            OutputCommentedUnselectedAllSections();

            // Create Output using above functions
            string co = CreateOutput();

            if (boolOpenPS1Successful)
            {
                string sectionIA = "";
                try
                {
                    sectionIA = co.Substring(co.IndexOf(startLineRegionInitialActions) + startLineRegionInitialActions.Length, co.IndexOf(endLineRegionInitialActions) - co.IndexOf(startLineRegionInitialActions) - startLineRegionInitialActions.Length);

                    //ModernWpf.MessageBox.Show(sectionIA);

                    string editST = scriptTop;

                    string sFindTopLine = "Get-ChildItem -Path $PSScriptRoot\\Module\\Private | ForEach-Object -Process {. $_.FullName}";
                    string sFindBottomLine = "# Global variable if checks failed";

                    sFindTopLine = lineToFindInPS1ToGetTopOfScriptTopLine;
                    sFindBottomLine = lineToFindInPS1ToGetTopOfScriptBottomLine;

                    string topPart = editST.Substring(0, editST.IndexOf(sFindTopLine) + sFindTopLine.Length);

                    //ModernWpf.MessageBox.Show(editST.IndexOf(sFindTopLine).ToString());

                    string bottomPart = editST.Substring(editST.IndexOf(sFindBottomLine));

                    
                    //ModernWpf.MessageBox.Show(bottomPart);

                    string scriptTopFinal = topPart + sectionIA + bottomPart;

                    so += scriptTopFinal;

                    //ModernWpf.MessageBox.Show(co);

                    string withoutIA = co.Substring(co.IndexOf(startLineRegionSystemProtection));

                    //ModernWpf.MessageBox.Show(withoutIA);

                    so += withoutIA;
                }
                catch
                {
                    so += co;
                }


            }
            else
            {
                so += co;
            }

            //ModernWpf.MessageBox.Show(so);

            // Add end (AFTER) functions
            if (endStringOutputList.Count > 0)
            {
                foreach (string s in endStringOutputList)
                {
                    so += s;
                    // Add new line unless last item in after list
                    if (s != endStringOutputList[endStringOutputList.Count() - 1])
                    {
                        so += Environment.NewLine;
                    }
                }
            }

            // Output to textbox
            tboxOutput.Text = so;

            // Status bar
            tblckStatusBarMessage.Text = statusBarPowerShellScriptCreatedFromSelections;

            ToolTip newToolTip = new ToolTip();
            newToolTip.Content = statusBarPowerShellScriptCreatedFromSelections;

            tblckStatusBarMessage.ToolTip = newToolTip;

            listAllToolTips.Add(newToolTip);

            //tblckStatusBarMessage.ToolTip = statusBarPowerShellScriptCreatedFromSelections;
        }

        // Function: Run PS with Set
        private void RunPowerShell_Click(object sender, RoutedEventArgs e)
        {
            // scriptfile to user sophia filename overwrite
            string scriptFile = userSophiaPS1ImportFilename;

            string scriptFromTxtOutput = tboxOutput.Text;



            if (scriptFromTxtOutput != "")
            {
                string powerShellFileExeLocation = "";

                string psVersion = "";



                // Get psver
                if (CompareStrings(powerShellVersionLoaded, minPS7ver) >= 0)
                {
                    psVersion = "7";
                }
                else if (CompareStrings(powerShellVersionLoaded, minPS5ver) >= 0)
                {
                    psVersion = "5";
                }

                // Get ps.exe location
                // PS7
                if (psVersion == "7")
                {
                    string programFilesPath = Environment.ExpandEnvironmentVariables("%ProgramW6432%");

                    powerShellFileExeLocation = programFilesPath + "\\PowerShell\\7\\pwsh.exe";

                    if (CheckFileExists(powerShellFileExeLocation))
                    {
                        // Nothing same
                    }
                    // Empty if not found
                    else
                    {
                        powerShellFileExeLocation = "";
                    }
                }
                // PS5
                else if (psVersion == "5")
                {
                    string systemDirectoryPath = Environment.SystemDirectory;

                    powerShellFileExeLocation = systemDirectoryPath + "\\WindowsPowerShell\\v1.0\\powershell.exe";

                    if (CheckFileExists(powerShellFileExeLocation))
                    {
                        // Nothing same
                    }
                    // Empty if not found
                    else
                    {
                        powerShellFileExeLocation = "";
                    }
                }

                // Write script to file as Encoding different
                // PS7
                if (psVersion == "7")
                {
                    // UTF8
                    File.WriteAllText(scriptFile, scriptFromTxtOutput);
                }
                // PS5
                else if (psVersion == "5")
                {
                    string completeStringHolder = "";

                    //if (scriptFromTxtOutput.IndexOf(setConsoleFontPs1Filename) == -1)
                    //{
                    //    string sTop = scriptFromTxtOutput.Substring(0, scriptFromTxtOutput.IndexOf("# # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #"));
                    //    string sBottom = scriptFromTxtOutput.Substring(scriptFromTxtOutput.IndexOf("# # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # # #"));

                    //    string insertComment = "# Set console font to Consolas when script is called only from the Wrapper due to it is not loaded by default\n";
                    //    string insertBegin = "if (Test-Path -Path \"" + pathSetConsoleFontPs1 + "\"){\n";
                    //    string insertPathSetConsoleFontPs1 = "\t& \"" + pathSetConsoleFontPs1 + "\"\n";
                    //    string insertEnd = "}";

                    //    completeStringHolder = sTop + insertComment + insertBegin + insertPathSetConsoleFontPs1 + insertEnd + "\n\n" + sBottom;
                    //}
                    //else
                    //{
                    completeStringHolder = scriptFromTxtOutput;
                    //}

                    // UTF with BOM
                    using (var sw = new StreamWriter(scriptFile, false, new UTF8Encoding(true)))
                    {
                        sw.WriteLine(completeStringHolder);
                    }
                }

                // If no ps.exe
                if (powerShellFileExeLocation == "")
                {
                    ModernWpf.MessageBox.Show(messageBoxPowerShellVersionNotInstalled);
                }
                // Run
                else
                {
                    var ps1File = scriptFile;

                    if (boolWTInstalled)
                    {
                        var startInfo = new ProcessStartInfo()
                        {
                            FileName = wtFileExeLocation,
                            Arguments = $"\"{powerShellFileExeLocation}\" -ExecutionPolicy Bypass -NoExit -file \"{ps1File}\""
                            //Arguments = $"\"{powerShellFileExeLocation}\" -ExecutionPolicy Bypass -NoExit -file \"{ps1File}\""
                            //Arguments = $"powershell & \"{ps1File}\""
                            //Arguments = $"Start-Process powershell -Verb RunAs & \"{ps1File}\""
                        };

                        Process.Start(startInfo);
                    }

                    else if (psVersion == "5")
                    {
                        var startInfo = new ProcessStartInfo()
                        {
                            FileName = powerShellFileExeLocation,
                            Arguments = $"-ExecutionPolicy Bypass -NoExit -file \"{ps1File}\""
                        };

                        Process.Start(startInfo);
                    }
                    else
                    {
                        var startInfo = new ProcessStartInfo()
                        {
                            FileName = powerShellFileExeLocation,
                            Arguments = $"-ExecutionPolicy Bypass -NoExit -file \"{ps1File}\""
                            // old Arguments = $"-NoProfile -ExecutionPolicy unrestricted -NoExit -file \"{ps1File}\""
                            //Arguments = $"-NoProfile -ExecutionPolicy ByPass -file \"{ps1File}\"",
                            //UseShellExecute = false
                        };

                        Process.Start(startInfo);
                    }
                }
            }
            // Show messagebox if console is empty
            else
            {
                ModernWpf.MessageBox.Show(messageBoxConsoleEmpty);
            }
        }


