        // Function: Get All Function Names with tags to list based on Normal/Default or LTSC separated by semi-colon
        private void GetAllFunctionNamesWithTags(string defaultOrLtscVersion, string winVer)
        {
            if (defaultOrLtscVersion == "default")
            {
                for (int i = 0; i < listSections.Count; i++)
                {
                    listSections[i].AllFunctionsList = ReturnAllFunctionsAddTags(listStringSectionsNames[i], "default", winVer);
                    //listSections[i].AllFunctionsListWithCombos = ReturnAllFunctionsAddTagsWithCombos(listStringSectionsNames[i], "default", winVer);
                }
            }
            else if (defaultOrLtscVersion == "ltsc")
            {
                for (int i = 0; i < listSections.Count; i++)
                {
                    listSections[i].AllFunctionsList = ReturnAllFunctionsAddTags(listStringSectionsNames[i], "ltsc", winVer);
                    //listSections[i].AllFunctionsListWithCombos = ReturnAllFunctionsAddTagsWithCombos(listStringSectionsNames[i], "ltsc", winVer);
                }
            }

            // SPECIAL

            //for (int i = 0; i < listSections.Count; i++)
            //{
            //    allControlsListWithTags.AddRange(listSections[i].AllFunctionsListWithCombos);
            //}
        }

        // Function: Get All Function Names with tags to list based on Normal/Default or LTSC separated by semi-colon
        private void GetAllFunctionNamesWithTagsWithCombos(string defaultOrLtscVersion, string winVer)
        {
            if (defaultOrLtscVersion == "default")
            {
                for (int i = 0; i < listSections.Count; i++)
                {
                    //listSections[i].AllFunctionsList = ReturnAllFunctionsAddTags(listStringSectionsNames[i], "default", winVer);
                    listSections[i].AllFunctionsListWithCombos = ReturnAllFunctionsAddTagsWithCombos(listStringSectionsNames[i], "default", winVer);
                }
            }
            else if (defaultOrLtscVersion == "ltsc")
            {
                for (int i = 0; i < listSections.Count; i++)
                {
                    //listSections[i].AllFunctionsList = ReturnAllFunctionsAddTags(listStringSectionsNames[i], "ltsc", winVer);
                    listSections[i].AllFunctionsListWithCombos = ReturnAllFunctionsAddTagsWithCombos(listStringSectionsNames[i], "ltsc", winVer);
                }
            }

            // SPECIAL

            for (int i = 0; i < listSections.Count; i++)
            {
                listAllControlsWithTags.AddRange(listSections[i].AllFunctionsListWithCombos);
            }
        }

        // Function: Get All Function Names Only into Sections and Fill Global List with all function names only and Get all function names that need own tooltip
        private void GetAllFunctionNamesOnlyIntoSections_FillGlobalListStringVariableAllFunctionNamesOnly_GetAllFunctionsThatNeedOwnToolTip(string defaultOrLtscVersion, string winVer)
        {
            GetAllFunctionNamesOnlyIntoSections(defaultOrLtscVersion, winVer);
            FillGlobalListStringVariableAllFunctionNamesOnly();
            GetAllFunctionNamesThatNeedOwnToolTip(defaultOrLtscVersion, winVer);
        }

        // Function: Get All Function Names Only Into Sections and fill global list with all function names only
        private void GetAllFunctionNamesOnlyIntoSections(string defaultOrLtscVersion, string winVer)
        {
            // Clear Sections
            for (int i = 0; i < listSections.Count; i++)
            {
                listSections[i].ListStringFunctionNamesOnly = new List<string>();
            }

            // Get function names only into sections
            if (defaultOrLtscVersion == "default")
            {
                for (int i = 0; i < listSections.Count; i++)
                {
                    listSections[i].ListStringFunctionNamesOnly = ReturnAllFunctionNamesOnly(listStringSectionsNames[i], "default", winVer);
                }
            }
            else if (defaultOrLtscVersion == "ltsc")
            {
                for (int i = 0; i < listSections.Count; i++)
                {
                    listSections[i].ListStringFunctionNamesOnly = ReturnAllFunctionNamesOnly(listStringSectionsNames[i], "ltsc", winVer);
                }
            }
        }

        // Function: Fill Global list of all function names only
        private void FillGlobalListStringVariableAllFunctionNamesOnly()
        {
            // A global variable that hold all function names only (no tag). Clear first
            listStringAllFunctionNamesOnly = new List<string>();

            // Fill Global variable
            for (int i = 0; i < listSections.Count; i++)
            {
                foreach (string s in listSections[i].ListStringFunctionNamesOnly)
                {
                    if (!listStringAllFunctionNamesOnly.Contains(s))
                    {
                        listStringAllFunctionNamesOnly.Add(s);
                    }
                }
            }
        }

