                for (int i = 0; i < listSections.Count; i++)
                {
                    //listStringAllFunctionNamesThatNeedOwnToolTip.AddRange(ReturnAllFunctionNamesThatHaveSeparateConditionForOwnToolTip(listStringSectionsNames[i], "default", winver));
                    listSections[i].ListStringFunctionNamesThatNeedOwnToolTip = ReturnAllFunctionNamesThatHaveSeparateConditionForOwnToolTip(listStringSectionsNames[i], "default", winver);
                }
            }
            else if (dataversion == "ltsc")
            {
                for (int i = 0; i < listSections.Count; i++)
                {
                    //listStringAllFunctionNamesThatNeedOwnToolTip.AddRange(ReturnAllFunctionNamesThatHaveSeparateConditionForOwnToolTip(listStringSectionsNames[i], "ltsc", winver));
                    listSections[i].ListStringFunctionNamesThatNeedOwnToolTip = ReturnAllFunctionNamesThatHaveSeparateConditionForOwnToolTip(listStringSectionsNames[i], "ltsc", winver);
                }
            }
        }

        // Function: Return all functions
        private List<string> ReturnAllFunctionsAddTags(string region, string dataVersion, string winVer)
        {
            //string output = "";

            List<string> output = new List<string>();

            foreach (var item in arrayJSON)
            {
                try
                {
                    // Arguement counter
                    int argCount = 0;

                    // Normal
                    if (item.Region == region)
                    {
                        // Count number of Arg
                        foreach (var i in item.Arg)
                        {
                            argCount += 1;
                        }

                        //string o = "";                        
                        List<string> o = new List<string>();


                        if ((item.Control == "tboxtboxtbox") & (item.Required == "false") & (argCount == 3))
                        {
                            //o = item.Function + ";";
                            o.Add(item.Function.ToString());
                        }
                        else if ((item.Control == "cmb") & (item.Required == "true") & (argCount == 2))
