                        }
                        else if ((item.Control == "chk") & (argCount == 3))
                        {
                            //o = item.Function.ToString() + ";";
                            o.Add(item.Function.ToString());
                        }
                        else if ((item.Control == "chk") & (argCount == 2))
                        {
                            //o = item.Function.ToString() + ";";
                            o.Add(item.Function.ToString());

                            o.Add(item.Function.ToString() + " " + item.Arg.Zero.Tag.ToString());
                            o.Add(item.Function.ToString() + " " + item.Arg.One.Tag.ToString());

                            o.Add(item.Function.ToString() + " " + item.Arg.Zero.Tag.ToString() + ", " + item.Arg.One.Tag.ToString());
                            o.Add(item.Function.ToString() + " " + item.Arg.One.Tag.ToString() + ", " + item.Arg.Zero.Tag.ToString());

                        }
                        else if ((item.Control == "chk") & (argCount == 1))
                        {
                            //o = item.Function.ToString() + ";";
                            o.Add(item.Function.ToString());
                        }

                        //output = output.Concat(o);
                        output.AddRange(o);

                    }
                }
                catch (Exception e)
                {
                    ModernWpf.MessageBox.Show(item.Function.ToString() + " error! " + e.Message);
                }
            }

            //if (output != "")
            //{
            //    // Remove last character
            //    output = output.Substring(0, output.Length - 1);
            //}

            // Return output
            return output;
        }

