        // Function: Return all functions from arrayJSON data.txt for use in outputting Tooltips as comments above options
        private List<string> ReturnAllFunctionNamesOnly(string region, string dataVersion, string winVer)
        {
            //string output = "";
            List<string> output = new List<string>();

            // JValue to compare LTSC cmbItem
            Newtonsoft.Json.Linq.JValue s1 = new Newtonsoft.Json.Linq.JValue("true");

            foreach (var item in arrayJSON)
            {
                try
                {
                    // Arguement counter
                    int argCount = 0;

                    // Normal
                    if (item.Region == region)
                    {
                        // Count number of Arg
                        foreach (var i in item.Arg)
                        {
                            argCount += 1;
                        }

                        //string o = "";
                        List<string> o = new List<string>();


                        //o = item.Function + ";";
                        o.Add(item.Function.ToString());

                        if (item.Function2 != null)
                        {
                            //o += item.Function2 + ";";
                            o.Add(item.Function2.ToString());
                        }

                        output.AddRange(o);
                        //output += o;

                    }
                }
                catch (Exception e)
                {
                    ModernWpf.MessageBox.Show(item.Function.ToString() + " error! " + e.Message);
                }
            }

            //if (output != "")
            //{
            //    // Remove last character
            //    output = output.Substring(0, output.Length - 1);
            //}

            // Return output
            return output;
        }

