        private List<string> ReturnAllFunctionNamesThatHaveSeparateConditionForOwnToolTip(string region, string dataVersion, string winVer)
        {
            //string output = "";
            List<string> output = new List<string>();

            // JValue to compare LTSC cmbItem
            //Newtonsoft.Json.Linq.JValue s1 = new Newtonsoft.Json.Linq.JValue("true");

            foreach (var item in arrayJSON)
            {
                try
                {
                    // Argument counter
                    int argCount = 0;

                    // Normal
                    if (item.Region == region)
                    {
                        // Count number of Arg
                        foreach (var i in item.Arg)
                        {
                            argCount += 1;
                        }

                        List<string> o = new List<string>();
                        //string o = "";


                        if (item.Separate != null)
                        {
                            if (item.Separate == "true")
                            {
                                //o = item.Function + ";";
                                o.Add(item.Function.ToString());
                            }
                        }

                        //output += o;
                        output.AddRange(o);

                    }
                }
                catch (Exception e)
                {
                    ModernWpf.MessageBox.Show(item.Function.ToString() + " error! " + e.Message);
                }
            }

            //if (output != "")
            //{
            //    // Remove last character
            //    output = output.Substring(0, output.Length - 1);
            //}

            // Return output
            return output;
        }

