        // Function: Output Uncommented Selected All Sections

        private void OutputUncommentedSelectedAllSections()
        {
            // Clear uncommented selected list
            foreach (Section sec in listSections)
            {
                sec.UncommentedSelectedList = new List<string>();
            }

            if ((LTSCversionLoaded == "ltsc2019") & (boolLTSC == true))
            {
                foreach (Section sec in listSectionsLTSC2019)
                {
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputComboBox(sec, sec.ComboBoxes)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputCheckBox(sec, sec.CheckBoxes)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputSCheckBox(sec.DictStringListChk)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputSelectedCmbListCmbs(sec.ListCmbsUF)));
                }
                oneDriveSec.UncommentedSelectedList.AddRange(ConvertToList(OutputComboBoxCheckBoxAlter(oneDriveSec)));
                systemSec.UncommentedSelectedList.AddRange(ConvertToList(OutputSetAssociationDict(systemSec.SelectDictStringListStringSA)));
            }

            else if ((LTSCversionLoaded == "ltsc2021") & (boolLTSC == true))
            {
                foreach (Section sec in listSectionsLTSC2021)
                {
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputComboBox(sec, sec.ComboBoxes)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputCheckBox(sec, sec.CheckBoxes)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputSCheckBox(sec.DictStringListChk)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputSelectedCmbListCmbs(sec.ListCmbsUF)));
                }
                oneDriveSec.UncommentedSelectedList.AddRange(ConvertToList(OutputComboBoxCheckBoxAlter(oneDriveSec)));
                systemSec.UncommentedSelectedList.AddRange(ConvertToList(OutputSetAssociationDict(systemSec.SelectDictStringListStringSA)));
            }

            else if ((LTSCversionLoaded == "ltsc2024") & (boolLTSC == true))
            {
                foreach (Section sec in listSectionsLTSC2024)
                {
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputComboBox(sec, sec.ComboBoxes)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputCheckBox(sec, sec.CheckBoxes)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputSCheckBox(sec.DictStringListChk)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputSelectedCmbListCmbs(sec.ListCmbsUF)));
                }
                oneDriveSec.UncommentedSelectedList.AddRange(ConvertToList(OutputComboBoxCheckBoxAlter(oneDriveSec)));
                systemSec.UncommentedSelectedList.AddRange(ConvertToList(OutputSetAssociationDict(systemSec.SelectDictStringListStringSA)));
            }

            else
            {
                foreach (Section sec in listSections) // mozilla
                {
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputComboBox(sec, sec.ComboBoxes)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputCheckBox(sec, sec.CheckBoxes)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputSCheckBox(sec.DictStringListChk)));
                    sec.UncommentedSelectedList.AddRange(ConvertToList(OutputSelectedCmbListCmbs(sec.ListCmbsUF)));
                    
                }
                oneDriveSec.UncommentedSelectedList.AddRange(ConvertToList(OutputComboBoxCheckBoxAlter(oneDriveSec)));
                systemSec.UncommentedSelectedList.AddRange(ConvertToList(OutputSetAssociationDict(systemSec.SelectDictStringListStringSA)));
            }
        }

