        // Function: Output Commented Unselected All Sections
        private void OutputCommentedUnselectedAllSections()
        {
            // Clear Commented Unselected list
            foreach (Section sec in listSections)
            {
                sec.CommentedUnselectedList = new List<string>();
            }

            if ((LTSCversionLoaded == "ltsc2019") & (boolLTSC == true))
            {
                foreach (Section sec in listSectionsLTSC2019)
                {
                    OutputSelectedRegion(sec.AllFunctionsList, sec.UncommentedSelectedList, sec.CommentedUnselectedList);
                }
            }

            else if ((LTSCversionLoaded == "ltsc2021") & (boolLTSC == true))
            {
                foreach (Section sec in listSectionsLTSC2021)
                {
                    OutputSelectedRegion(sec.AllFunctionsList, sec.UncommentedSelectedList, sec.CommentedUnselectedList);
                }
            }

            else if ((LTSCversionLoaded == "ltsc2024") & (boolLTSC == true))
            {
                foreach (Section sec in listSectionsLTSC2024)
                {
                    OutputSelectedRegion(sec.AllFunctionsList, sec.UncommentedSelectedList, sec.CommentedUnselectedList);
                }
            }

            else
            {
                foreach (Section sec in listSections)
                {
                    OutputSelectedRegion(sec.AllFunctionsList, sec.UncommentedSelectedList, sec.CommentedUnselectedList);
                }
            }
        }

        // Function: Output Uncommented Selected Region is just the opposite of selected items
        private void OutputSelectedRegion(List<string> AllFunctionList, List<string> UncommentedSelectedList, List<string> CommentedUnselectedList)
        {
            foreach (string s in AllFunctionList)
            {
                if (!UncommentedSelectedList.Contains(s))
                {
                    CommentedUnselectedList.Add(s);
                }
            }
        }

        // Function: Create Output by Region
        private string CreateOutputByRegion(Section sec, string region, string endregion, List<string> afl, List<string> usl, List<string> cusl, Dictionary<string, string> dict)
        {
            // o is output string
            string o = "";

            // Add region to output string
            o += region + "\n\n";

            // Go through the All Function List of region
            foreach (string s in afl)
            {
                // trim s just in case
                string ts = s.Trim();

                // InitialActions
                for (int i = 0; i < sec.ListCmbRequiredIA.Count; i++)
                {
                    // Get objects                    
                    for (int p = 0; p < sec.ListCmbRequiredIA[i].LstStrMainArg.Count; p++)
                    {
                        string accessString = "";

                        accessString = sec.ListCmbRequiredIA[i].CmbFunctionName + " -" + sec.ListCmbRequiredIA[i].LstStrMainArg[p];
                        if (sec.ListCmbRequiredIA[i].LstStrMainArg[p] == "")
                        {
                            accessString = sec.ListCmbRequiredIA[i].CmbFunctionName;// + " -" + sec.ListRequired[i].MainArg[p];
                        }

                        if (ts == accessString)
                        {
                            if (usl.Count > 0)
                            {
                                int j = 0;
                                while (j < usl.Count)
                                {
                                    if (usl[j] == accessString)
                                    {
                                        if ((usl[j] == accessString) & (sec.ListCmbRequiredIA[i].LstBoolCmb1[p] == false))
                                        {
                                            if (dict.ContainsKey(accessString))
                                            {
                                                o += "# " + dict[accessString] + "\n";
                                            }

                                            o += usl[j] + "\n";

                                            sec.ListCmbRequiredIA[i].LstBoolCmb1[p] = true;

                                            break;
                                        }
                                    }
                                    j++;
                                }
                            }
                        }
                    }
                }

                // OneDrive -AllUsers
                foreach (Cmbchkalter cmbchkalter in sec.ListCmbchkalterODAU)
                {
                    string accessString = cmbchkalter.CmbFunctionName;

                    if (ts.Contains(accessString))
                    {
                        // Only do this if the usl list has uncommented selected
                        if (usl.Count > 0)
                        {
                            // while i less than USL list count
                            int i = 0;
                            while (i < usl.Count)
                            {
                                // Go through usl to find sX. If USL contains sX then output usl at i
                                if (usl[i].Contains(accessString))
                                {
                                    // Boolean                                                                                                                 
                                    if ((usl[i].Contains(accessString) & (usl[i] != accessString)))
                                    {
                                        string accessStringChk = cmbchkalter.ChkFunctionName;
                                        string suffix = accessStringChk.Substring(accessStringChk.IndexOf(" "));
                                        accessStringChk = accessString + " -" + cmbchkalter.LstStrMainArg[cmbchkalter.IndexOfInstall] + suffix;
                                        if (usl[i].Contains(accessStringChk))
                                        {
                                            if (cmbchkalter.BoolChk1 == false)
                                            {
                                                if (dict.ContainsKey(cmbchkalter.ChkFunctionName))
                                                {
                                                    o += "# " + dict[cmbchkalter.ChkFunctionName] + "\n";
                                                }
                                                o += usl[i] + "\n\n";
                                                cmbchkalter.BoolChk1 = true;
                                            }
                                        }
                                        else
                                        {
                                            for (int a = 0; a < cmbchkalter.LstStrMainArg.Count; a++)
                                            {
                                                if ((usl[i].Contains(cmbchkalter.LstStrMainArg[a])) & (cmbchkalter.LstBoolCmb1[a] == false))
                                                {
                                                    string dictstring = accessString + " -" + cmbchkalter.LstStrMainArg[a];

                                                    if (dict.ContainsKey(dictstring))
                                                    {
                                                        o += "# " + dict[dictstring] + "\n";
                                                    }
                                                    else
                                                    {
                                                        if (!((a + 1) == cmbchkalter.LstStrMainArg.Count))
                                                        {
                                                            if (dict.ContainsKey(accessString + " -" + cmbchkalter.LstStrMainArg[(a + 1)]))
                                                            {
                                                                o += "# " + dict[accessString + " -" + cmbchkalter.LstStrMainArg[(a + 1)]] + "\n";
                                                            }
                                                        }
                                                    }

                                                    o += usl[i] + "\n\n";
                                                    cmbchkalter.LstBoolCmb1[a] = true;
                                                }
                                            }
                                            //break;
                                        }
                                    }
                                }
                                i++;
                            }
                        }
                    }
                }

                //// User Folders UserFolders
