                            if (sec.ListCmbRequiredIA[i].LstStrMainArg[j] == "")
                            {
                                accessString = sec.ListCmbRequiredIA[i].CmbFunctionName;// + " -" + sec.ListRequired[i].MainArg[p];
                            }

                            if (ts == accessString)
                            {
                                bSkip = true;
                            }
                        }
                    }

                    // Onedrive MainArg
                    for (int i = 0; i < sec.ListCmbchkalterODAU.Count; i++)
                    {
                        for (int j = 0; j < sec.ListCmbchkalterODAU[i].LstStrMainArg.Count; j++)
                        {
                            if (ts.Contains(sec.ListCmbchkalterODAU[i].CmbFunctionName + " -" + sec.ListCmbchkalterODAU[i].LstStrMainArg[j]))
                            {
                                bSkip = true;
                            }
                        }
                    }
                    // Onedrive allusers
                    for (int i = 0; i < sec.ListCmbchkalterODAU.Count; i++)
                    {
                        if (ts.Contains(sec.ListCmbchkalterODAU[i].ChkFunctionName))
                        {
                            bSkip = true;
                        }
                    }
                    for (int i = 0; i < sec.ListCmbsUF.Count; i++)
                    {
                        if (ts.Contains(sec.ListCmbsUF[i].CmbFunctionName) & (sec.ListCmbsUF[i].BoolTF == true))
                        {
                            bSkip = true;
                        }
                    }
                    //for (int i = 0; i < sec.ListCmbcmbcmbDOH.Count; i++)
                    //{

                    //    if (ts.Contains(sec.ListCmbcmbcmbDOH[i].CmbFunctionName))
                    //    {
                    //        bSkip = true;
                    //    }
                    //}

                    // Special function use for loop to go through list
                    foreach (var kvp in sec.DictStringBooleanSpecialFunctions.ToArray())
                    {
                        var item = kvp;
                        string itemKey = item.Key.ToString();

                        string sHolder = itemKey;
                        if (ts.Contains(sHolder))
                        {
                            // no repeat for special function
                            bSkip = true;
                        }
                    }

                    foreach (Cmbchk cc in sec.ListCmbchkPESC)
                    {
                        if (ts.Contains(cc.CmbFunctionName))
                        {
                            bSkip = true;
                        }
                    }

                    foreach (var kvp in systemSec.SelectDictStringListStringSA)
                    {
                        string k = kvp.Key.ToString();
                        k = k.Substring(0, k.LastIndexOf("-"));
                        if (ts.Contains(k))
                        {
                            //ModernWpf.MessageBox.Show(ts);
                            // no repeat for special function
                            bSkip = true;
                        }
                    }

                    // Special function use for loop to go through list
                    foreach (var kvp in sec.DictStringBooleanSpecialFunctions)
                    {
                        string k = kvp.Key.ToString();
                        if (ts.Contains(k))
                        {
                            // no repeat for special function
                            bSkip = true;
                        }
                    }

                    if (bSkip == false)
                    {
                        if (dict.ContainsKey(ts))
                        {
                            o += "# " + dict[ts] + "\n";
                        }
                        o += ts + "\n";
                    }
                }

                // Commented Unselected list
                if (cusl.Contains(ts))
                {
                    bool bSkip = false;

                    // InitialActions
                    for (int i = 0; i < sec.ListCmbRequiredIA.Count; i++)
                    {
                        for (int j = 0; j < sec.ListCmbRequiredIA[i].LstStrMainArg.Count; j++)
                        {
                            string accessString = "";
                            accessString = sec.ListCmbRequiredIA[i].CmbFunctionName + " -" + sec.ListCmbRequiredIA[i].LstStrMainArg[j];
                            if (sec.ListCmbRequiredIA[i].LstStrMainArg[j] == "")
                            {
                                accessString = sec.ListCmbRequiredIA[i].CmbFunctionName;// + " -" + sec.ListRequired[i].MainArg[p];
                            }

                            if (ts.Contains(accessString) & (sec.ListCmbRequiredIA[i].LstBoolCmb1[j] == true))
                            {
                                bSkip = true;
                            }
                        }
                    }

                    // OneDrive -AllUsers
                    for (int i = 0; i < sec.ListCmbchkalterODAU.Count; i++)
                    {
                        for (int j = 0; j < sec.ListCmbchkalterODAU[i].LstStrMainArg.Count; j++)
                        {
                            if (ts.Contains(sec.ListCmbchkalterODAU[i].CmbFunctionName + " -" + sec.ListCmbchkalterODAU[i].LstStrMainArg[j]) & (sec.ListCmbchkalterODAU[i].LstBoolCmb1[j] == true))
                            {
                                bSkip = true;
                            }
                        }
                    }
                    // Onedrive allusers
                    for (int i = 0; i < sec.ListCmbchkalterODAU.Count; i++)
                    {
                        if ((ts.Contains(sec.ListCmbchkalterODAU[i].ChkFunctionName)) & (sec.ListCmbchkalterODAU[i].BoolChk1 == true))
                        {
                            bSkip = true;
                        }
                    }

                    for (int i = 0; i < sec.ListCmbsUF.Count; i++)
                    {
                        bool bUFSkip = false;
                        if ((sec.ListCmbsUF[i].WhichMainArgFirst != -1) & (ts.Contains(sec.ListCmbsUF[i].CmbFunctionName)) & (sec.ListCmbsUF[i].BoolTF == true) & (sec.ListCmbsUF[i].BoolWroteOppositeComment == false))
                        {
                            if (ts.Contains(sec.ListCmbsUF[i].CmbFunctionName) & (sec.ListCmbsUF[i].BoolTF == true) & (ts.Contains(sec.ListCmbsUF[i].LstStrMainArg[sec.ListCmbsUF[i].WhichMainArgFirst])))
                            {
                                //if (dict.ContainsKey(ts))
                                //{
                                //ModernWpf.MessageBox.Show("1:" + ts);

                                //    //o += "\n";
                                //    o += "# " + dict[ts] + "\n"; ;
                                //}

                                //o += "# " + ts + "\n";

                                //bSkip = true;
                                //bUFSkip = true;
                                ////sec.ListCmbsUF[i].BoolWroteOppositeComment = true;
                                //}
                                //else
                                //{
                                //int whichInt = 1;
                                //if (sec.ListCmbsUF[i].WhichMainArgFirst == 1)
                                //{
                                //    whichInt = 0;
                                //}

                                //string sKey = sec.ListCmbsUF[i].CmbFunctionName + " -" + sec.ListCmbsUF[i].MainArg[whichInt].ToString();
                                //if (dict.ContainsKey(sKey))
                                //{
                                //    //ModernWpf.MessageBox.Show(ts);

                                //o += "\n\n";
                                //    o += "# " + dict[sKey] + "\n"; ;
                                //}

                                //o += "# " + sKey + "\n";

                                bSkip = true;
                                bUFSkip = true;
                                //sec.ListCmbsUF[i].BoolWroteOppositeComment = true;
                            }
                        }
                        else if (ts.Contains(sec.ListCmbsUF[i].CmbFunctionName) & (sec.ListCmbsUF[i].BoolTF == true))
                        {
                            //o += "\n\n";
                            //ModernWpf.MessageBox.Show("2:" + ts);
                            bSkip = false;
                        }
                        if (bUFSkip == true)
                        {
                            sec.ListCmbsUF[i].BoolWroteOppositeComment = true;
                        }
                    }

                    //for (int i = 0; i < sec.ListCmbcmbcmbDOH.Count; i++)
                    //{

                    //    if (ts.Contains(sec.ListCmbcmbcmbDOH[i].CmbFunctionName + " -" + sec.ListCmbcmbcmbDOH[i].LstStrMainArg[0]) & (sec.ListCmbcmbcmbDOH[i].BoolTF == true))
                    //    {
                    //        bSkip = true;
                    //    }
                    //}
                    // Special function use for loop with counter ccc to track list and bool list. 
                    foreach (var kvp in sec.DictStringBooleanSpecialFunctions.ToArray())
                    {
                        var item = kvp;
                        string itemKey = item.Key.ToString();

                        string sHolder = itemKey;
                        if (ts.Contains(sHolder) & (sec.DictStringBooleanSpecialFunctions[sHolder] == true))
                        {
                            // no repeat for special function
                            bSkip = true;
                        }
                    }
                    foreach (Cmbchk cc in sec.ListCmbchkPESC)
                    {
                        if (ts.Contains(cc.CmbFunctionName + " -" + cc.LstStrMainArg[0]) & cc.LstBoolMainCmb[0] == true)
                        {
                            bSkip = true;
                        }
                    }

                    foreach (Tboxtboxtbox tb in sec.ListTboxtboxtboxSA)
                    {
                        //if (ts.Contains(tb.TboxFunctionName))
                        //{
                        //    ModernWpf.MessageBox.Show(ts);
                        //}

                        if (ts.Contains(tb.TboxFunctionName) & tb.BoolTF == true)
                        {
                            bSkip = true;
                        }
                    }

                    foreach (var kvp in sec.DictStringBooleanSpecialFunctions)
                    {
                        string k = kvp.Key.ToString();
                        bool b = kvp.Value;

                        if (ts.Contains(k) & b == true)
                        {
                            // no repeat for special function
                            bSkip = true;
                        }
                    }



                    if (bSkip == false)
                    {
                        bool bSkip2 = false;

                        for (int i = 0; i < sec.ListCmbchkalterODAU.Count; i++)
                        {
                            if ((ts.Contains(sec.ListCmbchkalterODAU[i].ChkFunctionName)) & (sec.ListCmbchkalterODAU[i].BoolChk1 == false))
                            {
                                if (dict.ContainsKey(ts))
                                {
                                    o += "# " + dict[ts] + "\n"; ;
                                }

                                o += "# " + sec.ListCmbchkalterODAU[i].CmbFunctionName + " -" + sec.ListCmbchkalterODAU[i].LstStrMainArg[sec.ListCmbchkalterODAU[i].IndexOfInstall] + sec.ListCmbchkalterODAU[i].ChkFunctionName.Substring(sec.ListCmbchkalterODAU[i].ChkFunctionName.IndexOf(" ")) + "\n";
                                bSkip2 = true;
                                break;
                            }
                        }

                        if (bSkip2 == false)
                        {
                            if (dict.ContainsKey(ts))
                            {
                                o += "# " + dict[ts] + "\n"; ;
                            }

                            o += "# " + ts + "\n";
                        }
                    }
                }
                if (o.Substring(o.Length - 2) == "\n\n")
                {
                    o = o.Substring(0, o.Length);
                }
                else
                {
                    o += "\n";
                }
            }

            // output endregion
            o += endregion + "\n\n\n";
            // return 
            return o;
        }

