        // Function: Output S CheckBox 
        private string OutputSCheckBox(Dictionary<string, List<CheckBox>> myDictionary)
        {
            string output = "";
            string coutput = "";
            bool boolTrueFalse = false;

            foreach (KeyValuePair<string, List<CheckBox>> entry in myDictionary)
            {
                boolTrueFalse = false;

                foreach (CheckBox chk in entry.Value)
                {
                    if (chk.IsChecked == true)
                    {
                        coutput += chk.Content.ToString() + ", ";
                        boolTrueFalse = true;
                    }
                }
                // Remove ', ' if there is output
                if (boolTrueFalse == true)
                {
                    output += entry.Key + " " + coutput.Substring(0, coutput.Length - 2) + Environment.NewLine;
                }

                coutput = "";
            }

            return output;
        }

        // Function: Output CheckBox
        private string OutputCheckBox(Section sec, List<CheckBox> listChk)
        {
            string output = "";

            // Remove chk found in cmbchkalterodau
            bool bChkFound = false;

            foreach (CheckBox chk in listChk)
            {
                bChkFound = false;

                foreach (Cmbchkalter cca in sec.ListCmbchkalterODAU)
                {
                    if (chk == cca.Chk1)
                    {
                        bChkFound = true;
                    }
                }

                if (bChkFound == false)
                {
                    if (chk.IsChecked == true)
                    {
                        string sChk = chk.Tag.ToString().Trim();
                        //ModernWpf.MessageBox.Show(sChk);
                        if (sChk.Substring(sChk.Length - 1, 1) == "-")
                        {
                            //ModernWpf.MessageBox.Show(sChk);
                            sChk = sChk.Substring(0, sChk.Length - 1).Trim();
                            //ModernWpf.MessageBox.Show(sChk);
                        }
                        output += sChk + Environment.NewLine;
                    }
                }
            }
            return output;
        }

