        // Function: Output ComboBox
        private string OutputComboBox(Section sec, List<ComboBox> listCmb)
        {
            // string Output
            string output = "";

            // List of cmb that we don't want to include for output from CCA,CCC,UF
            List<ComboBox> listCmbFromCCAandCCCandUF = new List<ComboBox>();

            // Create a list of cmb from section CCA
            foreach (Cmbchkalter cca in sec.ListCmbchkalterODAU)
            {
                listCmbFromCCAandCCCandUF.Add(cca.Cmb1);
            }

            //foreach (Cmbcmbcmb ccc in sec.ListCmbcmbcmbDOH)
            //{
            //    foreach (ComboBox cmb in ccc.LstCmb1)
            //    {
            //        listCmbFromCCAandCCCandUF.Add(cmb);
            //    }
            //}

            foreach (Cmbs cmbs in sec.ListCmbsUF)
            {
                foreach (ComboBox cmb in cmbs.LstCmb1)
                {
                    listCmbFromCCAandCCCandUF.Add(cmb);
                }
            }

            // output combobox from listCmb
            foreach (ComboBox cmb in listCmb)
            {
                if ((cmb != null) & (!listCmbFromCCAandCCCandUF.Contains(cmb)))
                {
                    ComboBoxItem cmbItem = cmb.SelectedItem as ComboBoxItem;

                    if (cmbItem != null)
                    {
                        if (cmbItem.Tag.ToString() != sSkip)
                        {
                            output += cmbItem.Tag.ToString() + Environment.NewLine;
                        }
                    }
                }
            }

            // Return output
            return output;
        }

        // Function: Output ComboBox CheckBox Alter
        private string OutputComboBoxCheckBoxAlter(Section sec)
        {
            string output = "";

            foreach (Cmbchkalter cca in sec.ListCmbchkalterODAU)
            {
                ComboBox cmb = cca.Cmb1;

                if (cca.Chk1.IsChecked == true)
                {
                    //output += cca.ChkFunctionName + "\n";
                    output += cca.CmbFunctionName + " -" + cca.LstStrMainArg[cca.IndexOfInstall].ToString() + cca.ChkFunctionName.Substring(cca.ChkFunctionName.IndexOf(" ")) + "\n";
                }
                else if (cmb != null)
                {
                    // pluto
                    if (!(listStringSkip.Contains(cmb.Text)) & (cmb.Text != null) & (cmb.Text != ""))
                    {
                        ComboBoxItem cmbItem = cmb.SelectedItem as ComboBoxItem;

                        if (cmbItem.Tag.ToString() != sSkip)
                        {
                            output += cmbItem.Tag.ToString() + Environment.NewLine;
                        }
                    }
                }
            }
            return output;
        }

        // Function: Output Dict TextBox for Set-Assocation 
        private string OutputSetAssociationDict(Dictionary<string, List<string>> dict)
        {
            string o = "";
            string sheader = "Set-Association";
            string spp = "-ProgramPath";
            string sext = "-Extension";
            string sico = "-Icon";

            foreach (KeyValuePair<string, List<string>> entry in dict)
            {
                List<string> list = new List<string>();
                list = entry.Value;

                sheader = entry.Key.Substring(0, entry.Key.LastIndexOf("-"));

                if (list.Count == 3)
                {
                    o += sheader + " " + spp + " " + list[0] + " " + sext + " " + list[1] + " " + sico + " " + list[2] + "\n";
                }
                else if (list.Count == 2)
                {
                    o += sheader + " " + spp + " " + list[0] + " " + sext + " " + list[1] + "\n";
                }
            }
            return o;
        }

        // Function: Output Dict TextBox for Set-Assocation 
        private string OutputSetAssociationDictByFunction(Section sec, Dictionary<string, List<string>> dict, string functionName)
        {
            string o = "";
            string sheader = "Set-Association";
            string spp = "-ProgramPath";
            string sext = "-Extension";
            string sico = "-Icon";
            string h = "-";

            foreach (KeyValuePair<string, List<string>> entry in dict)
            {
                List<string> list = new List<string>();
                list = entry.Value;

                sheader = entry.Key.Substring(0, entry.Key.LastIndexOf("-"));

                foreach (Tboxtboxtbox ttt in sec.ListTboxtboxtboxSA)
                {
                    if (ttt.TboxFunctionName == functionName)
                    {
                        // Zillion
                        spp = h + ttt.Tbox1.Tag.ToString();
                        sext = h + ttt.Tbox2.Tag.ToString();
                        sico = h + ttt.Tbox3.Tag.ToString();
                    }
                }

                if (sheader == functionName)
                {
                    if (list.Count == 3)
                    {
                        o += sheader + " " + spp + " " + list[0] + " " + sext + " " + list[1] + " " + sico + " " + list[2] + "\n";
                    }
                    else if (list.Count == 2)
                    {
                        o += sheader + " " + spp + " " + list[0] + " " + sext + " " + list[1] + "\n";
                    }
                }
            }
            return o;
        }

        // Function: Output Selected UserFolders cmbList
        // Fix make into list to add list to output for multiple userfolder types. Output is a list // fix bool userfolder to reappear again 
        private string OutputSelectedCmbListCmbs(List<Cmbs> lcs)
        {
            string s = "";

            foreach (Cmbs cmbs in lcs)
            {
                s += cmbs.CmbFunctionName;

                foreach (ComboBox cmb in cmbs.LstCmb1)
                {
                    ComboBoxItem cmbItem = (ComboBoxItem)cmb.SelectedItem;

                    if (cmbItem != null)
                    {
                        if (cmbItem.Tag.ToString() != sSkip)
                        {
                            string sci = cmbItem.Tag.ToString();
                            string value = sci.Substring(sci.IndexOf(" "));
                            //string value = sci2;
                            s += value;// + " ";

                        }
                    }
                }
                s = s.Trim();
                s += "\n";
            }
            s = s.Trim();
            return s;
        }

