        // Function: OutputSCheckBoxPESC
        private string OutputSCheckBoxPESC(Section sec, List<ComboBox> myComboBox, Dictionary<string, List<CheckBox>> myDictionary)
        {
            string output = "";

            string comboBoxOutput = "";

            foreach (Cmbchk cc in sec.ListCmbchkPESC)
            {
                ComboBox cmb = cc.MainCmb;

                ComboBoxItem it = cmb.SelectedItem as ComboBoxItem;

                if (it != null)
                {
                    comboBoxOutput += it.Tag.ToString();
                    // Boolean
                    bool boolChannelsDisable = false;

                    if (comboBoxOutput.Contains(cc.LstStrMainArg[0]))
                    {
                        boolChannelsDisable = true;
                    }
                    else if (comboBoxOutput.Contains(cc.LstStrMainArg[1]))
                    {
                        boolChannelsDisable = false;
                    }
                    else
                    {
                        boolChannelsDisable = false;
                    }

                    string o = "";

                    if (boolChannelsDisable == true)
                    {

                        foreach (CheckBox chk in cc.LstChk)
                        {
                            if (chk.IsChecked == true)
                            {
                                o += chk.Content.ToString() + ", ";
                            }
                        }

                        // Remove comma and space
                        if (o != "")
                        {
                            o = o.Substring(0, o.LastIndexOf(","));
                            o = comboBoxOutput + " " + o;
                        }
                    }
                    // boolChannelsDisable = false
                    else
                    {
                        o = comboBoxOutput;
                    }
                    output += o + "\n";
                }
            }

            //ModernWpf.MessageBox.Show(output);
            return output;
        }

