        // Function: False All variables for Boolean for output
        private void FalseAllVariablesBooleanForOutput()
        {
            // Using List of Sections

            foreach (Section sec in listSections)
            {
                // Set-Associations Set Associations
                foreach (Tboxtboxtbox tb in sec.ListTboxtboxtboxSA)
                {
                    tb.BoolTF = false;
                }

                // User Folders
                foreach (Cmbs cmbs in sec.ListCmbsUF)
                {
                    cmbs.BoolTF = false;
                    cmbs.BoolWroteOppositeComment = false;
                    cmbs.WhichMainArgFirst = -1;

                }

                //// DNSoverHTTPS
                //foreach (Cmbcmbcmb cmbcmbcmb in sec.ListCmbcmbcmbDOH)
                //{
                //    cmbcmbcmb.BoolTF = false;
                //}

                foreach (var kvp in sec.DictStringBooleanSpecialFunctions.ToArray())
                {
                    var item = kvp;
                    string itemKey = item.Key.ToString();

                    string sHolder = itemKey;

                    sec.DictStringBooleanSpecialFunctions[sHolder] = false;
                }

                foreach (Cmbchk cmbchk in sec.ListCmbchkPESC)
                {
                    for (int i = 0; i < cmbchk.LstBoolMainCmb.Count; i++)
                    {
                        cmbchk.LstBoolMainCmb[i] = false;
                    }
                }

                foreach (Cmbchkalter cmbchkalter in sec.ListCmbchkalterODAU)
                {
                    for (int i = 0; i < cmbchkalter.LstBoolCmb1.Count; i++)
                    {
                        cmbchkalter.LstBoolCmb1[i] = false;
                    }
                    cmbchkalter.BoolChk1 = false;
                }

                foreach (CmbRequired r in sec.ListCmbRequiredIA)
                {
                    for (int i = 0; i < r.LstBoolCmb1.Count; i++)
                    {
                        r.LstBoolCmb1[i] = false;
                    }
                }

                foreach (Chkchkalter chkchkalter in sec.ListChkchkalterUWPFAU)
                {
                    chkchkalter.BoolChk1 = false;
                    chkchkalter.BoolChk2 = false;
                }
            }
        }

