        // Function: Chk UWP Click Hard code UWP event change
        private void ChkUWP_Click(object sender, EventArgs e)
        {
            CheckBox theCheckBoxClicked = sender as CheckBox;

            Chkchkalter cca = (Chkchkalter)theCheckBoxClicked.DataContext;

            if (cca != null)
            {
                //string n1 = cca.Chk1FunctionName.ToString() + "1";
                //string n2 = cca.Chk1FunctionName.ToString() + "2";
                //string n1 = cca.Chk1.Name.ToString() + "1";
                //string n2 = cca.Chk2.Name.ToString() + "2";
                string sVar = RemoveAllHyphen(cca.Chk1FunctionName.ToString());
                string n1 = sVar + "1";
                sVar = RemoveAllHyphen(cca.Chk2FunctionName.ToString());
                string n2 = sVar + "2";

                if ((theCheckBoxClicked.IsChecked == true) & (theCheckBoxClicked.Name == n1))
                {
                    foreach (CheckBox chk in uwpAppsSec.CheckBoxes)
                    {
                        if (chk.Name == n2)
                        {
                            chk.IsChecked = false;
                        }
                    }
                }
                // Uncheck 1st checkbox if 2nd checkbox clicked
                else if ((theCheckBoxClicked.IsChecked == true) & (theCheckBoxClicked.Name == n2))
                {
                    foreach (CheckBox chk in uwpAppsSec.CheckBoxes)
                    {
                        if (chk.Name == n1)
                        {
                            chk.IsChecked = false;
                        }
                    }
                }
            }
        }

        // Function: Load Presets: Sophia or Windows Default or PS1 with UWP selected to secondary disable
        private void LoadPresetCheckUWPChk()
        {
            // Uncheck chk 2 if chk 1 is checked
            foreach (CheckBox chk1 in uwpAppsSec.CheckBoxes)
            {
                if ((chk1.IsChecked == true) & (chk1.Name == "UninstallUWPApps1"))
                {
                    foreach (CheckBox chk2 in uwpAppsSec.CheckBoxes)
                    {
                        if (chk2.Name == "UninstallUWPApps2")
                        {
                            chk2.IsChecked = false;
                        }
                    }
                }
            }
            // Uncheck chk 1 if chk 2 is checked
            foreach (CheckBox chk1 in uwpAppsSec.CheckBoxes)
            {
                if ((chk1.IsChecked == true) & (chk1.Name == "UninstallUWPApps2"))
                {
                    foreach (CheckBox chk2 in uwpAppsSec.CheckBoxes)
                    {
                        if (chk2.Name == "UninstallUWPApps1")
                        {
                            chk2.IsChecked = false;
                        }
                    }
                }
            }
        }

        // Function: IP Conflict. Deselect if IP conflict
        private void IpConflict(object sender, EventArgs e)
        {
            var myControl = sender as Control;

            StackPanel element = VisualTreeHelper.GetParent(myControl) as StackPanel;

            string firstIP = "";
            string secondIP = "";

            List<string> listIP = new List<string>();
            List<ComboBox> listCmb = new List<ComboBox>();

            foreach (FrameworkElement fe in element.Children)
            {
                ComboBox cmb = fe as ComboBox;

                listCmb.Add(cmb);

                if (cmb != null)
                {
                    if (cmb.SelectedItem != null)
                    {
                        listIP.Add(cmb.SelectedItem.ToString());
                    }
                }
            }

            // Get IP from 1st
            if (listIP.Count > 1)
            {
                firstIP = listIP[0];
                // Get IP from 2nd                       
                secondIP = listIP[1];

                // If equal set second cmbList to empty
                if (firstIP == secondIP)
                {
                    listCmb[1].SelectedItem = null;
                }
            }
        }

