        // Function: Select opposite for special checkbox
        private void SelectOppositeSChk(Dictionary<string, List<CheckBox>> sChkList)
        {
            foreach (KeyValuePair<string, List<CheckBox>> entry in sChkList)
            {
                foreach (CheckBox chk in entry.Value)
                {
                    if (chk.IsChecked == true)
                    {
                        chk.IsChecked = false;
                    }
                    else if (chk.IsChecked == false)
                    {
                        chk.IsChecked = true;
                    }
                }
            }
        }

        // Function: Select opposite for checkbox
        private void SelectOppositeChk(List<CheckBox> chkList)
        {
            foreach (CheckBox chk in chkList)
            {
                if (chk.IsChecked == true)
                {
                    chk.IsChecked = false;
                }
                else if (chk.IsChecked == false)
                {
                    chk.IsChecked = true;
                }
            }
        }
        // Function: Select opposite for combobox
        private void SelectOppositeCmb(List<ComboBox> cbList)
        {
            foreach (ComboBox cmb in cbList)
            {
                int count = cmb.Items.Count;

                if ((count == 3) | (count == 2))
                {
                    if (cmb.SelectedIndex == 0)
                    {
                        cmb.SelectedIndex = 1;
                    }
                    else if (cmb.SelectedIndex == 1)
                    {
                        cmb.SelectedIndex = 0;
                    }

                }
                else
                {
                    ComboBoxItem cmbItem = cmb.SelectedItem as ComboBoxItem;
                    if (cmbItem != null)
                    {
                        MoreData gMD = (MoreData)cmbItem.DataContext;

                        if (gMD != null)
                        {
                            string getStringOpposite = gMD.StringMD2.ToString();

                            if (getStringOpposite != null)
                            {
                                //ModernWpf.MessageBox.Show(getStringOpposite);
                                if (getStringOpposite == "")
                                {
                                    cmb.SelectedIndex = -1;
                                }
                                else if (getStringOpposite == "Zero")
                                {
                                    cmb.SelectedIndex = 0;
                                }
                                else if (getStringOpposite == "One")
                                {
                                    cmb.SelectedIndex = 1;
                                }
                                else if (getStringOpposite == "Two")
                                {
                                    cmb.SelectedIndex = 2;
                                }
                                else if (getStringOpposite == "Three")
                                {
                                    cmb.SelectedIndex = 3;
                                }
                                else if (getStringOpposite == "Four")
                                {
                                    cmb.SelectedIndex = 4;
                                }
                                else if (getStringOpposite == "Five")
                                {
                                    cmb.SelectedIndex = 5;
                                }
                            }
                        }
                    }
                }
            }
        }

