        #region Import

        // Function: Import Menu Async
        private async System.Threading.Tasks.Task ImportMenu_NeedAsync()
        {
            OpenFileDialog openFileDialog = new OpenFileDialog();
            openFileDialog.InitialDirectory = AppDomain.CurrentDomain.BaseDirectory;
            openFileDialog.Filter = "PowerShell files (*.ps1)|*.ps1";

            if (openFileDialog.ShowDialog() == true)
            {
                if (OpenPs1File(openFileDialog.FileName))
                {
                    // Get user Sophia ps1 filename
                    userSophiaPS1ImportFilename = openFileDialog.FileName;

                    // Backup Sophia.ps1 if this file is used
                    string justFilename = Path.GetFileName(openFileDialog.FileName);
                    string justPath = Path.GetDirectoryName(openFileDialog.FileName);

                    if (justFilename == "Sophia.ps1")
                    {
                        File.Copy(Path.Combine(justPath, justFilename), Path.Combine(justPath, "Sophia_original.ps1"), true);
                    }

                    FileInfo fileInfo = new FileInfo(openFileDialog.FileName);
                    DirectoryInfo parentDirectory = fileInfo.Directory;
                    parentFolder = parentDirectory.FullName;

                    // go variable
                    bool go = false;

                    // Normal version with ARM
                    if (boolLTSC == false)
                    {
                        // Check script version default/normal                   
                        go = await SSCheckVersionAsync();
                        //go = true;
                    }
                    // LTSC version
                    else if (boolLTSC == true)
                    {
                        // Check boolLTSC script version                        
                        //go = LTSCCheckVersion();
                        go = LTSCCheckVersion();
                    }

                    // Check both Script and SSWversion is good
                    if ((go == true) & (boolSSWVersionGood == true))
                    {
                        // 10
                        if ((windowsOSVersion == "win10") & (win10or11Loaded == "10") & (boolLTSC == true))
                        {
                            LoadJson(configFilenameWindows10LTSC);
                        }
                        else if ((windowsOSVersion == "win10") & (win10or11Loaded == "10") & (boolLTSC == false))
                        {
                            LoadJson(configFilenameWindows10);
                        }
                        // 11
                        else if ((windowsOSVersion == "win11") & (win10or11Loaded == "11") & (ARMLoaded == "yes") & (cpuArch == "ARM64"))
                        {
                            LoadJson(configFilenameWindows11ARM);
                        }
                        else if ((windowsOSVersion == "win11") & (win10or11Loaded == "11") & (boolLTSC == true) & (currentEditionProEduEnterHome == "Enterprise") & (cpuArch == "X64") & (currentOSLTSCYear == "2024")) //asdf

                        {
                            LoadJson(configFilenameWindows11LTSC);
                        }
                        else if ((windowsOSVersion == "win11") & (win10or11Loaded == "11") & (boolLTSC == false) & (ARMLoaded == "no") & (cpuArch == "X64"))
                        {
                            LoadJson(configFilenameWindows11);
                        }
                        else
                        {
                            ModernWpf.MessageBox.Show(messageBoxPresetDoesNotMatchOS);
                            goto DontProcess;
                        }
                        //ModernWpf.MessageBox.Show("1");
                        //Tab disable or enable
                        EnableDisableTabs_ChangeTabHeaderColours();
                        //ModernWpf.MessageBox.Show("2");
                        // Enable UI
                        EnableUI();
                        //ModernWpf.MessageBox.Show("3");
                        // SS Window title variable load
                        //LoadSSConsoleWindowTitle();

                        // Change Tabs
                        if (boolLTSC == true)
                        {
                            //ModernWpf.MessageBox.Show("4");
                            CreateAllTabsRefresh("ltsc", windowsOSVersion);
                            //ModernWpf.MessageBox.Show("5");
                            // Get Function: Names with nothing extra
                            //GetAllFunctionNamesOnlyIntoSections_FillGlobalListStringVariableAllFunctionNamesOnly_GetAllFunctionsThatNeedOwnToolTip("ltsc", windowsOSVersion);
                        }
                        else
                        {
                            CreateAllTabsRefresh("default", windowsOSVersion);
                            // Get Function Names with nothing extra
                            //GetAllFunctionNamesOnlyIntoSections_FillGlobalListStringVariableAllFunctionNamesOnly_GetAllFunctionsThatNeedOwnToolTip("default", windowsOSVersion);
                        }

                        // Get Lists of Strings and Boolean Special Functions
                        ClearListStringsSpecialFunctions_CreateDictStringBooleanSpecialFunctions_CreateListStringSpecialFunctions();

                        ChangeToolTipsTagsUIForCurrentLanguage();

                        //ModernWpf.MessageBox.Show("Hello");

                        // Import Selection
                        MakePs1SelectListAllSections();

                        //ModernWpf.MessageBox.Show("Hello2");
                        // SPECIAL
                        //CompareAndShow();

                        //ModernWpf.MessageBox.Show("Hello3");

                        MakeSelectDictListAllSections();

                        SelectControlsFromSelectList();


                        // UWP
                        LoadPresetCheckUWPChk();

                        // Output PowerShell script after Import
                        OutputPowerShell_Click(new object(), new RoutedEventArgs());

                        // bool to not refresh more than once BUG
                        boolAlreadyRefreshed = true;

                        // Information
                        //UpdateInformationWindow();

                        //lblStatus.Text = openFileDialog.FileName + " " + statusBarPresetLoaded;
                        tblckStatusBarMessage.Text += " " + statusBarHover;


                        ToolTip newToolTip = new ToolTip();
                        newToolTip.Content = tblckStatusBarMessage.Text.ToString() + " " + statusBarHover;

                        tblckStatusBarMessage.ToolTip = newToolTip;

                        listAllToolTips.Add(newToolTip);

                    DontProcess:

                        // Select System Protection Tab at startup
                        tabInitialActions.IsSelected = true;
                    }
                }
            }
        }

