        // Function: Make PS1 Select List for All Sections
        private void MakePs1SelectListAllSections()
        {
            // SPECIAL
            listAllPS1SelectItemControls = new List<string>();

            foreach (Section sec in listSections)
            {
                sec.MakePS1SelectList();

                listAllPS1SelectItemControls.AddRange(sec.SelectList);
            }
        }

        // Function psm1 Exists
        private bool Psm1Exists(string selectFileName)
        {
            bool boolReturn = false;

            FileInfo psm1FileInfo = new FileInfo(selectFileName);
            DirectoryInfo psm1ParentDirectory = psm1FileInfo.Directory;
            string psm1ParentFolder = psm1ParentDirectory.FullName;

            string psm1FileToFind = psm1ParentFolder + "\\" + folderPsm1Filename + "\\" + psm1Filename;

            boolReturn = CheckFileExists(psm1FileToFind);

            return boolReturn;
        }

        // Function: Find Windows Version and LTSC version from psm1
        private void FindWindowsVersionAndLTSCAndARMVersionFromPsm1(string selectFileName)
        {
            // Get parent folder of input file          
            FileInfo psm1FileInfo = new FileInfo(selectFileName);
            DirectoryInfo psm1ParentDirectory = psm1FileInfo.Directory;
            string psm1ParentFolder = psm1ParentDirectory.FullName;

            // PSM1 file and path to find
            string psm1FileToFind = psm1ParentFolder + "\\" + folderPsm1Filename + "\\" + psm1Filename;

            // stringHolder for reading the PSM1 file
            string stringHolder = "";

            // return string
            string returnString = "";

            // Windows 10 or 11
            string tenOrEleven = "";

            // Strings to find
            // Get string to find "Supports Windows" from JSON
            string firstFind = wordsToFindForWindows10Psm1.Substring(0, wordsToFindForWindows10Psm1.LastIndexOf(" ")).Trim();
            // LTSC string
            string sLTSC = "LTSC";

            // Check if file exists
            if (CheckFileExists(psm1FileToFind))
            {
                // Read file
                stringHolder = System.IO.File.ReadAllText(psm1FileToFind);

                if (stringHolder.Contains(wordsToFindForWindows10Psm1))
                {
                    tenOrEleven = "10";
                }
                else if (stringHolder.Contains(wordsToFindForWindows11Psm1))
                {
                    tenOrEleven = "11";
                }

                //ModernWpf.MessageBox.Show(tenOrEleven);

                // Tools to find string
                int firstFindLength = firstFind.Length;
                int ssBegin = 0;
                int ssEnd = 0;

                // find index at end of firstFind
                //ssBegin = stringHolder.IndexOf(firstFind) + firstFindLength;
                // find index space after firstFind string
                //ssEnd = stringHolder.IndexOf(" ", ssBegin + 1);

                // Length of string to find
                int ssLength = ssEnd - ssBegin;

                // Get Windows version and trim it either 10 or 11
                //tenOrEleven = stringHolder.Substring(ssBegin, ssLength).Trim();              

                // Set global variable to tenOrEleven
                win10or11Loaded = tenOrEleven;

                // Windows 10
                if (tenOrEleven == "10")
                {
                    // LTSC finding
                    firstFindLength = sLTSC.Length;

                    // Clear variables
                    ssBegin = 0;
                    ssEnd = 0;

                    // Find LTSC
                    ssBegin = stringHolder.IndexOf(sLTSC);

                    // If LTSC found
                    if (ssBegin != -1)
                    {
                        // Find newline after finding LTSC string
                        ssEnd = stringHolder.IndexOf("\n", ssBegin + 1);

                        // Get length of LTSC to new line
                        ssLength = ssEnd - ssBegin;

                        // Get returnString from LTSC to new line
                        returnString = stringHolder.Substring(ssBegin, ssLength).Trim();
                        //ModernWpf.MessageBox.Show(returnString);
                        // Get from space to new line trimmed so getting the year of LTSC
                        returnString = returnString.Substring(returnString.IndexOf(" ")).Trim();

                        LTSCYearLoaded = returnString;

                        ARMLoaded = "no";

                        //ModernWpf.MessageBox.Show(returnString);
                    }
                    else
                    {
                        LTSCYearLoaded = "";
                        ARMLoaded = "no";
                    }
                }

                else if (tenOrEleven == "11")
                {
                    firstFindLength = sLTSC.Length;
                    ssBegin = 0;
                    ssEnd = 0;

                    ssBegin = stringHolder.IndexOf(sLTSC);


                    // LTSC
                    if (ssBegin != -1)
                    {
                        // Find newline after finding LTSC string
                        ssEnd = stringHolder.IndexOf("\n", ssBegin + 1);

                        // Get length of LTSC to new line
                        ssLength = ssEnd - ssBegin;

                        // Get returnString from LTSC to new line
                        returnString = stringHolder.Substring(ssBegin, ssLength).Trim();

                        // Get from space to new line trimmed so getting the year of LTSC
                        returnString = returnString.Substring(returnString.IndexOf(" ")).Trim();

                        LTSCYearLoaded = returnString;
                        ARMLoaded = "no";
                    }
                    else
                    {
                        LTSCYearLoaded = "";
                        ARMLoaded = "no";
                    }

                    // ARM
                    ssBegin = stringHolder.IndexOf(wordsToFindForWindows11ARMPsm1);
                    if (ssBegin != -1)
                    {
                        ARMLoaded = "yes";
                    }
                    else
                    {
                        ARMLoaded = "no";
                    }
                    //ModernWpf.MessageBox.Show(ARMImported);
                }
                ARMLoaded = ARMLoaded.ToLower();
            }
        }

