                    //else if (correctCount == correctLTSC2024TotalNumber)
                    {



                        int ScriptTopSubstract = SubstractReturnBetween(stringHolder, "#Requires -RunAsAdministrator");

                        scriptTop = FirstStringReturnBetween(stringHolder, "#Requires -RunAsAdministrator", startLineRegionSystemProtection, ScriptTopSubstract);
                        scriptTop = scriptTop.Substring(0, scriptTop.Length - startLineRegionSystemProtection.Length);

                        //for (int i = 0; i < listSections.Count - 1; i++)
                        //{
                        //    int substract = SubstractReturn(stringHolder, listSections[i].FindString);
                        //    listSections[i].SelectString = FirstStringReturn(stringHolder, listSections[i].FindString, listSections[i + 1].FindString, substract);
                        //}

                        int initialActionsSubstract = SubstractReturn(stringHolder, initialActionsSec.FindString);
                        initialActionsSec.SelectString = FirstStringReturn(stringHolder, initialActionsSec.FindString, systemProtectionSec.FindString, initialActionsSubstract);

                        int systemProtectionSubstract = SubstractReturn(stringHolder, systemProtectionSec.FindString);
                        systemProtectionSec.SelectString = FirstStringReturn(stringHolder, systemProtectionSec.FindString, privacyTelemetrySec.FindString, systemProtectionSubstract);

                        int privacyTelemetrySubstract = SubstractReturn(stringHolder, privacyTelemetrySec.FindString);
                        privacyTelemetrySec.SelectString = FirstStringReturn(stringHolder, privacyTelemetrySec.FindString, uiPersonalizationSec.FindString, privacyTelemetrySubstract);

                        int uiPersonalSubstract = SubstractReturn(stringHolder, uiPersonalizationSec.FindString);
                        uiPersonalizationSec.SelectString = FirstStringReturn(stringHolder, uiPersonalizationSec.FindString, systemSec.FindString, uiPersonalSubstract);



                        int systemSubstract = SubstractReturn(stringHolder, systemSec.FindString);
                        systemSec.SelectString = FirstStringReturn(stringHolder, systemSec.FindString, wslSec.FindString, systemSubstract);

                        //ModernWpf.MessageBox.Show("asdf");
                        int wslSubstract = SubstractReturn(stringHolder, wslSec.FindString);
                        wslSec.SelectString = FirstStringReturn(stringHolder, wslSec.FindString, gamingSec.FindString, wslSubstract);



                        //int startMenuSubstract = SubstractReturn(stringHolder, startMenuSec.FindString);
                        //startMenuSec.SelectString = FirstStringReturn(stringHolder, startMenuSec.FindString, uwpAppsSec.FindString, startMenuSubstract);

                        //int uwpSubstract = SubstractReturn(stringHolder, uwpAppsSec.FindString);
                        //uwpAppsSec.SelectString = FirstStringReturn(stringHolder, uwpAppsSec.FindString, gamingSec.FindString, uwpSubstract);

                        int gamingSubstract = SubstractReturn(stringHolder, gamingSec.FindString);
                        gamingSec.SelectString = FirstStringReturn(stringHolder, gamingSec.FindString, scheduledTasksSec.FindString, gamingSubstract);

                        int scheduledTasksSubstract = SubstractReturn(stringHolder, scheduledTasksSec.FindString);
                        scheduledTasksSec.SelectString = FirstStringReturn(stringHolder, scheduledTasksSec.FindString, defenderSecuritySec.FindString, scheduledTasksSubstract);

                        int defenderSecuritySubstract = SubstractReturn(stringHolder, defenderSecuritySec.FindString);
                        defenderSecuritySec.SelectString = FirstStringReturn(stringHolder, defenderSecuritySec.FindString, contextMenuSec.FindString, defenderSecuritySubstract);

                        int contextMenuSubstract = SubstractReturn(stringHolder, contextMenuSec.FindString);
                        contextMenuSec.SelectString = FirstStringReturn(stringHolder, contextMenuSec.FindString, updatePoliciesSec.FindString, contextMenuSubstract);

                        int updatePoliciesSubstract = SubstractReturn(stringHolder, updatePoliciesSec.FindString);
                        updatePoliciesSec.SelectString = FirstStringReturn(stringHolder, updatePoliciesSec.FindString, endLineRegionUpdatePolicies, updatePoliciesSubstract);

                        //ModernWpf.MessageBox.Show("123");

                        boolLTSC = true;

                        Clear();

                        //lblStatus.Text = selectFileName + " " + statusBarPresetLoaded;

                        boolOpenPS1Successful = true;
                    }
                }
                catch (Exception ex)
                {
                    ModernWpf.MessageBox.Show(selectFileName + " " + messageBoxPresetNotComp + " ERROR: " + ex.Message);

                    boolOpenPS1Successful = false;
                }
                // Not compatible
                //else
                //{

                //}

                // Return successful opening of PS1
                return boolOpenPS1Successful;
            }
            // File does not exists
            else if ((!boolPsm1FileName) & (!boolPs1FileName))
            {
                string message = selectFileName + " " + messageBoxDoesNotExist + "\n" + "Sophia.psm1" + " " + messageBoxDoesNotExist;
                ModernWpf.MessageBox.Show(message);
            }
            else if (!boolPs1FileName)
            {
                string message = selectFileName + " " + messageBoxDoesNotExist;
                ModernWpf.MessageBox.Show(message);
            }
            else if (!boolPsm1FileName)
            {
                string message = messageBoxPS1FileHasToBeInFolder;
                ModernWpf.MessageBox.Show(message);
            }

            // Return bool of PS1 file open successfully            
            return boolOpenPS1Successful;
        }
