        // Function: Select CheckBoxs using list of string
        private void CheckCheckBox(List<CheckBox> chkList, List<string> selectList)
        {
            foreach (string s in selectList)
            {
                foreach (CheckBox chk in chkList)
                {
                    // This is run twice fix it Firefox
                    //if ((s.Contains("DotNetRuntimes")) & (chk.Tag.ToString().Contains("DotNetRuntimes")))
                    //if (chk.Tag.ToString().Contains("UWP"))
                    //{
                    //    ModernWpf.MessageBox.Show(s + ":" + chk.Tag.ToString());
                    //}

                    //if ((s.Contains("OneDrive")) && chk.Tag.ToString().Contains("OneDrive"))
                    //{
                    //    ModernWpf.MessageBox.Show(s + " : " + chk.Tag.ToString());
                    //}

                    string s2 = s;
                    if (s2.Length > 0)
                    {
                        if (s2.Substring(s2.Length - 1, 1) == "-")
                        {
                            s2 = s2.Substring(0, s2.LastIndexOf(" "));
                            //ModernWpf.MessageBox.Show(s2 + ":" + chk.Tag.ToString());
                        }

                        if (chk.Tag.ToString().Trim() == s2.Trim() + " -")
                        {
                            chk.IsChecked = true;
                        }
                        if ((s.Trim()) == (chk.Tag.ToString().Trim()))
                        {
                            chk.IsChecked = true;
                        }
                    }
                }
            }
        }

        // Function: Select ComboBoxItem in ComboBox using list of string
        private void SelectItemInComboBox(List<ComboBox> cmbList, List<string> selectList)
        {
            foreach (string s in selectList)
            {
                foreach (ComboBox cmb in cmbList)
                {
                    foreach (ComboBoxItem it in cmb.Items)
                    {
                        //if (it.Tag.ToString().Contains("OneDrive") & !it.Tag.ToString().Contains("Ad"))
                        //{
                        //    //ModernWpf.MessageBox.Show(it.Tag.ToString() + ":" + s);
                        //}
                        if (it.Tag != null)
                        {
                            if (it.Tag.ToString().Trim().Equals(s.Trim()))
                            {
                                cmb.SelectedItem = it;
                            }
                        }

                    }
                }
            }
        }

        // Function: Select ComboBoxItem in ComboBox using list of string User folders UserFolders
        public void SelectItemInComboBoxComboBoxUF(List<Cmbs> listcmbs, Dictionary<string, string> selectdictss)
        {
            foreach (KeyValuePair<string, string> entry in selectdictss)
            {
                string kvp = entry.Key + " " + entry.Value;

                foreach (Cmbs cmbs in listcmbs)
                {
                    foreach (ComboBox cmb in cmbs.LstCmb1)
                    {
                        foreach (ComboBoxItem it in cmb.Items)
                        {
                            if (it.Tag.ToString().Trim().Equals(kvp.Trim()))
                            {
                                cmb.SelectedItem = it;
                            }
                        }
                    }
                }
            }
        }

