                                    }
                                    else if (item.WindowsDefault3 == "Five")
                                    {
                                        ol.Add(item.Function.ToString() + " -" + item.Arg3.Five.Tag.ToString());
                                    }

                                    o.AddRange(ol);

                                    ol = new List<string>();
                                }

                            }
                            catch (Exception e)
                            {
                                ModernWpf.MessageBox.Show(item.Function.ToString() + " error! " + e.Message);
                            }
                        }

                        output.AddRange(o);

                        o = new List<string>(); ;

                    }
                }
                catch (Exception e)
                {
                    ModernWpf.MessageBox.Show(item.Function.ToString() + " error! " + e.Message);
                }
            }

