        // Function: Select User Folders Combobox
        private void SelectUserFoldersCombobox(Section sec)
        {
            List<string> keyValueList = new List<string>();

            List<string> keyList = new List<string>(uiPersonalizationSec.SelectDictStringStringUF.Keys);

            foreach (var item in uiPersonalizationSec.SelectDictStringStringUF)
            {
                keyValueList.Add(item.Key + " " + item.Value);
            }

            foreach (Cmbs cmbs in sec.ListCmbsUF)
            {
                foreach (ComboBox cmb in cmbs.LstCmb1)
                {
                    foreach (ComboBoxItem it in cmb.Items)
                    {
                        foreach (string s in keyValueList)
                        {
                            if (it.Tag.ToString().Equals(s))
                            {
                                cmb.SelectedItem = it;
                            }
                        }
                    }
                }
            }
        }

