        // Function: Special Selection for PreventEdgeShortcutCreation
        private void CheckDictStringListChk2PESC(Dictionary<string, List<CheckBox>> dictStrings, List<string> sListStrings)
        {
            foreach (KeyValuePair<string, List<CheckBox>> entry in dictStrings)
            {
                foreach (CheckBox chk in entry.Value)
                {
                    foreach (string s in sListStrings)
                    {
                        if (chk.Tag.ToString().Trim() == s.Trim())
                        {
                            chk.IsChecked = true;
                        }
                    }
                }
            }
        }

        // Function: Special Selectioning
        private void CheckDictStringListChk(Dictionary<string, List<CheckBox>> dictStrings, Dictionary<string, List<string>> sDictStrings)
        {
            foreach (KeyValuePair<string, List<string>> entry in sDictStrings)
            {
                if (dictStrings.ContainsKey(entry.Key))
                {
                    foreach (string s in entry.Value)
                    {
                        foreach (CheckBox chk in dictStrings[entry.Key])
                        {
                            if (chk.Content.ToString() == s)
                                chk.IsChecked = true;
                        }
                    }
                }
            }
        }

