        // Function: OpenFileDialog for Program Path
        private void BtnProgramPathSetAssociationOpenFileDialog(object sender, EventArgs e)
        {
            var myValue = ((Button)sender).DataContext;
            Tboxtboxtbox tbTbTb1 = (Tboxtboxtbox)myValue;

            OpenFileDialog openFileDialog = new OpenFileDialog();
            openFileDialog.InitialDirectory = AppDomain.CurrentDomain.BaseDirectory;
            openFileDialog.Filter = "Program (*.exe)|*.exe";

            if (openFileDialog.ShowDialog() == true)
            {
                string o = "";
                if (openFileDialog.FileName.Contains('\\'))
                {
                    o = "\"" + openFileDialog.FileName + "\"";
                }
                tbTbTb1.Tbox1.Text = o;
            }
        }

        // Function: OpenFileDialog for Icon
        private void BtnIcoSetAssociationOpenFileDialog(object sender, EventArgs e)
        {
            var myValue = ((Button)sender).DataContext;
            Tboxtboxtbox tbTbTb1 = (Tboxtboxtbox)myValue;

            OpenFileDialog openFileDialog = new OpenFileDialog();
            openFileDialog.InitialDirectory = AppDomain.CurrentDomain.BaseDirectory;
            openFileDialog.Filter = "All Files (*.*)|*.*";

            if (openFileDialog.ShowDialog() == true)
            {
                string o = "";
                if (openFileDialog.FileName.Contains('\\'))
                {
                    o = "\"" + openFileDialog.FileName + "\"";
                }
                tbTbTb1.Tbox3.Text = o;
            }
        }

        // Function: fill cmbList SetAssociation
        private void FillSA(Section sec)
        {
            foreach (Tboxtboxtbox tbox in sec.ListTboxtboxtboxSA)
            {
                string tboxfn = tbox.TboxFunctionName;               

                foreach (KeyValuePair<string, List<string>> entry in systemSec.SelectDictStringListStringSA)
                {
                    string ek = entry.Key;

                    if (ek.Contains(tboxfn))
                    {
                        tbox.CmbTboxTboxTbox1.Items.Add(entry.Key);

                        //ModernWpf.MessageBox.Show(entry.Key);
                    }
                }
                // Select first index
                tbox.CmbTboxTboxTbox1.SelectedIndex = 0;
            }
        }

        // Function: Change SetAssociation controls when changed
        private void CmbSetAssociation_SelectedIndexChanged(object sender, EventArgs e)
        {
            // Send current class object of tbTbTb1 to get the object and not this global one set to make many more Set-Associations
            var myValue = ((ComboBox)sender).DataContext;
            Tboxtboxtbox tbTbTb1 = (Tboxtboxtbox)myValue;

            tbTbTb1.Tbox1.Text = "";
            tbTbTb1.Tbox2.Text = "";
            tbTbTb1.Tbox3.Text = "";
            tbTbTb1.Cmb2.SelectedIndex = -1;

            var currentSelectedIndex = tbTbTb1.CmbTboxTboxTbox1.SelectedIndex;

            if (tbTbTb1.CmbTboxTboxTbox1.SelectedItem != null)
            {
                // Get current index value
                string value = tbTbTb1.CmbTboxTboxTbox1.SelectedItem.ToString();

                List<string> v = new List<string>();

                if (systemSec.SelectDictStringListStringSA.ContainsKey(value))
                {
                    v = systemSec.SelectDictStringListStringSA[value];

                    // You must assign the textbox themselves and not place them in another variable for one Set-Association
                    if (v.Count > 2)
                    {
                        tbTbTb1.Tbox1.Text = v[0];
                        tbTbTb1.Tbox2.Text = v[1];
                        tbTbTb1.Tbox3.Text = v[2];
                        //Microsoft

                        if (tbTbTb1.Tbox3.Text.Contains(",") && (tbTbTb1.Tbox3.Text.Contains("\"")) && (tbTbTb1.Tbox3.Text.IndexOf(",") > 2))
                        {
                            int sStart = tbTbTb1.Tbox3.Text.LastIndexOf(",") + 1;

                            int sEnd = tbTbTb1.Tbox3.Text.LastIndexOf("\"");

                            //if
                            if (sStart != -1 && sEnd != -1)
                            {
                                string s = tbTbTb1.Tbox3.Text.Substring(sStart, sEnd - sStart);
                                //ModernWpf.MessageBox.Show(s + " : " + s.Length.ToString());
                                int intS = Int32.Parse(s.Trim());
                                tbTbTb1.Cmb2.SelectedValue = intS;
                            }
                        }
                    }
                    else if (v.Count == 2)
                    {
                        tbTbTb1.Tbox1.Text = v[0];
                        tbTbTb1.Tbox2.Text = v[1];
                        tbTbTb1.Tbox3.Text = "";
                    }
                }
            }
        }

        // Set-Association Button Save
        private void BtnSaveSetAssociation_Click(object sender, EventArgs e)
        {
            var myValue = ((Button)sender).DataContext;
            Tboxtboxtbox tbTbTb1 = (Tboxtboxtbox)myValue;

            // List to save the textboxes
            List<string> saveList = new List<string>();

            // bool to save if all conditions are met. False first
            bool okSave = false;

            // All 3 textboxes

            if ((tbTbTb1.Tbox1.Text != "") & (tbTbTb1.Tbox2.Text != "") & (tbTbTb1.Tbox3.Text != ""))
            {
                saveList.Add(tbTbTb1.Tbox1.Text);
                saveList.Add(tbTbTb1.Tbox2.Text);
                saveList.Add(tbTbTb1.Tbox3.Text);
                okSave = true;
            }
            // 2 textboxes
            else if ((tbTbTb1.Tbox1.Text != "") & (tbTbTb1.Tbox2.Text != ""))
            {
                saveList.Add(tbTbTb1.Tbox1.Text);
                saveList.Add(tbTbTb1.Tbox2.Text);
                okSave = true;
            }

            if (okSave == true) // Taco
            {
                if ((tbTbTb1.CmbTboxTboxTbox1.SelectedItem != null))// | (tbTbTb1.CmbTboxTboxTbox1.SelectedItem.ToString() != ""))
                {
                    string saKey = tbTbTb1.CmbTboxTboxTbox1.SelectedItem.ToString();

                    systemSec.SelectDictStringListStringSA[saKey] = saveList;

                }
                else
                {
                    // Count from Sophia.ps1 initial count global
                    string fn = tbTbTb1.TboxFunctionName;

                    int counter = 0;

                    foreach (var item in systemSec.SelectDictStringListStringSA)
                    {
                        if (item.Key.Contains(fn))
                        {
                            counter++;
                        }
                    }

                    if (counter != 0)
                    {
                        tbTbTb1.CountTboxInt = counter;

                        tbTbTb1.CountTboxInt += 1;

                        // String creation
                        string prefix = tbTbTb1.TboxFunctionName;
                        string newSAKey = prefix + "-" + tbTbTb1.CountTboxInt.ToString();

                        // Add new string to combobox
                        tbTbTb1.CmbTboxTboxTbox1.Items.Add(newSAKey);
                        //cmbSetAssocation.Items.Add(newsakey);

                        //ModernWpf.MessageBox.Show(newSAKey);
                        systemSec.SelectDictStringListStringSA.Add(newSAKey, saveList);

                        // Set index to new cmbItem
                        tbTbTb1.CmbTboxTboxTbox1.SelectedIndex = -1;

                        tbTbTb1.CmbTboxTboxTbox1.SelectedIndex = tbTbTb1.CmbTboxTboxTbox1.Items.Count - 1;

                        // deselect icon numbering combobox
                        tbTbTb1.Cmb2.SelectedIndex = -1;
                    }
                    else
                    {
                        tbTbTb1.CountTboxInt = 1;

                        // String creation
                        string prefix = tbTbTb1.TboxFunctionName;
                        string newSAKey = prefix + "-" + tbTbTb1.CountTboxInt.ToString();

                        // Add new string to combobox
                        tbTbTb1.CmbTboxTboxTbox1.Items.Add(newSAKey);

                        systemSec.SelectDictStringListStringSA.Add(newSAKey, saveList);

                        // Set index to new cmbItem
                        tbTbTb1.CmbTboxTboxTbox1.SelectedIndex = -1;
                        tbTbTb1.CmbTboxTboxTbox1.SelectedIndex = tbTbTb1.CmbTboxTboxTbox1.Items.Count - 1;

                        // deselect icon numbering combobox
                        tbTbTb1.Cmb2.SelectedIndex = -1;
                    }
                }
            }
        }

        // Set-Association Button Plus +
        private void BtnPlusSetAssociation_Click(object sender, EventArgs e)
        {
            var myValue = ((Button)sender).DataContext;
            Tboxtboxtbox tbTbTb1 = (Tboxtboxtbox)myValue;

            // Clear
            tbTbTb1.Tbox1.Text = "";
            tbTbTb1.Tbox2.Text = "";
            tbTbTb1.Tbox3.Text = "";

            // Count from Sophia.ps1 initial count global
            string fn = tbTbTb1.TboxFunctionName;

            int counter = 0;

            foreach (var item in systemSec.SelectDictStringListStringSA)
            {
                if (item.Key.Contains(fn))
                {
                    counter++;
                }
            }

            if (counter != 0)
            {
                tbTbTb1.CountTboxInt = counter;

                tbTbTb1.CountTboxInt += 1;

                // String creation
                string prefix = tbTbTb1.TboxFunctionName;
                string newsakey = prefix + "-" + tbTbTb1.CountTboxInt.ToString();

                // Add new string to combobox
                tbTbTb1.CmbTboxTboxTbox1.Items.Add(newsakey);

                // Save to dictionary
                List<string> saveList = new List<string>();

                saveList.Add(tbTbTb1.Tbox1.Text);
                saveList.Add(tbTbTb1.Tbox2.Text);
                saveList.Add(tbTbTb1.Tbox3.Text);

                if (!systemSec.SelectDictStringListStringSA.ContainsKey(newsakey))
                {
                    // Add item
                    systemSec.SelectDictStringListStringSA.Add(newsakey, saveList);

                    // Set index to new cmbItem
                    tbTbTb1.CmbTboxTboxTbox1.SelectedIndex = tbTbTb1.CmbTboxTboxTbox1.Items.Count - 1;

                    // deselect icon numbering combobox
                    tbTbTb1.Cmb2.SelectedIndex = -1;
                }
            }
            else
            {
                tbTbTb1.CountTboxInt = 1;

                // String creation
                string prefix = tbTbTb1.TboxFunctionName;
                string newsakey = prefix + "-" + tbTbTb1.CountTboxInt.ToString();

                // Add new string to combobox
                tbTbTb1.CmbTboxTboxTbox1.Items.Add(newsakey);

                // Save to dictionary
                List<string> saveList = new List<string>();

                saveList.Add(tbTbTb1.Tbox1.Text);
                saveList.Add(tbTbTb1.Tbox2.Text);
                saveList.Add(tbTbTb1.Tbox3.Text);

                systemSec.SelectDictStringListStringSA.Add(newsakey, saveList);

                // Set index to new cmbItem
                tbTbTb1.CmbTboxTboxTbox1.SelectedIndex = tbTbTb1.CmbTboxTboxTbox1.Items.Count - 1;

                // deselect icon numbering combobox
                tbTbTb1.Cmb2.SelectedIndex = -1;
            }
        }

        // Set-Association Button Minus -
        private void BtnMinusSetAssociation_Click(object sender, EventArgs e)
        {
            var myValue = ((Button)sender).DataContext;
            Tboxtboxtbox tbTbTb1 = (Tboxtboxtbox)myValue;

            if (tbTbTb1.CmbTboxTboxTbox1.SelectedItem != null)
            {
                // Get cmbItem at selected cmbItem
                string saKey = tbTbTb1.CmbTboxTboxTbox1.SelectedItem.ToString();

                // Remove from combo
                tbTbTb1.CmbTboxTboxTbox1.Items.Remove(saKey);
                // Remove from dictionary
                systemSec.SelectDictStringListStringSA.Remove(saKey);

                // Refresh
                tbTbTb1.CmbTboxTboxTbox1.Items.Refresh();

                // Select last cmbItem
                tbTbTb1.CmbTboxTboxTbox1.SelectedIndex = tbTbTb1.CmbTboxTboxTbox1.Items.Count - 1;

                // icon combobox number reset
                tbTbTb1.Cmb2.SelectedIndex = -1;
            }
        }

        // Function: Ico combobox selection change
        private void CmbIcoSetAssociation_SelectionChanged(object sender, EventArgs e)
        {
            var myValue = ((ComboBox)sender).DataContext;
            Tboxtboxtbox tbTbTb1 = (Tboxtboxtbox)myValue;

            if (tbTbTb1.Cmb2.SelectedItem != null)
            {
                string value = tbTbTb1.Cmb2.SelectedItem.ToString();
                string sStart = "";
                string sEnd = "";

                // Does not contain a number
                if ((tbTbTb1.Tbox3.Text != "") & (!tbTbTb1.Tbox3.Text.Contains(",")) & (tbTbTb1.Tbox3.Text.Contains("\"")))
                {
                    sStart = tbTbTb1.Tbox3.Text.Substring(0, tbTbTb1.Tbox3.Text.LastIndexOf("\""));

                    sEnd = tbTbTb1.Tbox3.Text.Substring(tbTbTb1.Tbox3.Text.LastIndexOf("\""));

                    tbTbTb1.Tbox3.Text = sStart + "," + value + sEnd;
                }
                // Contains a number ','
                else if ((tbTbTb1.Tbox3.Text != "") & (tbTbTb1.Tbox3.Text.Contains(",")) & (tbTbTb1.Tbox3.Text.Contains("\"")))
                {
                    sStart = tbTbTb1.Tbox3.Text.Substring(0, tbTbTb1.Tbox3.Text.LastIndexOf(","));

                    sEnd = tbTbTb1.Tbox3.Text.Substring(tbTbTb1.Tbox3.Text.LastIndexOf("\""));

                    tbTbTb1.Tbox3.Text = sStart + "," + value + sEnd;
                }
            }
        }

