        #region Enable / Disable Controls

        // Function: Disable Menu Items and Buttons
        private void DisableMenuItemsAndButtons()
        {
            // Menu disabled
            menuAutosave.IsEnabled = false;
            menuPresets.IsEnabled = false;
            menuOpposite.IsEnabled = false;
            menuClear.IsEnabled = false;

            // Button disabled
            btnRefreshConsoleOutputPowerShell.IsEnabled = false;
            btnRunPowerShell.IsEnabled = false;
        }

        // Function: Enable UI
        private void EnableUI()
        {
            // Menu enabled
            menuAutosave.IsEnabled = true;
            menuPresets.IsEnabled = true;
            menuOpposite.IsEnabled = true;
            menuClear.IsEnabled = true;

            // Button enabled
            btnRefreshConsoleOutputPowerShell.IsEnabled = true;
            btnRunPowerShell.IsEnabled = true;
        }

        // Function: Enable Disable tabs and Change Tab header colours
        private void EnableDisableTabs_ChangeTabHeaderColours()
        {
            //ModernWpf.MessageBox.Show(boolLTSC.ToString() + ", " + LTSCversion + ", " + sCurrentEditionProEduEnterHome);
            // Colors
            Color colWhite = (Color)ColorConverter.ConvertFromString("White");
            Color colBlack = (Color)ColorConverter.ConvertFromString("Black");
            Color colRed = System.Windows.Media.Color.FromRgb(148, 0, 0);
            Color colBlue = System.Windows.Media.Color.FromRgb(41, 108, 159);

            // Here we are
