                    App.Current.Resources["OneDriveColorText"] = new SolidColorBrush(colRed);
                    App.Current.Resources["WSLColorText"] = new SolidColorBrush(colBlack);
                    App.Current.Resources["UWPColorText"] = new SolidColorBrush(colRed);
                }
            }

            // Other
            else if (boolLTSC == false)
            {
                //ModernWpf.MessageBox.Show("false");
                tabOneDrive.IsEnabled = true;
                tabWSL.IsEnabled = true;
                tabUWP.IsEnabled = true;
                tabGaming.IsEnabled = true;

                App.Current.Resources["OneDriveColor"] = new SolidColorBrush(colBlue);
                App.Current.Resources["WSLColor"] = new SolidColorBrush(colBlue);
                App.Current.Resources["UWPColor"] = new SolidColorBrush(colBlue);
