                }
                else
                {
                    App.Current.Resources["OneDriveColorText"] = new SolidColorBrush(colBlack);
                    App.Current.Resources["WSLColorText"] = new SolidColorBrush(colBlack);
                    App.Current.Resources["UWPColorText"] = new SolidColorBrush(colBlack);
                    App.Current.Resources["GamingColorText"] = new SolidColorBrush(colBlack);
                }
            }
            else
            {
                ModernWpf.MessageBox.Show(messageBoxPresetDoesNotMatchOS);
            }

