        // Function: Disable Controls
        private void DisableControls()
        {
            // For loop of Sections
            foreach (Section sec in listSections)
            {
                DisableComboBox(sec.ComboBoxes);
                DisableCheckBox(sec.CheckBoxes);
                DisableSpecialCheckBox(sec.DictStringListChk);

                // PESC
                foreach (var item in sec.DictStringListChk2PESC)
                {
                    List<CheckBox> lcb = item.Value;

                    foreach (CheckBox cb in lcb)
                    {
                        cb.IsEnabled = false;
                    }
                }

                //// DNSoverHTTPS
                //foreach (Cmbcmbcmb ccc in sec.ListCmbcmbcmbDOH)
                //{
                //    foreach (ComboBox cmb in ccc.LstCmb1)
                //    {
                //        cmb.IsEnabled = false;
                //    }
                //}

                // Set-Associations
                foreach (Tboxtboxtbox ttt in sec.ListTboxtboxtboxSA)
                {
                    ttt.CmbTboxTboxTbox1.IsEnabled = false;
                    ttt.Tbox1.IsEnabled = false;
                    ttt.Tbox2.IsEnabled = false;
                    ttt.Tbox3.IsEnabled = false;
                    ttt.Cmb2.IsEnabled = false;

                    foreach (Button btn in ttt.ListBtns)
                    {
                        btn.IsEnabled = false;
                    }
                }
            }
        }

        // Function: Disable Checkbox
        private void DisableCheckBox(List<CheckBox> chkList)
        {
            foreach (CheckBox chk in chkList)
            {
                chk.IsEnabled = false;
            }
        }

        // Function: Enable combobox
        private void EnableComboBox(List<ComboBox> cmbList)
        {
            foreach (ComboBox cmb in cmbList)
            {
                cmb.IsEnabled = true;
            }
        }

        // Function: Disable combobox
        private void DisableComboBox(List<ComboBox> cmbList)
        {
            foreach (ComboBox cmb in cmbList)
            {
                cmb.IsEnabled = false;
            }
        }

        // Function: Disable special checkbox
        private void DisableSpecialCheckBox(Dictionary<string, List<CheckBox>> schk)
        {
            foreach (KeyValuePair<string, List<CheckBox>> entry in schk)
            {
                foreach (CheckBox chk in entry.Value)
                {
                    chk.IsEnabled = false;
                }
            }
        }

