        // Function: Change ToolTip to other language
        private void ChangeToolTipBasedOnInputLang(string ToolTipsLang)
        {
            if (CheckFileExists(ToolTipsLang))
            {
                // Clear
                foreach (Section sec in listSections)
                {
                    sec.ToolTipString = "";
                    sec.ToolTipList = new List<string>();
                    sec.ToolTipDict = new Dictionary<string, string>();
                    sec.SDictStringListString = new Dictionary<string, List<string>>();
                    sec.LabelToolTipDict = new Dictionary<string, string>();
                }

                listAllToolTips = new List<ToolTip>();

                // Open tooltip file
                OpenToolTipFile(ToolTipsLang);
                MakeToolTipListAllSections();
                MakeToolTipDictAllSections();
                AddToolTipToControls();

                // ToolTip to Label
                MakeLabelDictAllSections();
                AddToolTipToLabelAllSections();
            }
        }

        // Function: Add tooltips to all labels in tabs
        private void AddToolTipToLabelAllSections()
        {

            // Clear
            foreach (Section sec in listSections)
            {
                AddToolTipToLabel(sec.Labels, sec.LabelToolTipDict);
            }
        }

        // Function: Add tooltip to label
        private void AddToolTipToLabel3(List<System.Windows.Controls.Label> lblList, Dictionary<string, string> lblToolTipDict)
        {
            foreach (System.Windows.Controls.Label l in lblList)
            {
                // If label is TextBlock
                if (l.Content is TextBlock)
                {
                    string s = "";
                    TextBlock tb = l.Content as TextBlock;
                    s = tb.Text;
                    if (lblToolTipDict.ContainsKey(s))
                    {
                        ToolTip tt = new ToolTip();

                        double factor = double.Parse(sScaleSelected) / 100;


                        tt.FontSize = 12 * factor;
                        tt.Content = lblToolTipDict[s];

                        tb.ToolTip = tt;
                    }
                }
                // Normal
                else
                {
                    if (l.Content != null)
                    {
                        if (lblToolTipDict.ContainsKey(l.Content.ToString()))
                        {
                            //l.ToolTip = lblToolTipDict[l.Content.ToString()];
                            ToolTip tt = new ToolTip();

                            double factor = double.Parse(sScaleSelected) / 100;


                            tt.FontSize = 12 * factor;
                            tt.Content = lblToolTipDict[l.Content.ToString()];

                            l.ToolTip = tt;
                        }
                        // Special case - Set-Association // Firefox to make json
                        if (l.DataContext != null)
                        {
                            foreach (Section sec in listSections)
                            {
                                if (sec.ToolTipDict.ContainsKey(l.DataContext.ToString()))
                                {
                                    //l.ToolTip = sec.ToolTipDict[l.DataContext.ToString()];

                                    ToolTip tt = new ToolTip();

                                    double factor = double.Parse(sScaleSelected) / 100;


                                    tt.FontSize = 12 * factor;
                                    tt.Content = sec.ToolTipDict[l.DataContext.ToString()];

                                    l.ToolTip = tt;
                                }
                            }
                        }
                    }
                }
            }
        }

        // Function: Add tooltip to label
        private void AddToolTipToLabel(List<System.Windows.Controls.Label> lblList, Dictionary<string, string> lblToolTipDict)
        {
            foreach (System.Windows.Controls.Label l in lblList)
            {
                ToolTip tt = new ToolTip();
                // If label is TextBlock
                if (l.Content is TextBlock)
                {
                    string s = "";
                    TextBlock tb = l.Content as TextBlock;
                    s = tb.Text;
                    if (lblToolTipDict.ContainsKey(s))
                    {
                        tt.Content = lblToolTipDict[s];
                        tb.ToolTip = tt;
                    }
                }
                // Normal
                else
                {
                    if (l.Content != null)
                    {
                        if (lblToolTipDict.ContainsKey(l.Content.ToString()))
                        {
                            //l.ToolTip = lblToolTipDict[l.Content.ToString()];

                            tt.Content = lblToolTipDict[l.Content.ToString()];
                            l.ToolTip = tt;
                        }
                        // Special case - Set-Association // Firefox to make json
                        if (l.DataContext != null)
                        {
                            foreach (Section sec in listSections)
                            {
                                if (sec.ToolTipDict.ContainsKey(l.DataContext.ToString()))
                                {
                                    //l.ToolTip = sec.ToolTipDict[l.DataContext.ToString()];

                                    tt.Content = sec.ToolTipDict[l.DataContext.ToString()];
                                    l.ToolTip = tt;
                                }
                            }
                        }
                    }
                }
                listAllToolTips.Add(tt);
            }
        }

        // Function: Add tooltip to label
        private void AddToolTipToLabel4(List<System.Windows.Controls.Label> lblList, Dictionary<string, string> lblToolTipDict)
        {
            foreach (System.Windows.Controls.Label l in lblList)
            {
                // If label is TextBlock
                if (l.Content is TextBlock)
                {
                    string s = "";
                    TextBlock tb = l.Content as TextBlock;
                    s = tb.Text;
                    if (lblToolTipDict.ContainsKey(s))
                    {

                        tb.ToolTip = lblToolTipDict[s];
                    }
                }
                // Normal
                else
                {
                    if (l.Content != null)
                    {
                        if (lblToolTipDict.ContainsKey(l.Content.ToString()))
                        {
                            l.ToolTip = lblToolTipDict[l.Content.ToString()];
                        }
                        // Special case - Set-Association // Firefox to make json
                        if (l.DataContext != null)
                        {
                            foreach (Section sec in listSections)
                            {
                                if (sec.ToolTipDict.ContainsKey(l.DataContext.ToString()))
                                {
                                    l.ToolTip = sec.ToolTipDict[l.DataContext.ToString()];
                                }
                            }
                        }
                    }
                }
            }
        }

