        // Function: Load the tooltip.JSON file
        private void OpenToolTipFile(string toolTipFilename)
        {
            if (CheckFileExists(toolTipFilename))
            {
                using (StreamReader r = new StreamReader(toolTipFilename))
                {
                    string json = r.ReadToEnd();

                    json = ReplaceStringWithDict(json);
                    try
                    {
                        arrayJSONToolTips = Newtonsoft.Json.JsonConvert.DeserializeObject(json);
                    }
                    catch (JsonReaderException ex)
                    {
                        ModernWpf.MessageBox.Show("ERROR! in JSON file: " + toolTipFilename + ": " + ex.Message);
                    }
                }

                for (int i = 0; i < listSections.Count; i++)
                {
                    listSections[i].ToolTipString = ReturnToolTipString(listStringSectionsNames[i]);
                }
            }
        }

        // Function: return ToolTip string using region
        private string ReturnToolTipString(string region)
        {
            string o = "";

            foreach (var item in arrayJSONToolTips)
            {
                try
                {
                    int argCount = 0;

                    if (item.Region == region)
                    {
                        // Count number of Arg
                        foreach (var i in item.Arg)
                        {
                            argCount += 1;
                        }

                        if (argCount == 1)
                        {
                            if (item.ToolTip == null)
                            {
                                o += item.Function.ToString() + ";" + item.Arg.Zero.ToolTip.ToString() + ";";
                            }
                            else
                            {
                                o += item.Function + ";" + item.ToolTip + ";";
                            }
                        }
                        else if (argCount == 2)
                        {
                            if (item.ToolTip == null)
                            {
                                o += item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Arg.Zero.ToolTip + ";";
                                if (item.Arg.One.Tag == "")
                                {
                                    o += item.Function + ";" + item.Arg.One.ToolTip + ";";
                                }
                                else
                                {
                                    o += item.Function + " -" + item.Arg.One.Tag + ";" + item.Arg.One.ToolTip + ";";
                                }
                            }
                            else
                            {
                                o += item.Function + ";" + item.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Arg.Zero.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.One.Tag + ";" + item.Arg.One.ToolTip + ";";
                            }
                        }

                        else if (argCount == 3)
                        {
                            if (item.ToolTip == null)
                            {
                                o += item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Arg.Zero.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.One.Tag + ";" + item.Arg.One.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Two.Tag + ";" + item.Arg.Two.ToolTip + ";";
                            }
                            else // Has ToolTip on cmbItem
                            {
                                o += item.Function + ";" + item.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Arg.Zero.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.One.Tag + ";" + item.Arg.One.ToolTip + ";";
