                                o += item.Function + " -" + item.Arg.Six.Tag + ";" + item.Arg.Six.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Seven.Tag + ";" + item.Arg.Seven.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Eight.Tag + ";" + item.Arg.Eight.ToolTip + ";";
                            }
                            else // Has ToolTip on cmbItem
                            {
                                o += item.Function + ";" + item.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Arg.Zero.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.One.Tag + ";" + item.Arg.One.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Two.Tag + ";" + item.Arg.Two.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Three.Tag + ";" + item.Arg.Three.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Four.Tag + ";" + item.Arg.Four.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Five.Tag + ";" + item.Arg.Five.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Six.Tag + ";" + item.Arg.Six.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Seven.Tag + ";" + item.Arg.Seven.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Eight.Tag + ";" + item.Arg.Eight.ToolTip + ";";
                            }
                        }
                        else if (argCount == 10)
                        {
                            if (item.ToolTip == null)
                            {
                                o += item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Arg.Zero.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.One.Tag + ";" + item.Arg.One.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Two.Tag + ";" + item.Arg.Two.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Three.Tag + ";" + item.Arg.Three.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Four.Tag + ";" + item.Arg.Four.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Five.Tag + ";" + item.Arg.Five.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Six.Tag + ";" + item.Arg.Six.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Seven.Tag + ";" + item.Arg.Seven.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Eight.Tag + ";" + item.Arg.Eight.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Nine.Tag + ";" + item.Arg.Nine.ToolTip + ";";
                            }
                            else // Has ToolTip on cmbItem
                            {
                                o += item.Function + ";" + item.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Zero.Tag + ";" + item.Arg.Zero.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.One.Tag + ";" + item.Arg.One.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Two.Tag + ";" + item.Arg.Two.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Three.Tag + ";" + item.Arg.Three.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Four.Tag + ";" + item.Arg.Four.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Five.Tag + ";" + item.Arg.Five.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Six.Tag + ";" + item.Arg.Six.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Seven.Tag + ";" + item.Arg.Seven.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Eight.Tag + ";" + item.Arg.Eight.ToolTip + ";";
                                o += item.Function + " -" + item.Arg.Nine.Tag + ";" + item.Arg.Nine.ToolTip + ";";
                            }
                        }
                    }
                }
                catch (Exception e)
                {
                    ModernWpf.MessageBox.Show(item.Function.ToString() + " error! " + e.Message);
                }
            }
            if (o != "")
            {
                o = o.Substring(0, o.Length - 1);
            }
            return o;
        }

        // Function: Make Tooltip list from all sections
        private void MakeToolTipListAllSections()
        {
            foreach (Section sec in listSections)
            {
                sec.MakeToolTipList();
            }
        }

        // Function: Make tooltip dict from all sections
        private void MakeToolTipDictAllSections()
        {
            foreach (Section sec in listSections)
            {
                sec.ListToDict();
            }
        }

        // Function: Add ToolTips to Controls
        private void AddToolTipToControls()
        {
            foreach (Section sec in listSections)
            {
                AddToolTipCmb(sec.ComboBoxes, sec.ToolTipDict);
                AddToolTipChk(sec.CheckBoxes, sec.ToolTipDict);
                AddToolTipSChk(sec.DictStringListChk, sec.ToolTipDict);
            }
        }

        // Function: add tooltip to special checkboxes
        private void AddToolTipSChk(Dictionary<string, List<CheckBox>> schk, Dictionary<string, string> dct)
        {
            foreach (KeyValuePair<string, List<CheckBox>> entry in schk)
            {
                foreach (CheckBox chk in entry.Value)
                {
                    if (dct.ContainsKey(chk.Tag.ToString()))
                    {
                        ToolTip tt = new ToolTip();
                        tt.Content = chk.Tag.ToString() + ": " + dct[chk.Tag.ToString()];

                        chk.ToolTip = tt;

                        listAllToolTips.Add(tt);
                    }
                }
            }
        }

        // Function: add tooltip to checkboxes
        private void AddToolTipChk(List<CheckBox> chkList, Dictionary<string, string> dct)
        {
            foreach (CheckBox chk in chkList)
            {
                string sKey = chk.Tag.ToString();
                sKey = sKey.Substring(0, sKey.LastIndexOf(" "));

                if (dct.ContainsKey(sKey))
                {
                    ToolTip tt = new ToolTip();
                    tt.Content = sKey + ": " + dct[sKey];

                    chk.ToolTip = tt;

                    listAllToolTips.Add(tt);
                }
                else if (dct.ContainsKey(chk.Tag.ToString()))
                {
                    ToolTip tt = new ToolTip();
                    tt.Content = chk.Tag.ToString() + ": " + dct[chk.Tag.ToString()];

                    chk.ToolTip = tt;

                    listAllToolTips.Add(tt);
                }
            }
        }

        // Function: add tooltip to combobox
        private void AddToolTipCmb(List<ComboBox> cmbList, Dictionary<string, string> dct)
        {
            foreach (ComboBox cmb in cmbList)
            {
                foreach (ComboBoxItem it in cmb.Items)
                {
                    if (it.Tag != null)
                    {
                        if ((it.Tag.ToString() != sSkip) & (it.Tag.ToString() != ""))
                        {
                            if (dct.ContainsKey(it.Tag.ToString()))
                            {
                                ToolTip tt = new ToolTip();
                                tt.Content = it.Tag.ToString() + ": " + dct[it.Tag.ToString()];

                                //it.ToolTip = "";
                                it.ToolTip = tt;//it.Tag.ToString() + ": " + dct[it.Tag.ToString()];

                                listAllToolTips.Add(tt);

                                // Rolaids

                                //if (it.Tag.ToString().Contains("DNS"))
                                // {
                                //    ModernWpf.MessageBox.Show(it.Tag.ToString());
                                // }
                            }
                        }
                    }
                }
            }
        }

