        // Function: Get SS Versions from Online GitHub
        private void GetSSVersionsFromOnlineGitHub()
        {
            // Create Web Request from GitHub JSON
            var webRequest = WebRequest.Create(urlSophiaScriptReleasesJson);

            // Try ... Catch
            try
            {
                // Online
                var response = webRequest.GetResponse();
                var content = response.GetResponseStream();
                var reader = new StreamReader(content);

                string json = reader.ReadToEnd();
                arrayJSONSSReleasesFromGitHub = Newtonsoft.Json.JsonConvert.DeserializeObject(json);

                SSWin10PS51VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_10).ToString();
                SSWin10PS7VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_10).ToString();
                SSWin10LTSC2019VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_10_LTSC_2019).ToString();
                SSWin10LTSC2021VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_10_LTSC_2021).ToString();
                SSWin11LTSC2024PS51VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_11_LTSC_2024).ToString();
                SSWin11LTSC2024PS7VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_11_LTSC_2024).ToString();
                SSWin11PS51VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_11).ToString();
                SSWin11PS7VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_11).ToString();
                SSWin11ARMPS51VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_11).ToString();
                SSWin11ARMPS7VersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Windows_11).ToString();
                SSWVersionFromGitHub = (arrayJSONSSReleasesFromGitHub.Sophia_Script_Wrapper).ToString();
            }
            catch (System.Net.WebException ex)
            {
                // Do nothing and continue when there is no Internet connection               
            }
            catch (Exception ex)
            {
                ModernWpf.MessageBox.Show("ERROR! in JSON file on: " + urlSophiaScriptReleasesJson + ": " + ex.Message);
            }
        }

