        // Function: Compare SSW Version
        private void CompareSSWVersionFromLocalToOnlineAndSetGlobalBooleanVariableForWrapperToRun()
        {
            // Default global variable boolSSWVersionGood to true to run if no internet connection
            boolSSWVersionGood = true;

            // Try ... Catch
            try
            {
                var versionSSWVersionEXE = new Version(SSWVersion); // Version from local EXE
                var versionSSWVersionJSON = new Version(); // Version from Web

                // If Web version of Wrapper is not empty, create Versioning
                if (SSWVersionFromGitHub != "")
                {
                    versionSSWVersionJSON = new Version(SSWVersionFromGitHub);
                }

                // Compare Local and Web
                var resultCompareToVersion = versionSSWVersionJSON.CompareTo(versionSSWVersionEXE);

                // The version on GitHub is same as local version
                if (resultCompareToVersion == 0)
                {
                    // Global variable boolSSWVersionGood is set tp true so ok to run
                    boolSSWVersionGood = true;
                }
                // GitHub version is greater
                else if (resultCompareToVersion > 0)
                {
                    // boolSSWVersionGood is set to false so no good to run Wrapper 
                    boolSSWVersionGood = false;

                    // Ask user to go to GitHub and download latest Wrapper
                    MessageBoxResult result = (MessageBoxResult)ModernWpf.MessageBox.Show(messageBoxNewWrapperFound, "", MessageBoxButton.YesNo);
                    // Yes go to URL
                    if (result == MessageBoxResult.Yes)
                    {
                        string target = urlLatestSophiaScriptDownloads;
                        Process.Start("explorer.exe", target);
                        System.Windows.Application.Current.Shutdown();
                    }
                    // No shutdown Wrapper
                    else if (result == MessageBoxResult.No)
                    {
                        // No code here
                        System.Windows.Application.Current.Shutdown();
                    }
                    // Else shutdown Wrapper
                    else
                    {
                        // Cancel code here
                        System.Windows.Application.Current.Shutdown();
                    }
                }
                // Local copy is good
                else
                {
                    boolSSWVersionGood = true;
                }
            }
            // Could not connect to the Internet to check so proceed good
            catch (System.Net.WebException ex)
            {
                // Do nothing and continue
            }
        }

        // Function: Check LTSC SS Version
        private bool LTSCCheckVersion()
        {
            bool go = true;

            try
            {
                // Online
                string stringHolder = ""; ;

                string firstFind = "Supports Windows ";

                string onlineWin10LTSCSSVersionLoaded2019 = SSWin10LTSC2019VersionFromGitHub;
                string onlineWin10LTSCSSVersionLoaded2021 = SSWin10LTSC2021VersionFromGitHub;
                string onlineWin11LTSCSSVersionLoaded2024PS51 = SSWin11LTSC2024PS51VersionFromGitHub;
                string onlineWin11LTSCSSVersionLoaded2024PS7 = SSWin11LTSC2024PS7VersionFromGitHub;

                //if (onlineWin11LTSCSSVersionLoaded2024PS51 != "")
                if (true)
                {
                    // Local
                    //string fileToFind = parentFolder + "\\" + pathPsd1Filename;
                    string fileToFind = parentFolder + "\\" + folderPsm1Filename + "\\" + psm1Filename;

                    stringHolder = System.IO.File.ReadAllText(fileToFind);

                    int firstFindLength = firstFind.Length;
                    int ssBegin = 0;
                    int ssEnd = 0;

                    ssBegin = stringHolder.IndexOf(firstFind) + firstFindLength;
                    ssEnd = stringHolder.IndexOf("\n", ssBegin + 1);

                    int ssLength = ssEnd - ssBegin;

                    SSVersionLoaded = stringHolder.Substring(ssBegin, ssLength);

                    SSVersionLoaded = SSVersionLoaded.Substring(SSVersionLoaded.LastIndexOf(" ")).Trim();

                    LTSCversionLoaded = "ltsc" + SSVersionLoaded;

                    LTSCversionLoaded = LTSCversionLoaded.Trim();
                    //ModernWpf.MessageBox.Show("LTSC:" + LTSCversion);

                    // Check 2019 or 2021 or 2024 boolLTSC
                    //if (LTSCYearImported == "2024")
                    //{
                    //    LTSC2019or2021or2024 = "ltsc2024";
                    //}
                    //else if (LTSCYearImported == "2021")
                    //{
                    //    LTSC2019or2021or2024 = "ltsc2021";
                    //}
                    //else
                    //{
                    //    LTSC2019or2021or2024 = "ltsc2019";
                    //}
                    //if (new Version(LTSCversion) > new Version(LTSCversionToCompareBetween2021and2024))
                    //{
                    //    LTSC2019or2021or2024 = "ltsc2024";
                    //}
                    //else if (new Version(LTSCversion) > new Version(LTSCversionToCompareBetween2019and2021))
                    //{
                    //    LTSC2019or2021or2024 = "ltsc2021";
                    //}
                    //else
                    //{
                    //    LTSC2019or2021or2024 = "ltsc2019";
                    //}

                    //// Set global windowsOSVersion (Windows Version)
                    //int ssversionComparison = "6".CompareTo(SSVersionLoaded);
                    //if (ssversionComparison < 0)
                    //{
                    //    windowsOSVersion = "win11";
                    //}
                    //else
                    //{
                    //    windowsOSVersion = "win10";
                    //}

                    fileToFind = parentFolder + "\\" + folderPsd1Filename + "\\" + psd1Filename;

                    stringHolder = System.IO.File.ReadAllText(fileToFind);


                    // Find SS Version
                    string mVFind = "ModuleVersion         = '";

                    int mVFindLength = mVFind.Length;
                    int mVBegin = 0;
                    int mVEnd = 0;

                    mVBegin = stringHolder.IndexOf(mVFind) + mVFindLength;
                    mVEnd = stringHolder.IndexOf("'", mVBegin + 1);

                    int mVLength = mVEnd - mVBegin;

                    SSVersionLoaded = stringHolder.Substring(mVBegin, mVLength);


                    // Find PowerShell Version
                    string psFind = "PowerShellVersion     = '";

                    int psFindLength = psFind.Length;
                    int psBegin = 0;
                    int psEnd = 0;

                    psBegin = stringHolder.IndexOf(psFind) + psFindLength;
                    psEnd = stringHolder.IndexOf("'", psBegin + 1);

                    int psLength = psEnd - psBegin;

                    powerShellVersionLoaded = stringHolder.Substring(psBegin, psLength);
                    //ModernWpf.MessageBox.Show(LTSCversion);
                    //ModernWpf.MessageBox.Show(powerShellVersion);


                    // COMPARE
                    var compareLinguistic = 0;

                    if (onlineWin11LTSCSSVersionLoaded2024PS51 != "")
                    {
                        if (LTSCversionLoaded == "ltsc2019")
                        {
                            compareLinguistic = new Version(onlineWin10LTSCSSVersionLoaded2019).CompareTo(new Version(SSVersionLoaded));
                        }
                        if (LTSCversionLoaded == "ltsc2021")
                        {
                            compareLinguistic = new Version(onlineWin10LTSCSSVersionLoaded2021).CompareTo(new Version(SSVersionLoaded));
                        }
                        if ((LTSCversionLoaded == "ltsc2024") & (double.Parse(powerShellVersionLoaded) >= 7.0))
                        {
                            //ModernWpf.MessageBox.Show(compareLinguistic.ToString());
                            compareLinguistic = new Version(onlineWin11LTSCSSVersionLoaded2024PS7).CompareTo(new Version(SSVersionLoaded));
                        }
                        else if ((LTSCversionLoaded == "ltsc2024") & (double.Parse(powerShellVersionLoaded) >= 5.1))
                        {
                            //ModernWpf.MessageBox.Show(compareLinguistic.ToString());
                            compareLinguistic = new Version(onlineWin11LTSCSSVersionLoaded2024PS51).CompareTo(new Version(SSVersionLoaded));
                        }

                        if (compareLinguistic == 0)
                        {
                            //The version on GitHub is same as local
                            go = true;
                        }
                        else if (compareLinguistic > 0)
                        {
                            //Github version is greater                
                            MessageBoxResult result = (MessageBoxResult)ModernWpf.MessageBox.Show(messageBoxNewSophiaFound, "", MessageBoxButton.YesNoCancel);
                            if (result == MessageBoxResult.Yes)
                            {
                                string target = urlLatestSophiaScriptDownloads;
                                Process.Start("explorer.exe", target);
                                go = false;
                            }
                            else if (result == MessageBoxResult.No)
                            {
                                // No code here
                                go = false;
                            }
                            else
                            {
                                // Cancel code here
                                go = false;
                            }
                        }
                        else
                        {
                            go = true;
                        }
                    }
                    else
                    {
                        go = true;
                    }
                }
                else
                {
                    go = true;
                }
            }
            catch (System.Net.WebException exception)
            {
                // Do nothing and continue
            }




            return go;

        }

