        // Function: Script version ASYNC
        private async System.Threading.Tasks.Task<bool> SSCheckVersionAsync()
        {
            string fileToFind = parentFolder + "\\" + pathPsd1Filename;

            string stringHolder = "";

            //ModernWpf.MessageBox.Show(CheckFileExists(fileToFind).ToString());
            //Check for file exist and exit of using older
            if (!CheckFileExists(fileToFind))
            {
                MessageBoxResult result = (MessageBoxResult)ModernWpf.MessageBox.Show(messageBoxNewSophiaFound, "", MessageBoxButton.YesNoCancel);
                if (result == MessageBoxResult.Yes)
                {
                    string target = urlLatestSophiaScriptDownloads;
                    Process.Start("explorer.exe", target);
                }
                else if (result == MessageBoxResult.No)
                {
                    // No code here
                }
                return false;
            }

            stringHolder = System.IO.File.ReadAllText(fileToFind);

            string firstFind = "ModuleVersion         = '";

            int firstFindLength = firstFind.Length;
            int ssBegin = 0;
            int ssEnd = 0;

            ssBegin = stringHolder.IndexOf(firstFind) + firstFindLength;
            ssEnd = stringHolder.IndexOf("'", ssBegin + 1);

            int ssLength = ssEnd - ssBegin;

            SSVersionLoaded = stringHolder.Substring(ssBegin, ssLength);

            //ModernWpf.MessageBox.Show(SSVersionLoaded);

            ////Set global windowsOSVersion (Windows Version)
            //int SSVersionComparison = "6".CompareTo(SSVersionLoaded);
            //if (SSVersionComparison < 0)
            //{
            //    windowsOSVersion = "win11";
            //}
            //else
            //{
            //    windowsOSVersion = "win10";
            //}

            // Find PowerShell Version
            string psFind = "PowerShellVersion     = '";

            int psFindLength = psFind.Length;
            int psBegin = 0;
            int psEnd = 0;

            psBegin = stringHolder.IndexOf(psFind) + psFindLength;
            psEnd = stringHolder.IndexOf("'", psBegin + 1);

            int psLength = psEnd - psBegin;

            powerShellVersionLoaded = stringHolder.Substring(psBegin, psLength);

            //ModernWpf.MessageBox.Show(powerShellVersion);

            //Default go is true to run if no internet connection
            bool go = true;

            try
            {
                Version latestGitHubVersion = new Version("1.1");

                //ModernWpf.MessageBox.Show(latestGitHubVersion.ToString());

                //ModernWpf.MessageBox.Show(windowsOSVersion);

                //windowsOSVersion = "win10";

                if ((windowsOSVersion == "win10") & (CompareStrings(powerShellVersionLoaded, minPS7ver) >= 0))
                {
                    latestGitHubVersion = new Version(SSWin10PS7VersionFromGitHub);
                }
                else if ((windowsOSVersion == "win10") & (CompareStrings(powerShellVersionLoaded, minPS5ver) >= 0))
                {
                    latestGitHubVersion = new Version(SSWin10PS51VersionFromGitHub);

                    //ModernWpf.MessageBox.Show(SSWin10PS51VersionFromGitHub);
                }

                else if ((windowsOSVersion == "win11") & (CompareStrings(powerShellVersionLoaded, minPS7ver) >= 0) & (ARMLoaded == "yes"))
                {
                    latestGitHubVersion = new Version(SSWin11ARMPS7VersionFromGitHub);
                }
                else if ((windowsOSVersion == "win11") & (CompareStrings(powerShellVersionLoaded, minPS5ver) >= 0) & (ARMLoaded == "yes"))
                {
                    latestGitHubVersion = new Version(SSWin11ARMPS51VersionFromGitHub);
                }

                else if ((windowsOSVersion == "win11") & (CompareStrings(powerShellVersionLoaded, minPS7ver) >= 0))
                {
                    latestGitHubVersion = new Version(SSWin11PS7VersionFromGitHub);
                }
                else if ((windowsOSVersion == "win11") & (CompareStrings(powerShellVersionLoaded, minPS5ver) >= 0))
                {
                    latestGitHubVersion = new Version(SSWin11PS51VersionFromGitHub);
                }

                Version localVersion = new Version(SSVersionLoaded); //Replace this with your local version. 
                                                                     //Only tested with numeric values.

                //Compare the Versions
                //Source: https://stackoverflow.com/questions/7568147/compare-version-numbers-without-using-split-function
                int versionComparison = localVersion.CompareTo(latestGitHubVersion);
                if (versionComparison < 0)
                {
                    //The version on GitHub is more up to date than this local release.
                    MessageBoxResult result = (MessageBoxResult)ModernWpf.MessageBox.Show(messageBoxNewSophiaFound, "", MessageBoxButton.YesNoCancel);
                    if (result == MessageBoxResult.Yes)
                    {
                        string target = urlLatestSophiaScriptDownloads;
                        Process.Start("explorer.exe", target);
                    }
                    else if (result == MessageBoxResult.No)
                    {
                        // No code here
                    }
                    go = false;
                }
                else if (versionComparison > 0)
                {
                    //This local version is greater than the release version on GitHub.                    
                    go = true;
                    //ModernWpf.MessageBox.Show("Local newer");
                }
                else
                {
                    //This local Version and the Version on GitHub are equal.                    
                    go = true;
                    //ModernWpf.MessageBox.Show("Github same");
                }
            }
            catch
            {

            }

            return go;
        }

