        // Function: Export Menu 
        private void ExportMenu_Click(object sender, RoutedEventArgs e)
        {
            // output PowerShell clicking Export
            OutputPowerShell_Click(new object(), new RoutedEventArgs());

            string fileText = tboxOutput.Text;

            SaveFileDialog dialog = new SaveFileDialog()
            {
                Filter = "PowerShell Scripts(*.ps1)|*.ps1"
            };

            if (dialog.ShowDialog() == true)
            {
                ps1Filename = dialog.FileName;

                ////Write to file Encoding different                
                //if (CompareStrings(powerShellVersion, minPS7ver) >= 0)
                //{
                //    // UTF8
                //    File.WriteAllText(ps1Filename, fileText);
                //}
                //else if (CompareStrings(powerShellVersion, minPS5ver) >= 0)
                //{
                //    // UTF with BOM
                //    using (var sw = new StreamWriter(ps1Filename, false, new UTF8Encoding(true)))
                //    {
                //        sw.WriteLine(fileText);
                //    }
                //}

                // Write to File
                WriteToFile(ps1Filename, fileText);

                tblckStatusBarMessage.Text = ps1Filename + " " + statusBarPowerShellExport;
                //tblckStatusBarMessage.ToolTip = 


                ToolTip newToolTip = new ToolTip();
                newToolTip.Content = ps1Filename + " " + statusBarPowerShellExport;

                tblckStatusBarMessage.ToolTip = newToolTip;

                listAllToolTips.Add(newToolTip);
            }
        }

        // Function: Autosave menu click turn off and on timer for autosave based on menu
        private void AutosaveMenu_Click(object sender, RoutedEventArgs e)
        {
            // menu autosave on
            if (menuAutosave.IsChecked == true)
            {
                // timer on
                autoSaveTimer.IsEnabled = true;
                // Change Wrapper theme
                ChangeWrapperThemeBasedOnGlobal();
            }
            // menu autosave off
            else if (menuAutosave.IsChecked == false)
            {
                // timer off
                autoSaveTimer.IsEnabled = false;
                // Change Wrapper theme
                ChangeWrapperThemeBasedOnGlobal();
            }
        }

        // Function: Sophia Preset menu click
        private void SophiaPreset_Click(object sender, RoutedEventArgs e)
        {
            Clear();

            // LTSC version
            if (boolLTSC == true)
            {
                CreateAllTabsRefresh("ltsc", windowsOSVersion);
            }
            // Normal
            else
            {
                CreateAllTabsRefresh("default", windowsOSVersion);
            }

            SelectListAllSectionsFromPreset("SophiaPreset");

            // Special
            MakeSelectDictListAllSections();

            // Select
            SelectControlsFromPresetSelectList();

            // Disable UWP
            LoadPresetCheckUWPChk();

            // Add Tooltips to controls
            ChangeToolTipsTagsUIForCurrentLanguage();

            // OutputPowerShell
            OutputPowerShell_Click(new object(), new RoutedEventArgs());

            tblckStatusBarMessage.Text = statusBarSophiaPreset;
            //tblckStatusBarMessage.ToolTip = statusBarSophiaPreset;

            ToolTip newToolTip = new ToolTip();
            newToolTip.Content = statusBarSophiaPreset;

            tblckStatusBarMessage.ToolTip = newToolTip;

            listAllToolTips.Add(newToolTip);

        }

