        // Function: Dark menu option
        private void DarkMenu_Click(object sender, RoutedEventArgs e)
        {
            currentSelectedTheme = "dark";
            ThemeManager.Current.ApplicationTheme = ApplicationTheme.Dark;

            SSWTabControl.Background = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#FF03253d"));
            tboxOutput.Background = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#FF000000"));
            tboxOutput.Foreground = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#FFFFFFFF"));

            btnRefreshConsoleOutputPowerShell.Background = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#04253d"));
            btnRunPowerShell.Background = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#04253d"));

            menuImportPreset.Foreground = System.Windows.Media.Brushes.White;
            menuImportExportPreset.Foreground = System.Windows.Media.Brushes.White;

            menuAutosave.Foreground = System.Windows.Media.Brushes.White;

            EnableDisableTabs_ChangeTabHeaderColours();
        }

        // Function: Light menu option
        private void LightMenu_Click(object sender, RoutedEventArgs e)
        {
            currentSelectedTheme = "light";
            ThemeManager.Current.ApplicationTheme = ApplicationTheme.Light;

            SSWTabControl.Background = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#FFFFFFFF"));
            tboxOutput.Background = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#FFFFFFFF"));
            tboxOutput.Foreground = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#FF000000"));

            btnRefreshConsoleOutputPowerShell.Background = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#FFa8d5ec"));
            btnRunPowerShell.Background = (System.Windows.Media.Brush)(new BrushConverter().ConvertFrom("#FFa8d5ec"));

            menuImportPreset.Foreground = System.Windows.Media.Brushes.White;
            menuImportExportPreset.Foreground = System.Windows.Media.Brushes.White;

            if (autoSaveTimer.IsEnabled == true) // Mozilla
            {
                menuAutosave.Foreground = System.Windows.Media.Brushes.White;
            }
            else
            {
                menuAutosave.Foreground = System.Windows.Media.Brushes.Black;
            }

            EnableDisableTabs_ChangeTabHeaderColours();
        }

