        // Function: Menu color for Import and Export on Submenu Opened
        private void ImportExportMenuForegroundColor_SubmenuOpened(object sender, RoutedEventArgs e)
        {
            if (currentSelectedTheme == "dark")
            {
                menuImportExportPreset.Foreground = System.Windows.Media.Brushes.White;
            }
            else
            {
                menuImportExportPreset.Foreground = System.Windows.Media.Brushes.Black;
            }
        }

        // Function: Menu color for Import and Export on Submenu Closed
        private void ImportExportMenuForegroundColor_SubmenuClosed(object sender, RoutedEventArgs e)
        {
            menuImportExportPreset.Foreground = System.Windows.Media.Brushes.White;
        }

        // Function: Menu color for Import and Export on Mouse Enter
        private void ImportExportMenuForegroundColor_MouseEnter(object sender, MouseEventArgs e)
        {
            if (currentSelectedTheme == "dark")
            {
                menuImportExportPreset.Foreground = System.Windows.Media.Brushes.White;
            }
            else
            {
                menuImportExportPreset.Foreground = System.Windows.Media.Brushes.Black;
            }
        }

        // Function: Menu color for Import and Export on Mouse Leave
        private void ImportExportMenuForegroundColor_MouseLeave(object sender, MouseEventArgs e)
        {
            if (currentSelectedTheme == "dark")
            {
                menuImportExportPreset.Foreground = System.Windows.Media.Brushes.White;
            }
            else if ((currentSelectedTheme == "light") & (menuImportExportPreset.IsSubmenuOpen))
            {
                menuImportExportPreset.Foreground = System.Windows.Media.Brushes.Black;
            }
            else if ((currentSelectedTheme == "light") & (!menuImportExportPreset.IsSubmenuOpen))
            {
                menuImportExportPreset.Foreground = System.Windows.Media.Brushes.White;
            }
        }

        // Function: Select Opposite PESC
        private void SelectOppositePESC(Dictionary<string, List<CheckBox>> dictsc)
        {
            foreach (KeyValuePair<string, List<CheckBox>> entry in dictsc)
            {
                foreach (CheckBox chk in entry.Value)
                {
                    if (chk.IsChecked == true)
                    {
                        chk.IsChecked = false;
                    }
                    else if (chk.IsChecked == false)
                    {
                        chk.IsChecked = true;
                    }
                }
            }
        }

